app std-algo-bubblesort "2.0.0"
"Algorithm-animation engine (algorithm-canvas): Bubble-sort visualizer — each step performs one adjacent compare-or-swap micro-step over a bar array, with pointers on the compared pair and a fill range over the sorted suffix. The Step/Run-Pause/Reset transport and the step clock come from the std-learn-transport atom (BubbleSortTransport); the compare-or-swap logic lives in the sibling BubbleSortSim trait, which transitions directly on the transport's LEARN_STEP (applies one compare-or-swap micro-step), LEARN_RESET (reseeds bars from config), and LEARN_UPDATED (full-shell repaint) broadcasts — delivered by the same bare-event cascade the lab routers use — and owns the full-shell scene render (the transport strip is embedded via @trait.BubbleSortTransport — one render authority per shared entity). Standalone by default; behind a lab router set matchMode and it renders only when MODE_SELECTED matches."
orbital BubbleSortEngineOrbital {
  type AlgoBar = {
    value : number!
    color : string
    label : string
  }
  type AlgoPointer = {
    index : number!
    label : string
    color : string
  }
  type AlgoRange = {
    from : number!
    to : number!
    kind : "fill" | "bracket"
    label : string
    color : string
  }

  entity BubbleScene [runtime, shared] {
    id : string!
    active : boolean = false
    title : string
    running : boolean = false
    steps : int = 0
    elapsedMs : number = 0
    done : boolean = false
    bars : [AlgoBar]
    i : number = 0
    n : number = 0
    pass : boolean = false
    pointers : [AlgoPointer]
    ranges : [AlgoRange]
    narration : string
  }

  uses LearnTransport from "std/behaviors/std-learn-transport"

  trait BubbleSortTransport = LearnTransport.traits.LearnTransportSim -> BubbleScene {
    config {
      title: "Bubble Sort"
      stepIntervalMs: 300
    }
  }

  trait BubbleSortSim -> @rebindable BubbleScene [interaction, instance] {
    initial: idle

    state idle {
      INIT -> idle when (== @config.matchMode "")
        (set @entity.bars (array/map @config.values { value: @item, label: (str/concat "" @item), color: "#3b82f6" }))
        (set @entity.n (array/len @config.values))
        (set @entity.i 0)
        (set @entity.pass false)
        (set @entity.done (<= (array/len @config.values) 1))
        (set @entity.pointers [ { index: 0, label: "j" }, { index: 1, label: "j+1" } ])
        (set @entity.ranges [])
        (set @entity.narration "press Step to compare the first pair")
        (render-ui main {
          type: box
          padding: md
          children: [
            { type: stack, direction: vertical, gap: md, children: [
                @trait.BubbleSortTransport,
                { type: algorithm-canvas, width: @config.width, height: @config.height, backgroundColor: @config.backgroundColor, bars: @entity.bars, pointers: @entity.pointers, ranges: @entity.ranges },
                { type: typography, variant: body, content: @entity.narration }
              ] }
          ]
        })
        (emit BUBBLESORT_UPDATED { bars: @entity.bars, pointers: @entity.pointers, ranges: @entity.ranges, narration: @entity.narration })

      MODE_SELECTED -> idle when (== ?mode @config.matchMode)
        (set @entity.bars (array/map @config.values { value: @item, label: (str/concat "" @item), color: "#3b82f6" }))
        (set @entity.n (array/len @config.values))
        (set @entity.i 0)
        (set @entity.pass false)
        (set @entity.done (<= (array/len @config.values) 1))
        (set @entity.pointers [ { index: 0, label: "j" }, { index: 1, label: "j+1" } ])
        (set @entity.ranges [])
        (set @entity.narration "press Step to compare the first pair")
        (render-ui main {
          type: box
          padding: md
          children: [
            { type: stack, direction: vertical, gap: md, children: [
                @trait.BubbleSortTransport,
                { type: algorithm-canvas, width: @config.width, height: @config.height, backgroundColor: @config.backgroundColor, bars: @entity.bars, pointers: @entity.pointers, ranges: @entity.ranges },
                { type: typography, variant: body, content: @entity.narration }
              ] }
          ]
        })
        (emit BUBBLESORT_UPDATED { bars: @entity.bars, pointers: @entity.pointers, ranges: @entity.ranges, narration: @entity.narration })

      LEARN_STEP -> idle when (and (== @entity.active true) (not (== @entity.done true)))
        (let (
            (a (array/nth @entity.bars @entity.i))
            (b (array/nth @entity.bars (+ @entity.i 1)))
            (aVal (object/get @a value))
            (bVal (object/get @b value))
            (swap (> @aVal @bVal))
            (pass (>= @entity.i (- @entity.n 2)))
            (done (and @pass (<= @entity.n 1)))
            (newN (if @pass (- @entity.n 1) @entity.n))
            (newI (if @pass 0 (+ @entity.i 1)))
          )
          (do
            (set @entity.bars (array/map @entity.bars
              { value: (if (and @swap (== @index @entity.i)) @bVal (if (and @swap (== @index (+ @entity.i 1))) @aVal (object/get @item value)))
                label: (if (and @swap (== @index @entity.i)) (str/concat "" @bVal) (if (and @swap (== @index (+ @entity.i 1))) (str/concat "" @aVal) (object/get @item label)))
                color: (if @done "#22c55e"
                         (if (>= @index @entity.n) "#22c55e"
                           (if (or (== @index @entity.i) (== @index (+ @entity.i 1))) "#f59e0b" "#3b82f6")))
              }))
            (set @entity.pass @pass)
            (set @entity.done @done)
            (set @entity.n @newN)
            (set @entity.i @newI)
            (set @entity.narration (if @done "sorted!" (if @swap (str/concat "swap " @aVal " and " @bVal) (str/concat "compare " @aVal " and " @bVal " — no swap"))))
            (set @entity.pointers (if @done [] [ { index: @newI, label: "j" }, { index: (+ @newI 1), label: "j+1" } ]))
            (set @entity.ranges (if @done [] (if (< @newN (array/len @entity.bars)) [ { from: @newN, to: (- (array/len @entity.bars) 1), kind: "fill", label: "sorted" } ] [])))
          ))
        (render-ui main {
          type: box
          padding: md
          children: [
            { type: stack, direction: vertical, gap: md, children: [
                @trait.BubbleSortTransport,
                { type: algorithm-canvas, width: @config.width, height: @config.height, backgroundColor: @config.backgroundColor, bars: @entity.bars, pointers: @entity.pointers, ranges: @entity.ranges },
                { type: typography, variant: body, content: @entity.narration }
              ] }
          ]
        })
        (emit BUBBLESORT_UPDATED { bars: @entity.bars, pointers: @entity.pointers, ranges: @entity.ranges, narration: @entity.narration })

      LEARN_RESET -> idle when (== @entity.active true)
        (set @entity.bars (array/map @config.values { value: @item, label: (str/concat "" @item), color: "#3b82f6" }))
        (set @entity.n (array/len @config.values))
        (set @entity.i 0)
        (set @entity.pass false)
        (set @entity.done (<= (array/len @config.values) 1))
        (set @entity.pointers [ { index: 0, label: "j" }, { index: 1, label: "j+1" } ])
        (set @entity.ranges [])
        (set @entity.narration "press Step to compare the first pair")
        (render-ui main {
          type: box
          padding: md
          children: [
            { type: stack, direction: vertical, gap: md, children: [
                @trait.BubbleSortTransport,
                { type: algorithm-canvas, width: @config.width, height: @config.height, backgroundColor: @config.backgroundColor, bars: @entity.bars, pointers: @entity.pointers, ranges: @entity.ranges },
                { type: typography, variant: body, content: @entity.narration }
              ] }
          ]
        })
        (emit BUBBLESORT_UPDATED { bars: @entity.bars, pointers: @entity.pointers, ranges: @entity.ranges, narration: @entity.narration })

      LEARN_UPDATED -> idle when (== @entity.active true)
        (render-ui main {
          type: box
          padding: md
          children: [
            { type: stack, direction: vertical, gap: md, children: [
                @trait.BubbleSortTransport,
                { type: algorithm-canvas, width: @config.width, height: @config.height, backgroundColor: @config.backgroundColor, bars: @entity.bars, pointers: @entity.pointers, ranges: @entity.ranges },
                { type: typography, variant: body, content: @entity.narration }
              ] }
          ]
        })
    }

    listens {
      BubbleSortTransport.LEARN_RESET -> LEARN_RESET
      BubbleSortTransport.LEARN_STEP -> LEARN_STEP
      BubbleSortTransport.LEARN_UPDATED -> LEARN_UPDATED
      MODE_SELECTED {
        mode : string
      }
        @description "Lab router broadcast naming the active mode; this instrument renders when the mode equals matchMode, otherwise renders null."
        @tier "domain"
      LEARN_STEP {
        steps : int
      }
        @description "One step of the transport clock or Step button (from the composed std-learn-transport trait); applies one adjacent compare-or-swap micro-step."
        @tier "domain"
      LEARN_RESET {
      }
        @description "Transport Reset broadcast (from the composed std-learn-transport trait); reseeds the bar array, pointers, and narration from config."
        @tier "domain"
      LEARN_UPDATED {
        running : boolean
        steps : int
      }
        @description "Transport state broadcast on load and Run/Pause toggle (from the composed std-learn-transport trait); repaints the full shell so the canvas and narration stay fresh."
        @tier "domain"
    }

    emits {
      BUBBLESORT_UPDATED -> external {
        bars : [AlgoBar]
        pointers : [AlgoPointer]
        ranges : [AlgoRange]
        narration : string
      }
        @description "The bar array, pointers, ranges and narration after each step/toggle/reset — a composed listener (a mirror canvas, a readout) can subscribe; a harmless no-op standalone."
        @synonyms "tick, frame, step, redraw, compare, swap, bubble sort"
        @tier "domain"
    }

    config {
      matchMode : string = ""
        @label "Match Mode"
        @description "When composed behind a lab router, the MODE_SELECTED mode value this instrument responds to. Empty string means standalone — render immediately on INIT."
        @tier "presentation"
      width : number = 600
        @label "Width"
        @description "Canvas width in pixels."
        @tier "presentation"
      height : number = 400
        @label "Height"
        @description "Canvas height in pixels."
        @tier "presentation"
      backgroundColor : string = "#f8fafc"
        @label "Background Color"
        @description "Canvas background color."
        @tier "presentation"
      values : [number] = [5, 2, 8, 1, 9, 3, 7, 4]
        @label "Values"
        @description "Initial unsorted dataset; each bar's height is proportional to its value."
        @tier "presentation"
    }
  }

  page "/algo-bubblesort" as BubbleSortEnginePage -> BubbleSortTransport, BubbleSortSim
}

app std-algo-bfs "2.0.0"
"Breadth-first search visualizer — an algo-graph-canvas (circle layout) recolours nodes unvisited→frontier→current→visited as each step dequeues the queue head and enqueues its unseen neighbours (discovery edges marked tree); a horizontal queue strip below the graph (algorithm-canvas slots, front pointer) mirrors the live FIFO order. The Step/Run-Pause/Reset transport and the step clock come from the std-learn-transport atom (BfsTransport); the BFS expansion lives in the sibling BfsSim trait, which transitions directly on the transport's LEARN_STEP (applies one dequeue-and-expand), LEARN_RESET (reseeds from the start node), and LEARN_UPDATED (full-shell repaint) broadcasts — delivered by the same bare-event cascade the lab routers use — and owns the full-shell scene render (the transport strip is embedded via @trait.BfsTransport — one render authority per shared entity). Standalone by default; behind a lab router set matchMode and it renders only when MODE_SELECTED matches."
orbital BfsEngineOrbital {
  type AlgoNode = {
    id : string!
    label : string
    state : "unvisited" | "frontier" | "current" | "visited" | "goal" | "path"
  }
  type AlgoEdge = {
    from : string!
    to : string!
    directed : boolean
    label : string
    state : "default" | "tree" | "relaxed" | "candidate" | "path"
  }
  type AlgoSlot = {
    value : string
    state : "empty" | "filled" | "highlight"
  }
  type AlgoPointer = {
    index : number!
    label : string
    color : string
  }

  entity BfsScene [runtime, shared] {
    id : string!
    active : boolean = false
    title : string
    running : boolean = false
    steps : int = 0
    elapsedMs : number = 0
    done : boolean = false
    nodes : [AlgoNode]
    edges : [AlgoEdge]
    queue : [string]
    seen : [string]
    visited : [string]
    cur : string = ""
    slots : [AlgoSlot]
    pointers : [AlgoPointer]
    narration : string
  }

  uses LearnTransport from "std/behaviors/std-learn-transport"

  trait BfsTransport = LearnTransport.traits.LearnTransportSim -> BfsScene {
    config {
      title: "Breadth-First Search"
      stepIntervalMs: 500
    }
  }

  trait BfsSim -> @rebindable BfsScene [interaction, instance] {
    initial: idle

    state idle {
      INIT -> idle when (== @config.matchMode "")
        (set @entity.edges @config.edges)
        (set @entity.queue [@config.start])
        (set @entity.seen [@config.start])
        (set @entity.visited [])
        (set @entity.cur "")
        (set @entity.done false)
        (set @entity.nodes (array/map @config.nodes (fn n
          (object/merge @n { state: (if (== (object/get @n id) @config.start) "frontier" "unvisited") }))))
        (set @entity.slots (array/map @config.queueSlots
          (if (== @index 0) { value: @config.start, state: "filled" } { state: "empty" })))
        (set @entity.pointers [ { index: 0, label: "front", color: "#2563eb" } ])
        (set @entity.narration (str/concat "start at " @config.start " — press Step to dequeue"))
        (render-ui main {
          type: box
          padding: md
          children: [
            { type: stack, direction: vertical, gap: md, children: [
                @trait.BfsTransport,
                { type: algo-graph-canvas, width: @config.width, height: @config.height, backgroundColor: @config.backgroundColor, layout: circle, nodes: @entity.nodes, edges: @entity.edges },
                { type: algorithm-canvas, width: @config.slotWidth, height: @config.slotHeight, backgroundColor: @config.backgroundColor, slots: @entity.slots, pointers: @entity.pointers },
                { type: typography, variant: body, content: @entity.narration }
              ] }
          ]
        })
        (emit NODES_UPDATED { nodes: @entity.nodes, edges: @entity.edges, queue: @entity.queue, visited: @entity.visited, narration: @entity.narration })

      MODE_SELECTED -> idle when (== ?mode @config.matchMode)
        (set @entity.edges @config.edges)
        (set @entity.queue [@config.start])
        (set @entity.seen [@config.start])
        (set @entity.visited [])
        (set @entity.cur "")
        (set @entity.done false)
        (set @entity.nodes (array/map @config.nodes (fn n
          (object/merge @n { state: (if (== (object/get @n id) @config.start) "frontier" "unvisited") }))))
        (set @entity.slots (array/map @config.queueSlots
          (if (== @index 0) { value: @config.start, state: "filled" } { state: "empty" })))
        (set @entity.pointers [ { index: 0, label: "front", color: "#2563eb" } ])
        (set @entity.narration (str/concat "start at " @config.start " — press Step to dequeue"))
        (render-ui main {
          type: box
          padding: md
          children: [
            { type: stack, direction: vertical, gap: md, children: [
                @trait.BfsTransport,
                { type: algo-graph-canvas, width: @config.width, height: @config.height, backgroundColor: @config.backgroundColor, layout: circle, nodes: @entity.nodes, edges: @entity.edges },
                { type: algorithm-canvas, width: @config.slotWidth, height: @config.slotHeight, backgroundColor: @config.backgroundColor, slots: @entity.slots, pointers: @entity.pointers },
                { type: typography, variant: body, content: @entity.narration }
              ] }
          ]
        })
        (emit NODES_UPDATED { nodes: @entity.nodes, edges: @entity.edges, queue: @entity.queue, visited: @entity.visited, narration: @entity.narration })

      LEARN_STEP -> idle when (and (== @entity.active true) (not (== @entity.done true)))
        (let (
            (u (array/first @entity.queue))
            (newIds (array/filter
                      (array/map
                        (array/filter @entity.edges (fn e (or (== (object/get @e from) @u) (== (object/get @e to) @u))))
                        (fn e (if (== (object/get @e from) @u) (object/get @e to) (object/get @e from))))
                      (fn nid (not (array/includes @entity.seen @nid)))))
          )
          (do
            (set @entity.cur @u)
            (set @entity.visited (array/append @entity.visited @u))
            (set @entity.seen (array/concat @entity.seen @newIds))
            (set @entity.queue (array/concat (array/drop @entity.queue 1) @newIds))
            (set @entity.done (== (array/len @entity.queue) 0))
            (set @entity.nodes (array/map @entity.nodes (fn n
              (object/merge @n {
                state: (if (== (object/get @n id) @u) "current"
                         (if (array/includes @entity.visited (object/get @n id)) "visited"
                           (if (array/includes @entity.seen (object/get @n id)) "frontier" "unvisited")))
              }))))
            (set @entity.edges (array/map @entity.edges (fn e
              (object/merge @e {
                state: (if (or (and (== (object/get @e from) @u) (array/includes @newIds (object/get @e to)))
                                (and (== (object/get @e to) @u) (array/includes @newIds (object/get @e from))))
                         "tree"
                         @e.state)
              }))))
            (set @entity.slots (array/map @config.queueSlots
              (if (< @index (array/len @entity.queue))
                { value: (array/nth @entity.queue @index), state: "filled" }
                { state: "empty" })))
            (set @entity.pointers (if (> (array/len @entity.queue) 0) [ { index: 0, label: "front", color: "#2563eb" } ] []))
            (set @entity.narration (if (> (array/len @newIds) 0)
              (str/concat "dequeue " @u " — enqueue " (str/join @newIds ", "))
              (str/concat "dequeue " @u " — no new neighbors")))
          ))
        (render-ui main {
          type: box
          padding: md
          children: [
            { type: stack, direction: vertical, gap: md, children: [
                @trait.BfsTransport,
                { type: algo-graph-canvas, width: @config.width, height: @config.height, backgroundColor: @config.backgroundColor, layout: circle, nodes: @entity.nodes, edges: @entity.edges },
                { type: algorithm-canvas, width: @config.slotWidth, height: @config.slotHeight, backgroundColor: @config.backgroundColor, slots: @entity.slots, pointers: @entity.pointers },
                { type: typography, variant: body, content: @entity.narration }
              ] }
          ]
        })
        (emit NODES_UPDATED { nodes: @entity.nodes, edges: @entity.edges, queue: @entity.queue, visited: @entity.visited, narration: @entity.narration })

      LEARN_RESET -> idle when (== @entity.active true)
        (set @entity.edges @config.edges)
        (set @entity.queue [@config.start])
        (set @entity.seen [@config.start])
        (set @entity.visited [])
        (set @entity.cur "")
        (set @entity.done false)
        (set @entity.nodes (array/map @config.nodes (fn n
          (object/merge @n { state: (if (== (object/get @n id) @config.start) "frontier" "unvisited") }))))
        (set @entity.slots (array/map @config.queueSlots
          (if (== @index 0) { value: @config.start, state: "filled" } { state: "empty" })))
        (set @entity.pointers [ { index: 0, label: "front", color: "#2563eb" } ])
        (set @entity.narration (str/concat "start at " @config.start " — press Step to dequeue"))
        (render-ui main {
          type: box
          padding: md
          children: [
            { type: stack, direction: vertical, gap: md, children: [
                @trait.BfsTransport,
                { type: algo-graph-canvas, width: @config.width, height: @config.height, backgroundColor: @config.backgroundColor, layout: circle, nodes: @entity.nodes, edges: @entity.edges },
                { type: algorithm-canvas, width: @config.slotWidth, height: @config.slotHeight, backgroundColor: @config.backgroundColor, slots: @entity.slots, pointers: @entity.pointers },
                { type: typography, variant: body, content: @entity.narration }
              ] }
          ]
        })
        (emit NODES_UPDATED { nodes: @entity.nodes, edges: @entity.edges, queue: @entity.queue, visited: @entity.visited, narration: @entity.narration })

      LEARN_UPDATED -> idle when (== @entity.active true)
        (render-ui main {
          type: box
          padding: md
          children: [
            { type: stack, direction: vertical, gap: md, children: [
                @trait.BfsTransport,
                { type: algo-graph-canvas, width: @config.width, height: @config.height, backgroundColor: @config.backgroundColor, layout: circle, nodes: @entity.nodes, edges: @entity.edges },
                { type: algorithm-canvas, width: @config.slotWidth, height: @config.slotHeight, backgroundColor: @config.backgroundColor, slots: @entity.slots, pointers: @entity.pointers },
                { type: typography, variant: body, content: @entity.narration }
              ] }
          ]
        })
    }

    listens {
      BfsTransport.LEARN_RESET -> LEARN_RESET
      BfsTransport.LEARN_STEP -> LEARN_STEP
      BfsTransport.LEARN_UPDATED -> LEARN_UPDATED
      MODE_SELECTED {
        mode : string
      }
        @description "Lab router broadcast naming the active mode; this instrument renders when the mode equals matchMode, otherwise renders null."
        @tier "domain"
      LEARN_STEP {
        steps : int
      }
        @description "One step of the transport clock or Step button (from the composed std-learn-transport trait); applies one BFS dequeue-and-expand."
        @tier "domain"
      LEARN_RESET {
      }
        @description "Transport Reset broadcast (from the composed std-learn-transport trait); reseeds the graph, queue, and narration from config."
        @tier "domain"
      LEARN_UPDATED {
        running : boolean
        steps : int
      }
        @description "Transport state broadcast on load and Run/Pause toggle (from the composed std-learn-transport trait); repaints the full shell so the strip's Run/Pause label and step caption stay fresh."
        @tier "domain"
    }

    emits {
      NODES_UPDATED -> external {
        nodes : [AlgoNode]
        edges : [AlgoEdge]
        queue : [string]
        visited : [string]
        narration : string
      }
        @description "The graph and queue after each step/reset — a composed listener (readout, grader) can subscribe; a harmless no-op when the atom runs standalone."
        @synonyms "breadth first search, bfs, queue, frontier, level order traversal"
        @tier "domain"
    }

    config {
      matchMode : string = ""
        @label "Match Mode"
        @description "When composed behind a lab router, the MODE_SELECTED mode value this instrument responds to. Empty string means standalone — render immediately on INIT."
        @tier "presentation"
      start : string = "A"
        @label "Start Node"
        @description "Id of the node BFS starts from; seeded into the queue on load."
        @tier "domain"
      width : number = 600
        @label "Width"
        @description "Graph canvas width in pixels."
        @tier "presentation"
      height : number = 300
        @label "Height"
        @description "Graph canvas height in pixels."
        @tier "presentation"
      slotWidth : number = 600
        @label "Queue Strip Width"
        @description "Queue strip canvas width in pixels."
        @tier "presentation"
      slotHeight : number = 140
        @label "Queue Strip Height"
        @description "Queue strip canvas height in pixels."
        @tier "presentation"
      backgroundColor : string = "#f8fafc"
        @label "Background Color"
        @description "Canvas background color."
        @tier "presentation"
      nodes : [AlgoNode] = [
        { id: "A", label: "A", state: "unvisited" },
        { id: "B", label: "B", state: "unvisited" },
        { id: "C", label: "C", state: "unvisited" },
        { id: "D", label: "D", state: "unvisited" },
        { id: "E", label: "E", state: "unvisited" },
        { id: "F", label: "F", state: "unvisited" },
        { id: "G", label: "G", state: "unvisited" }
      ]
        @label "Nodes"
        @description "Graph vertices; the circle layout computes positions, BFS drives state slate(unvisited)→amber(frontier)→red(current)→green(visited)."
        @tier "presentation"
      edges : [AlgoEdge] = [
        { from: "A", to: "B", directed: false, label: "", state: "default" },
        { from: "A", to: "C", directed: false, label: "", state: "default" },
        { from: "B", to: "D", directed: false, label: "", state: "default" },
        { from: "B", to: "E", directed: false, label: "", state: "default" },
        { from: "C", to: "F", directed: false, label: "", state: "default" },
        { from: "C", to: "G", directed: false, label: "", state: "default" },
        { from: "E", to: "F", directed: false, label: "", state: "default" }
      ]
        @label "Edges"
        @description "Undirected adjacency; each dequeue that discovers a neighbor marks that edge as a discovery (tree) edge."
        @tier "presentation"
      queueSlots : [AlgoSlot] = [
        { state: "empty" }, { state: "empty" }, { state: "empty" }, { state: "empty" },
        { state: "empty" }, { state: "empty" }, { state: "empty" }, { state: "empty" }
      ]
        @label "Queue Slots"
        @description "Pre-allocated slots bounding the queue strip's capacity; empty slots draw no value."
        @tier "presentation"
    }
  }

  page "/algo-bfs" as BfsEnginePage -> BfsTransport, BfsSim
}

app std-algo-astargraph "2.0.0"
"A* pathfinding engine on algo-graph-canvas — Step expands the open-set node with the smallest f = g + h (straight-line heuristic to the goal); badges show a compact f=g+h readout, the goal node holds state goal until expanded, and once the goal is reached the reconstructed route's nodes and edges switch to state path. An open-set slot strip renders alongside, ordered by f, head highlighted. The Step/Run-Pause/Reset transport and the step clock come from the std-learn-transport atom (AstarTransport); the A* expansion lives in the sibling AstarSim trait, which transitions directly on the transport's LEARN_STEP (applies one open-set expansion), LEARN_RESET (reseeds g-scores from the start node), and LEARN_UPDATED (full-shell repaint) broadcasts — delivered by the same bare-event cascade the lab routers use — and owns the full-shell scene render (the transport strip is embedded via @trait.AstarTransport — one render authority per shared entity). Standalone by default; behind a lab router set matchMode and it renders only when MODE_SELECTED matches."
orbital AstarGraphEngineOrbital {
  type NodeSeed = {
    id : string!
    label : string
    x : number
    y : number
  }
  type WeightedEdge = {
    from : string!
    to : string!
    weight : number!
  }
  type GScore = {
    id : string!
    g : number!
    from : string
  }
  type Badge = {
    text : string!
  }
  type GraphNodeOut = {
    id : string!
    label : string
    state : "unvisited" | "frontier" | "current" | "visited" | "goal" | "path"
    x : number
    y : number
    badge : Badge
  }
  type GraphEdgeOut = {
    from : string!
    to : string!
    directed : boolean
    weight : number
    state : "default" | "tree" | "relaxed" | "candidate" | "path"
  }
  type PQSlot = {
    value : string
    state : "empty" | "filled" | "highlight"
  }

  entity AstarScene [runtime, shared] {
    id : string!
    active : boolean = false
    title : string
    running : boolean = false
    steps : int = 0
    elapsedMs : number = 0
    done : boolean = false
    gscore : [GScore]
    visited : [string]
    cur : string = ""
    goalX : number = 0
    goalY : number = 0
    pathIds : [string]
    nodes : [GraphNodeOut]
    edges : [GraphEdgeOut]
    slots : [PQSlot]
    narration : string
  }

  uses LearnTransport from "std/behaviors/std-learn-transport"

  trait AstarTransport = LearnTransport.traits.LearnTransportSim -> AstarScene {
    config {
      title: "A* Pathfinding"
      stepIntervalMs: 500
    }
  }

  trait AstarSim -> @rebindable AstarScene [interaction, instance] {
    initial: idle

    state idle {
      INIT -> idle when (== @config.matchMode "")
        (set @entity.done false)
        (set @entity.gscore (array/map @config.nodeSeeds (fn ns
          { id: (object/get @ns id), g: (if (== (object/get @ns id) @config.start) 0 9999), from: "" })))
        (set @entity.visited [])
        (set @entity.cur "")
        (set @entity.pathIds [])
        (set @entity.goalX (object/get (array/first (array/filter @config.nodeSeeds (fn ns (== (object/get @ns id) @config.goal)))) x))
        (set @entity.goalY (object/get (array/first (array/filter @config.nodeSeeds (fn ns (== (object/get @ns id) @config.goal)))) y))
        (set @entity.nodes (array/map @config.nodeSeeds (fn ns
          { id: (object/get @ns id), label: (object/get @ns label), x: (object/get @ns x), y: (object/get @ns y),
            state: (if (== (object/get @ns id) @config.goal) "goal" (if (== (object/get @ns id) @config.start) "frontier" "unvisited")),
            badge: { text: (if (== (object/get @ns id) @config.start) "f=0" "—") } })))
        (set @entity.edges (array/map @config.edges (fn e
          { from: (object/get @e from), to: (object/get @e to), directed: true, weight: (object/get @e weight), state: "default" })))
        (set @entity.slots [ { value: (str/concat @config.start " f=0"), state: "highlight" } ])
        (set @entity.narration (str/concat "Press Step to expand the lowest-f node toward " @config.goal ", or Run to auto-play."))
        (render-ui main {
          type: box
          padding: md
          children: [
            { type: stack, direction: vertical, gap: md, children: [
                @trait.AstarTransport,
                { type: algo-graph-canvas, width: @config.width, height: @config.height, backgroundColor: @config.backgroundColor, layout: manual, nodes: @entity.nodes, edges: @entity.edges },
                { type: algorithm-canvas, width: @config.width, height: 120, backgroundColor: @config.backgroundColor, slots: @entity.slots, slotOrientation: horizontal },
                { type: typography, variant: body, content: @entity.narration }
              ] }
          ]
        })
        (emit ASTAR_UPDATED { nodes: @entity.nodes, edges: @entity.edges, gscore: @entity.gscore, narration: @entity.narration })

      MODE_SELECTED -> idle when (== ?mode @config.matchMode)
        (set @entity.done false)
        (set @entity.gscore (array/map @config.nodeSeeds (fn ns
          { id: (object/get @ns id), g: (if (== (object/get @ns id) @config.start) 0 9999), from: "" })))
        (set @entity.visited [])
        (set @entity.cur "")
        (set @entity.pathIds [])
        (set @entity.goalX (object/get (array/first (array/filter @config.nodeSeeds (fn ns (== (object/get @ns id) @config.goal)))) x))
        (set @entity.goalY (object/get (array/first (array/filter @config.nodeSeeds (fn ns (== (object/get @ns id) @config.goal)))) y))
        (set @entity.nodes (array/map @config.nodeSeeds (fn ns
          { id: (object/get @ns id), label: (object/get @ns label), x: (object/get @ns x), y: (object/get @ns y),
            state: (if (== (object/get @ns id) @config.goal) "goal" (if (== (object/get @ns id) @config.start) "frontier" "unvisited")),
            badge: { text: (if (== (object/get @ns id) @config.start) "f=0" "—") } })))
        (set @entity.edges (array/map @config.edges (fn e
          { from: (object/get @e from), to: (object/get @e to), directed: true, weight: (object/get @e weight), state: "default" })))
        (set @entity.slots [ { value: (str/concat @config.start " f=0"), state: "highlight" } ])
        (set @entity.narration (str/concat "Press Step to expand the lowest-f node toward " @config.goal ", or Run to auto-play."))
        (render-ui main {
          type: box
          padding: md
          children: [
            { type: stack, direction: vertical, gap: md, children: [
                @trait.AstarTransport,
                { type: algo-graph-canvas, width: @config.width, height: @config.height, backgroundColor: @config.backgroundColor, layout: manual, nodes: @entity.nodes, edges: @entity.edges },
                { type: algorithm-canvas, width: @config.width, height: 120, backgroundColor: @config.backgroundColor, slots: @entity.slots, slotOrientation: horizontal },
                { type: typography, variant: body, content: @entity.narration }
              ] }
          ]
        })
        (emit ASTAR_UPDATED { nodes: @entity.nodes, edges: @entity.edges, gscore: @entity.gscore, narration: @entity.narration })

      LEARN_STEP -> idle when (and (== @entity.active true) (not (== @entity.done true)))
        (set @entity.cur
          (let (
              (open (array/map
                      (array/filter @entity.gscore (fn gs (and (not (array/includes @entity.visited (object/get @gs id))) (< (object/get @gs g) 9999))))
                      (fn gs (let ( (gid (object/get @gs id)) (gd (object/get @gs g)) )
                        (let ( (nd (array/first (array/filter @entity.nodes (fn n2 (== (object/get @n2 id) @gid))))) )
                          (let ( (hh (math/round (math/sqrt (+ (* (- (object/get @nd x) @entity.goalX) (- (object/get @nd x) @entity.goalX)) (* (- (object/get @nd y) @entity.goalY) (- (object/get @nd y) @entity.goalY)))))) )
                            { id: @gid, f: (+ @gd @hh) }))))))
              (minF (array/min (array/map @open (fn of (object/get @of f)))))
            )
            (object/get (array/first (array/filter @open (fn of (== (object/get @of f) @minF)))) id)))
        (set @entity.narration
          (let (
              (gU (object/get (array/first (array/filter @entity.gscore (fn gs (== (object/get @gs id) @entity.cur)))) g))
              (nd (array/first (array/filter @entity.nodes (fn n2 (== (object/get @n2 id) @entity.cur)))))
              (hU (math/round (math/sqrt (+ (* (- (object/get @nd x) @entity.goalX) (- (object/get @nd x) @entity.goalX)) (* (- (object/get @nd y) @entity.goalY) (- (object/get @nd y) @entity.goalY))))))
              (fU (+ @gU @hU))
            )
            (str/concat "expand " @entity.cur " — g=" (str/concat "" @gU) ", h=" (str/concat "" @hU) ", f=" (str/concat "" @fU) " (min of the open set)"
              (if (== @entity.cur @config.goal) " · goal reached, route highlighted" ""))))
        (set @entity.visited (array/append @entity.visited @entity.cur))
        (set @entity.gscore
          (array/map @entity.gscore (fn row
            (let ( (nid (object/get @row id)) (dcur (object/get @row g)) )
              (let ( (matches (array/filter @entity.edges (fn e (or (and (== (object/get @e from) @entity.cur) (== (object/get @e to) @nid)) (and (== (object/get @e from) @nid) (== (object/get @e to) @entity.cur)))))) )
                (if (== (array/len @matches) 0)
                  @row
                  (let ( (gU (object/get (array/first (array/filter @entity.gscore (fn gs2 (== (object/get @gs2 id) @entity.cur)))) g)) (ww (object/get (array/first @matches) weight)) )
                    (if (< (+ @gU @ww) @dcur)
                      (object/merge @row { g: (+ @gU @ww), from: @entity.cur })
                      @row))))))))
        (set @entity.done (== @entity.cur @config.goal))
        (set @entity.pathIds
          (if @entity.done
            (array/reduce (array/range (array/len @entity.nodes)) [@config.goal]
              (fn acc i
                (let ( (last (array/last @acc)) )
                  (if (or (== @last @config.start) (== @last ""))
                    @acc
                    (array/append @acc (object/get (array/first (array/filter @entity.gscore (fn gs (== (object/get @gs id) @last)))) from))))))
            []))
        (set @entity.nodes
          (array/map @entity.nodes (fn nd
            (let ( (nid (object/get @nd id)) (grec (array/first (array/filter @entity.gscore (fn gs (== (object/get @gs id) @nid))))) )
              (object/merge @nd {
                state: (if (and @entity.done (array/includes @entity.pathIds @nid)) "path"
                         (if (== @nid @entity.cur) "current"
                           (if (== @nid @config.goal) "goal"
                             (if (array/includes @entity.visited @nid) "visited"
                               (if (< (object/get @grec g) 9999) "frontier" "unvisited"))))),
                badge: { text: (if (< (object/get @grec g) 9999)
                                 (let ( (hh (math/round (math/sqrt (+ (* (- (object/get @nd x) @entity.goalX) (- (object/get @nd x) @entity.goalX)) (* (- (object/get @nd y) @entity.goalY) (- (object/get @nd y) @entity.goalY)))))) )
                                   (str/concat "f=" (str/concat "" (+ (object/get @grec g) @hh))))
                                 "—") }
              })))))
        (set @entity.edges
          (array/map @entity.edges (fn ed
            (let ( (ef (object/get @ed from)) (et (object/get @ed to)) )
              (object/merge @ed {
                state: (if (and @entity.done (array/includes @entity.pathIds @ef) (array/includes @entity.pathIds @et)
                             (or (== (object/get (array/first (array/filter @entity.gscore (fn gs (== (object/get @gs id) @et)))) from) @ef)
                                 (== (object/get (array/first (array/filter @entity.gscore (fn gs (== (object/get @gs id) @ef)))) from) @et)))
                           "path" "default")
              })))))
        (set @entity.slots
          (array/map
            (array/sort
              (array/map
                (array/filter @entity.gscore (fn gs (and (not (array/includes @entity.visited (object/get @gs id))) (< (object/get @gs g) 9999))))
                (fn gs (let ( (gid (object/get @gs id)) (gd (object/get @gs g)) )
                  (let ( (nd (array/first (array/filter @entity.nodes (fn n2 (== (object/get @n2 id) @gid))))) )
                    (let ( (hh (math/round (math/sqrt (+ (* (- (object/get @nd x) @entity.goalX) (- (object/get @nd x) @entity.goalX)) (* (- (object/get @nd y) @entity.goalY) (- (object/get @nd y) @entity.goalY)))))) )
                      { id: @gid, f: (+ @gd @hh) })))))
              "f" "asc")
            (fn of { value: (str/concat (object/get @of id) " f=" (str/concat "" (object/get @of f))), state: (if (== @index 0) "highlight" "filled") })))
        (render-ui main {
          type: box
          padding: md
          children: [
            { type: stack, direction: vertical, gap: md, children: [
                @trait.AstarTransport,
                { type: algo-graph-canvas, width: @config.width, height: @config.height, backgroundColor: @config.backgroundColor, layout: manual, nodes: @entity.nodes, edges: @entity.edges },
                { type: algorithm-canvas, width: @config.width, height: 120, backgroundColor: @config.backgroundColor, slots: @entity.slots, slotOrientation: horizontal },
                { type: typography, variant: body, content: @entity.narration }
              ] }
          ]
        })
        (emit ASTAR_UPDATED { nodes: @entity.nodes, edges: @entity.edges, gscore: @entity.gscore, narration: @entity.narration })

      LEARN_RESET -> idle when (== @entity.active true)
        (set @entity.done false)
        (set @entity.gscore (array/map @config.nodeSeeds (fn ns
          { id: (object/get @ns id), g: (if (== (object/get @ns id) @config.start) 0 9999), from: "" })))
        (set @entity.visited [])
        (set @entity.cur "")
        (set @entity.pathIds [])
        (set @entity.goalX (object/get (array/first (array/filter @config.nodeSeeds (fn ns (== (object/get @ns id) @config.goal)))) x))
        (set @entity.goalY (object/get (array/first (array/filter @config.nodeSeeds (fn ns (== (object/get @ns id) @config.goal)))) y))
        (set @entity.nodes (array/map @config.nodeSeeds (fn ns
          { id: (object/get @ns id), label: (object/get @ns label), x: (object/get @ns x), y: (object/get @ns y),
            state: (if (== (object/get @ns id) @config.goal) "goal" (if (== (object/get @ns id) @config.start) "frontier" "unvisited")),
            badge: { text: (if (== (object/get @ns id) @config.start) "f=0" "—") } })))
        (set @entity.edges (array/map @config.edges (fn e
          { from: (object/get @e from), to: (object/get @e to), directed: true, weight: (object/get @e weight), state: "default" })))
        (set @entity.slots [ { value: (str/concat @config.start " f=0"), state: "highlight" } ])
        (set @entity.narration (str/concat "Press Step to expand the lowest-f node toward " @config.goal ", or Run to auto-play."))
        (render-ui main {
          type: box
          padding: md
          children: [
            { type: stack, direction: vertical, gap: md, children: [
                @trait.AstarTransport,
                { type: algo-graph-canvas, width: @config.width, height: @config.height, backgroundColor: @config.backgroundColor, layout: manual, nodes: @entity.nodes, edges: @entity.edges },
                { type: algorithm-canvas, width: @config.width, height: 120, backgroundColor: @config.backgroundColor, slots: @entity.slots, slotOrientation: horizontal },
                { type: typography, variant: body, content: @entity.narration }
              ] }
          ]
        })
        (emit ASTAR_UPDATED { nodes: @entity.nodes, edges: @entity.edges, gscore: @entity.gscore, narration: @entity.narration })

      LEARN_UPDATED -> idle when (== @entity.active true)
        (render-ui main {
          type: box
          padding: md
          children: [
            { type: stack, direction: vertical, gap: md, children: [
                @trait.AstarTransport,
                { type: algo-graph-canvas, width: @config.width, height: @config.height, backgroundColor: @config.backgroundColor, layout: manual, nodes: @entity.nodes, edges: @entity.edges },
                { type: algorithm-canvas, width: @config.width, height: 120, backgroundColor: @config.backgroundColor, slots: @entity.slots, slotOrientation: horizontal },
                { type: typography, variant: body, content: @entity.narration }
              ] }
          ]
        })
    }

    listens {
      AstarTransport.LEARN_RESET -> LEARN_RESET
      AstarTransport.LEARN_STEP -> LEARN_STEP
      AstarTransport.LEARN_UPDATED -> LEARN_UPDATED
      MODE_SELECTED {
        mode : string
      }
        @description "Lab router broadcast naming the active mode; this instrument renders when the mode equals matchMode, otherwise renders null."
        @tier "domain"
      LEARN_STEP {
        steps : int
      }
        @description "One step of the transport clock or Step button (from the composed std-learn-transport trait); applies one A* open-set expansion."
        @tier "domain"
      LEARN_RESET {
      }
        @description "Transport Reset broadcast (from the composed std-learn-transport trait); reseeds g-scores, the graph, and narration from config."
        @tier "domain"
      LEARN_UPDATED {
        running : boolean
        steps : int
      }
        @description "Transport state broadcast on load and Run/Pause toggle (from the composed std-learn-transport trait); repaints the full shell so the strip's Run/Pause label and step caption stay fresh."
        @tier "domain"
    }

    emits {
      ASTAR_UPDATED -> external {
        nodes : [GraphNodeOut]
        edges : [GraphEdgeOut]
        gscore : [GScore]
        narration : string
      }
        @description "The graph and g-score table after each step/reset — a composed listener (readout, grader) can subscribe; a harmless no-op when the atom runs standalone."
        @synonyms "astar, a star, heuristic, open set, goal, path, expand, admissible"
        @tier "domain"
    }

    config {
      matchMode : string = ""
        @label "Match Mode"
        @description "When composed behind a lab router, the MODE_SELECTED mode value this instrument responds to. Empty string means standalone — render immediately on INIT."
        @tier "presentation"
      start : string = "A"
        @label "Start Node"
        @description "Id of the node A* searches from; seeded to g=0."
        @tier "domain"
      goal : string = "G"
        @label "Goal Node"
        @description "Id of the target node; the search stops once it is expanded and its route is reconstructed."
        @tier "domain"
      width : number = 600
        @label "Width"
        @description "Canvas width in pixels."
        @tier "presentation"
      height : number = 400
        @label "Height"
        @description "Canvas height in pixels."
        @tier "presentation"
      backgroundColor : string = "#f8fafc"
        @label "Background Color"
        @description "Canvas background color."
        @tier "presentation"
      nodeSeeds : [NodeSeed] = [
        { id: "A", label: "A", x: 60, y: 340 },
        { id: "B", label: "B", x: 180, y: 200 },
        { id: "C", label: "C", x: 200, y: 340 },
        { id: "D", label: "D", x: 340, y: 180 },
        { id: "E", label: "E", x: 360, y: 340 },
        { id: "F", label: "F", x: 500, y: 200 },
        { id: "G", label: "G", x: 540, y: 340 }
      ]
        @label "Node Seeds"
        @description "Graph vertices — id/label/manual x,y position; the algorithm recolors them via state, not these seeds."
        @synonyms "vertices, nodes, graph"
        @tier "domain"
      edges : [WeightedEdge] = [
        { from: "A", to: "B", weight: 186 },
        { from: "A", to: "C", weight: 142 },
        { from: "B", to: "C", weight: 143 },
        { from: "B", to: "D", weight: 163 },
        { from: "C", to: "E", weight: 162 },
        { from: "D", to: "E", weight: 163 },
        { from: "D", to: "F", weight: 163 },
        { from: "E", to: "F", weight: 200 },
        { from: "E", to: "G", weight: 182 },
        { from: "F", to: "G", weight: 148 }
      ]
        @label "Weighted Edges"
        @description "Weighted adjacency the relaxation reads and the drawn (directed) edges source; each weight exceeds its edge's straight-line length so the heuristic stays admissible."
        @synonyms "adjacency, weights, graph edges"
        @tier "domain"
    }
  }

  page "/algo-astargraph" as AstarGraphEnginePage -> AstarTransport, AstarSim
}

app std-physics-projectile "2.0.0"
"Projectile-motion engine — integrates bodies under constant gravity with wall/ground bounce, substepped for smooth motion, and renders a physics-canvas with trails, a labeled velocity vector, and height/range/speed readouts. The Step/Run-Pause/Reset transport and the step clock come from the std-learn-transport atom (ProjectileTransport); the gravity/bounce integration lives in the sibling ProjectileSim trait, which transitions directly on the transport's LEARN_STEP (applies one substepped integration batch), LEARN_RESET (reseeds bodies, trails, vectors, and readouts from config), and LEARN_UPDATED (full-shell repaint) broadcasts — delivered by the same bare-event cascade the lab routers use — and owns the full-shell scene render (the transport strip is embedded via @trait.ProjectileTransport — one render authority per shared entity). Standalone by default; behind a lab router set matchMode and it renders only when MODE_SELECTED matches."
orbital ProjectileEngineOrbital {
  type ProjectileBody = {
    id : string
    x : number!
    y : number!
    radius : number
    color : string
    label : string
    vx : number
    vy : number
    fx : number
    fy : number
  }
  type ProjectilePoint = {
    x : number!
    y : number!
  }
  type ProjectileTrail = {
    id : string
    points : [ProjectilePoint]
    color : string
  }
  type ProjectileVector = {
    body : string
    dx : number!
    dy : number!
    scale : number
    color : string
    label : string
  }
  type ProjectileSceneObject = {
    kind : "ground" | "box"!
    x : number
    y : number
    x1 : number
    x2 : number
    width : number
    height : number
    color : string
    fill : string
    label : string
  }
  type ProjectileReadout = {
    label : string!
    value : string!
    color : string
  }

  entity ProjectileState [runtime, shared] {
    id : string!
    active : boolean = false
    title : string
    running : boolean = false
    steps : int = 0
    elapsedMs : number = 0
    done : boolean = false
    bodies : [ProjectileBody]
    trails : [ProjectileTrail]
    vectors : [ProjectileVector]
    sceneObjects : [ProjectileSceneObject]
    readouts : [ProjectileReadout]
    launchX : number = 0
    narration : string
  }

  uses LearnTransport from "std/behaviors/std-learn-transport"

  trait ProjectileTransport = LearnTransport.traits.LearnTransportSim -> ProjectileState {
    config {
      title: "Projectile Motion"
      stepIntervalMs: 500
    }
  }

  trait ProjectileSim -> @rebindable ProjectileState [interaction, instance] {
    initial: idle

    state idle {
      INIT -> idle when (== @config.matchMode "")
        (set @entity.bodies @config.bodies)
        (set @entity.done false)
        (let (
            (groundY (* @config.height 0.9))
            (padW (* @config.width 0.06))
            (padH (* @config.height 0.045))
            (launchX (object/get (array/nth @config.bodies 0) x))
          )
          (do
            (set @entity.launchX @launchX)
            (set @entity.sceneObjects [
              { kind: "ground", x1: 0, x2: @config.width, y: @groundY, label: "ground" },
              { kind: "box", x: (- @launchX (/ @padW 2)), y: (- @groundY @padH), width: @padW, height: @padH, color: "#334155", fill: "#cbd5e1", label: "pad" }
            ])))
        (set @entity.trails (array/map @config.bodies (fn b { id: (object/get @b id), points: [ { x: (object/get @b x), y: (object/get @b y) } ], color: (object/get @b color) })))
        (let (
            (primary (array/nth @config.bodies 0))
          )
          (set @entity.vectors [ { body: (object/get @primary id), dx: (object/get @primary vx), dy: (object/get @primary vy), scale: @config.velocityScale, color: "#dc2626", label: "v" } ]))
        (set @entity.readouts [
          { label: "height", value: "0" },
          { label: "range", value: "0" },
          { label: "speed", value: "0" }
        ])
        (set @entity.narration "ready — press Step to launch")
        (render-ui main {
          type: box
          padding: md
          children: [
            { type: stack, direction: vertical, gap: md, children: [
                @trait.ProjectileTransport,
                { type: physics-canvas, width: @config.width, height: @config.height, backgroundColor: @config.backgroundColor, bodies: @entity.bodies, sceneObjects: @entity.sceneObjects, trails: @entity.trails, vectors: @entity.vectors, showVelocity: @config.showVelocity, showForces: false, velocityScale: @config.velocityScale, readouts: @entity.readouts },
                { type: typography, variant: body, content: @entity.narration }
              ] }
          ]
        })
        (emit PROJECTILE_UPDATED { bodies: @entity.bodies, trails: @entity.trails, height: "0", range: "0", speed: "0", narration: @entity.narration })

      MODE_SELECTED -> idle when (== ?mode @config.matchMode)
        (set @entity.bodies @config.bodies)
        (set @entity.done false)
        (let (
            (groundY (* @config.height 0.9))
            (padW (* @config.width 0.06))
            (padH (* @config.height 0.045))
            (launchX (object/get (array/nth @config.bodies 0) x))
          )
          (do
            (set @entity.launchX @launchX)
            (set @entity.sceneObjects [
              { kind: "ground", x1: 0, x2: @config.width, y: @groundY, label: "ground" },
              { kind: "box", x: (- @launchX (/ @padW 2)), y: (- @groundY @padH), width: @padW, height: @padH, color: "#334155", fill: "#cbd5e1", label: "pad" }
            ])))
        (set @entity.trails (array/map @config.bodies (fn b { id: (object/get @b id), points: [ { x: (object/get @b x), y: (object/get @b y) } ], color: (object/get @b color) })))
        (let (
            (primary (array/nth @config.bodies 0))
          )
          (set @entity.vectors [ { body: (object/get @primary id), dx: (object/get @primary vx), dy: (object/get @primary vy), scale: @config.velocityScale, color: "#dc2626", label: "v" } ]))
        (set @entity.readouts [
          { label: "height", value: "0" },
          { label: "range", value: "0" },
          { label: "speed", value: "0" }
        ])
        (set @entity.narration "ready — press Step to launch")
        (render-ui main {
          type: box
          padding: md
          children: [
            { type: stack, direction: vertical, gap: md, children: [
                @trait.ProjectileTransport,
                { type: physics-canvas, width: @config.width, height: @config.height, backgroundColor: @config.backgroundColor, bodies: @entity.bodies, sceneObjects: @entity.sceneObjects, trails: @entity.trails, vectors: @entity.vectors, showVelocity: @config.showVelocity, showForces: false, velocityScale: @config.velocityScale, readouts: @entity.readouts },
                { type: typography, variant: body, content: @entity.narration }
              ] }
          ]
        })
        (emit PROJECTILE_UPDATED { bodies: @entity.bodies, trails: @entity.trails, height: "0", range: "0", speed: "0", narration: @entity.narration })

      LEARN_STEP -> idle when (and (== @entity.active true) (not (== @entity.done true)))
        (let (
            (groundY (* @config.height 0.9))
            (newBodies (array/reduce (array/range @config.substeps) @entity.bodies (fn acc s
              (array/map @acc (fn b
                (let (
                    (r (object/get @b radius))
                    (nvx (* (object/get @b vx) @config.damping))
                    (nvy (* (+ (object/get @b vy) @config.gravity) @config.damping))
                  )
                  (let (
                      (nx (+ (object/get @b x) @nvx))
                      (ny (+ (object/get @b y) @nvy))
                    )
                    (let (
                        (hitx (or (< @nx @r) (> @nx (- @config.width @r))))
                        (hity (or (< @ny @r) (> @ny (- @groundY @r))))
                      )
                      (object/merge @b {
                        x: (math/clamp @nx @r (- @config.width @r)),
                        y: (math/clamp @ny @r (- @groundY @r)),
                        vx: (if @hitx (* @nvx (* -1 @config.restitution)) @nvx),
                        vy: (if @hity (* @nvy (* -1 @config.restitution)) @nvy)
                      })))))))))
            (newTrails (array/map @newBodies (fn b
              (let (
                  (prevPts (object/get (array/nth @entity.trails @index) points))
                  (appended (array/append @prevPts { x: (object/get @b x), y: (object/get @b y) }))
                  (n (array/len @appended))
                )
                { id: (object/get @b id), points: (if (> @n @config.traceLength) (array/drop @appended (- @n @config.traceLength)) @appended), color: (object/get @b color) }))))
            (primary (array/nth @newBodies 0))
            (pvx (object/get @primary vx))
            (pvy (object/get @primary vy))
            (speed (math/hypot @pvx @pvy))
            (heightVal (- @groundY (object/get @primary y)))
            (rangeVal (math/abs (- (object/get @primary x) @entity.launchX)))
            (settled (< @speed @config.epsilon))
          )
          (do
            (set @entity.bodies @newBodies)
            (set @entity.trails @newTrails)
            (set @entity.vectors [ { body: (object/get @primary id), dx: @pvx, dy: @pvy, scale: @config.velocityScale, color: "#dc2626", label: "v" } ])
            (set @entity.readouts [
              { label: "height", value: (str/concat "" (math/round @heightVal 1)) },
              { label: "range", value: (str/concat "" (math/round @rangeVal 1)) },
              { label: "speed", value: (str/concat "" (math/round @speed 2)) }
            ])
            (set @entity.done @settled)
            (set @entity.narration (if @settled
              (str/concat "at rest — height " (str/concat "" (math/round @heightVal 1)) "px, range " (str/concat "" (math/round @rangeVal 1)) "px")
              (str/concat "in flight — speed " (str/concat "" (math/round @speed 2)) " px/step")))))
        (render-ui main {
          type: box
          padding: md
          children: [
            { type: stack, direction: vertical, gap: md, children: [
                @trait.ProjectileTransport,
                { type: physics-canvas, width: @config.width, height: @config.height, backgroundColor: @config.backgroundColor, bodies: @entity.bodies, sceneObjects: @entity.sceneObjects, trails: @entity.trails, vectors: @entity.vectors, showVelocity: @config.showVelocity, showForces: false, velocityScale: @config.velocityScale, readouts: @entity.readouts },
                { type: typography, variant: body, content: @entity.narration }
              ] }
          ]
        })
        (emit PROJECTILE_UPDATED { bodies: @entity.bodies, trails: @entity.trails, height: (object/get (array/nth @entity.readouts 0) value), range: (object/get (array/nth @entity.readouts 1) value), speed: (object/get (array/nth @entity.readouts 2) value), narration: @entity.narration })

      LEARN_RESET -> idle when (== @entity.active true)
        (set @entity.bodies @config.bodies)
        (set @entity.done false)
        (let (
            (groundY (* @config.height 0.9))
            (padW (* @config.width 0.06))
            (padH (* @config.height 0.045))
            (launchX (object/get (array/nth @config.bodies 0) x))
          )
          (do
            (set @entity.launchX @launchX)
            (set @entity.sceneObjects [
              { kind: "ground", x1: 0, x2: @config.width, y: @groundY, label: "ground" },
              { kind: "box", x: (- @launchX (/ @padW 2)), y: (- @groundY @padH), width: @padW, height: @padH, color: "#334155", fill: "#cbd5e1", label: "pad" }
            ])))
        (set @entity.trails (array/map @config.bodies (fn b { id: (object/get @b id), points: [ { x: (object/get @b x), y: (object/get @b y) } ], color: (object/get @b color) })))
        (let (
            (primary (array/nth @config.bodies 0))
          )
          (set @entity.vectors [ { body: (object/get @primary id), dx: (object/get @primary vx), dy: (object/get @primary vy), scale: @config.velocityScale, color: "#dc2626", label: "v" } ]))
        (set @entity.readouts [
          { label: "height", value: "0" },
          { label: "range", value: "0" },
          { label: "speed", value: "0" }
        ])
        (set @entity.narration "ready — press Step to launch")
        (render-ui main {
          type: box
          padding: md
          children: [
            { type: stack, direction: vertical, gap: md, children: [
                @trait.ProjectileTransport,
                { type: physics-canvas, width: @config.width, height: @config.height, backgroundColor: @config.backgroundColor, bodies: @entity.bodies, sceneObjects: @entity.sceneObjects, trails: @entity.trails, vectors: @entity.vectors, showVelocity: @config.showVelocity, showForces: false, velocityScale: @config.velocityScale, readouts: @entity.readouts },
                { type: typography, variant: body, content: @entity.narration }
              ] }
          ]
        })
        (emit PROJECTILE_UPDATED { bodies: @entity.bodies, trails: @entity.trails, height: "0", range: "0", speed: "0", narration: @entity.narration })

      LEARN_UPDATED -> idle when (== @entity.active true)
        (render-ui main {
          type: box
          padding: md
          children: [
            { type: stack, direction: vertical, gap: md, children: [
                @trait.ProjectileTransport,
                { type: physics-canvas, width: @config.width, height: @config.height, backgroundColor: @config.backgroundColor, bodies: @entity.bodies, sceneObjects: @entity.sceneObjects, trails: @entity.trails, vectors: @entity.vectors, showVelocity: @config.showVelocity, showForces: false, velocityScale: @config.velocityScale, readouts: @entity.readouts },
                { type: typography, variant: body, content: @entity.narration }
              ] }
          ]
        })
    }

    listens {
      ProjectileTransport.LEARN_RESET -> LEARN_RESET
      ProjectileTransport.LEARN_STEP -> LEARN_STEP
      ProjectileTransport.LEARN_UPDATED -> LEARN_UPDATED
      MODE_SELECTED {
        mode : string
      }
        @description "Lab router broadcast naming the active mode; this instrument renders when the mode equals matchMode, otherwise renders null."
        @tier "domain"
      LEARN_STEP {
        steps : int
      }
        @description "One step of the transport clock or Step button (from the composed std-learn-transport trait); integrates gravity and bounces for one substepped batch."
        @tier "domain"
      LEARN_RESET {
      }
        @description "Transport Reset broadcast (from the composed std-learn-transport trait); reseeds bodies, trails, vectors, readouts, and narration from config."
        @tier "domain"
      LEARN_UPDATED {
        running : boolean
        steps : int
      }
        @description "Transport state broadcast on load and Run/Pause toggle (from the composed std-learn-transport trait); repaints the full shell so the strip's Run/Pause label and step caption stay fresh."
        @tier "domain"
    }

    emits {
      PROJECTILE_UPDATED -> external {
        bodies : [ProjectileBody]
        trails : [ProjectileTrail]
        height : string
        range : string
        speed : string
        narration : string
      }
        @description "The scene and computed height/range/speed readouts after each step/toggle/reset — a composed listener (graph, readout, mirror canvas) can subscribe; a harmless no-op when the atom runs standalone."
        @synonyms "projectile motion, trajectory, launch, ballistic, parabola"
        @tier "domain"
    }

    config {
      matchMode : string = ""
        @label "Match Mode"
        @description "When composed behind a lab router, the MODE_SELECTED mode value this instrument responds to. Empty string means standalone — render immediately on INIT."
        @tier "presentation"
      substeps : number = 8
        @label "Substeps"
        @description "Integration substeps applied per Step press or tick, for smoother motion at a coarse UI cadence."
        @synonyms "integration steps, sub-steps, physics substeps"
        @tier "domain"
      gravity : number = 0.4
        @label "Gravity"
        @description "Downward acceleration added to each body's vy every substep."
        @synonyms "acceleration, g, downward pull"
        @tier "domain"
      restitution : number = 0.78
        @label "Restitution"
        @description "Fraction of speed kept when a body bounces off the ground or a wall."
        @synonyms "bounciness, elasticity, energy retained"
        @tier "domain"
      damping : number = 0.995
        @label "Damping"
        @description "Fraction of velocity retained each substep (air resistance)."
        @synonyms "air resistance, drag"
        @tier "domain"
      traceLength : number = 60
        @label "Trace Length"
        @description "Maximum trail points retained per body; older points drop off the trail's tail."
        @synonyms "trail length, trace cap, history length"
        @tier "domain"
      epsilon : number = 0.05
        @label "Rest Threshold"
        @description "Speed below which the primary body is considered settled, marking the sim done."
        @synonyms "stop threshold, rest speed, settle threshold"
        @tier "domain"
      width : number = 600
        @label "Width"
        @description "Simulation width in pixels; bounds the bounce and sets wall positions."
        @tier "presentation"
      height : number = 400
        @label "Height"
        @description "Simulation height in pixels; the ground line sits at 90% of this height."
        @tier "presentation"
      backgroundColor : string = "#f8fafc"
        @label "Background Color"
        @description "Canvas background color."
        @tier "presentation"
      showVelocity : boolean = true
        @label "Show Velocity"
        @description "Draw each body's built-in velocity arrow in addition to the labeled v vector on the primary body."
        @tier "presentation"
      velocityScale : number = 8
        @label "Velocity Scale"
        @description "Length multiplier for the velocity arrows."
        @tier "presentation"
      bodies : [ProjectileBody] = [
        { id: "ball-a", x: 90, y: 70, radius: 16, color: "#2563eb", label: "A", vx: 5, vy: 0, fx: 0, fy: 0 },
        { id: "ball-b", x: 320, y: 50, radius: 11, color: "#16a34a", label: "B", vx: -4, vy: 3, fx: 0, fy: 0 }
      ]
        @label "Bodies"
        @description "Initial bodies; each carries position (x,y) and velocity (vx,vy). The first body (index 0) is the primary tracked for the labeled vector, readouts, and the rest/done condition."
        @tier "presentation"
    }
  }

  page "/physics-projectile" as ProjectileEnginePage -> ProjectileTransport, ProjectileSim
}

app std-physics-pendulum "2.0.0"
"Pendulum engine — swings a bob about a fixed pivot via rigid-length projection, substepped for smooth motion, and renders a physics-canvas with a pivot fixture, a rod, an angle marker measured from vertical, a bob trail, and labeled tension/gravity vectors. The Step/Run-Pause/Reset transport and the step clock come from the std-learn-transport atom (PendulumTransport); the swing lives in the sibling PendulumSim trait, which transitions directly on the transport's LEARN_STEP (applies one substepped rigid-length projection pass), LEARN_RESET (reseeds bodies, trails, vectors, angles, and readouts from config), and LEARN_UPDATED (full-shell repaint) broadcasts — delivered by the same bare-event cascade the lab routers use — and owns the full-shell scene render (the transport strip is embedded via @trait.PendulumTransport — one render authority per shared entity); a pendulum never reaches rest in this model, so done stays false-only. Standalone by default; behind a lab router set matchMode and it renders only when MODE_SELECTED matches."
orbital PendulumEngineOrbital {
  type PendulumBody = {
    id : string
    x : number!
    y : number!
    radius : number
    color : string
    label : string
    vx : number
    vy : number
    fx : number
    fy : number
  }
  type PendulumPoint = {
    x : number!
    y : number!
  }
  type PendulumTrail = {
    id : string
    points : [PendulumPoint]
    color : string
  }
  type PendulumVector = {
    body : string
    dx : number!
    dy : number!
    color : string
    label : string
  }
  type PendulumAngle = {
    x : number!
    y : number!
    from : number!
    to : number!
    radius : number
    color : string
    label : string
  }
  type PendulumSceneObject = {
    kind : "pivot"!
    x : number
    y : number
    label : string
  }
  type PendulumConstraint = {
    from : string!
    to : string!
    kind : string
    color : string
  }
  type PendulumReadout = {
    label : string!
    value : string!
    color : string
  }

  entity PendulumState [runtime, shared] {
    id : string!
    active : boolean = false
    title : string
    running : boolean = false
    steps : int = 0
    elapsedMs : number = 0
    done : boolean = false
    bodies : [PendulumBody]
    trails : [PendulumTrail]
    vectors : [PendulumVector]
    angles : [PendulumAngle]
    sceneObjects : [PendulumSceneObject]
    constraints : [PendulumConstraint]
    readouts : [PendulumReadout]
    narration : string
  }

  uses LearnTransport from "std/behaviors/std-learn-transport"

  trait PendulumTransport = LearnTransport.traits.LearnTransportSim -> PendulumState {
    config {
      title: "Pendulum"
      stepIntervalMs: 500
    }
  }

  trait PendulumSim -> @rebindable PendulumState [interaction, instance] {
    initial: idle

    state idle {
      INIT -> idle when (== @config.matchMode "")
        (set @entity.done false)
        (let (
            (pivotX (* @config.width @config.pivotXFrac))
            (pivotY (* @config.height @config.pivotYFrac))
            (configBob (array/nth @config.bodies 0))
            (bobId (object/get @configBob id))
            (bobX (object/get @configBob x))
            (bobY (object/get @configBob y))
            (dx (- @bobX @pivotX))
            (dy (- @bobY @pivotY))
            (dist (math/hypot @dx @dy))
            (bearingDeg (math/rad-deg (math/atan2 @dy @dx)))
            (thetaFromVertical (- @bearingDeg 90))
            (thetaLabel (str/concat (str/concat "" (math/round @thetaFromVertical 1)) "°"))
            (tMag (* @config.gravity (* @config.vectorScale (math/cos (math/deg-rad @thetaFromVertical)))))
            (ux (/ (* -1 @dx) @dist))
            (uy (/ (* -1 @dy) @dist))
          )
          (do
            (set @entity.sceneObjects [ { kind: "pivot", x: @pivotX, y: @pivotY, label: "pivot" } ])
            (set @entity.bodies (array/concat [ { id: "pivot", x: @pivotX, y: @pivotY, radius: 6, color: "#334155", label: "", vx: 0, vy: 0, fx: 0, fy: 0 } ] [ @configBob ]))
            (set @entity.constraints [ { from: "pivot", to: @bobId, kind: "rod", color: "#94a3b8" } ])
            (set @entity.trails [ { id: @bobId, points: [ { x: @bobX, y: @bobY } ], color: (object/get @configBob color) } ])
            (set @entity.vectors [
              { body: @bobId, dx: 0, dy: (* @config.gravity @config.vectorScale), color: "#dc2626", label: "mg" },
              { body: @bobId, dx: (* @ux @tMag), dy: (* @uy @tMag), color: "#16a34a", label: "T" }
            ])
            (set @entity.angles [ { x: @pivotX, y: @pivotY, from: 90, to: @bearingDeg, radius: 24, color: "#0ea5e9", label: @thetaLabel } ])
            (set @entity.readouts [ { label: "θ", value: @thetaLabel } ])
            (set @entity.narration (str/concat "ready — bob at " (str/concat @thetaLabel " from vertical; press Step or Run to swing")))))
        (render-ui main {
          type: box
          padding: md
          children: [
            { type: stack, direction: vertical, gap: md, children: [
                @trait.PendulumTransport,
                { type: physics-canvas, width: @config.width, height: @config.height, backgroundColor: @config.backgroundColor, bodies: @entity.bodies, constraints: @entity.constraints, sceneObjects: @entity.sceneObjects, trails: @entity.trails, vectors: @entity.vectors, angles: @entity.angles, showVelocity: @config.showVelocity, showForces: false, velocityScale: @config.velocityScale, readouts: @entity.readouts },
                { type: typography, variant: body, content: @entity.narration }
              ] }
          ]
        })
        (emit PENDULUM_UPDATED { bodies: @entity.bodies, trails: @entity.trails, readouts: @entity.readouts, narration: @entity.narration })

      MODE_SELECTED -> idle when (== ?mode @config.matchMode)
        (set @entity.done false)
        (let (
            (pivotX (* @config.width @config.pivotXFrac))
            (pivotY (* @config.height @config.pivotYFrac))
            (configBob (array/nth @config.bodies 0))
            (bobId (object/get @configBob id))
            (bobX (object/get @configBob x))
            (bobY (object/get @configBob y))
            (dx (- @bobX @pivotX))
            (dy (- @bobY @pivotY))
            (dist (math/hypot @dx @dy))
            (bearingDeg (math/rad-deg (math/atan2 @dy @dx)))
            (thetaFromVertical (- @bearingDeg 90))
            (thetaLabel (str/concat (str/concat "" (math/round @thetaFromVertical 1)) "°"))
            (tMag (* @config.gravity (* @config.vectorScale (math/cos (math/deg-rad @thetaFromVertical)))))
            (ux (/ (* -1 @dx) @dist))
            (uy (/ (* -1 @dy) @dist))
          )
          (do
            (set @entity.sceneObjects [ { kind: "pivot", x: @pivotX, y: @pivotY, label: "pivot" } ])
            (set @entity.bodies (array/concat [ { id: "pivot", x: @pivotX, y: @pivotY, radius: 6, color: "#334155", label: "", vx: 0, vy: 0, fx: 0, fy: 0 } ] [ @configBob ]))
            (set @entity.constraints [ { from: "pivot", to: @bobId, kind: "rod", color: "#94a3b8" } ])
            (set @entity.trails [ { id: @bobId, points: [ { x: @bobX, y: @bobY } ], color: (object/get @configBob color) } ])
            (set @entity.vectors [
              { body: @bobId, dx: 0, dy: (* @config.gravity @config.vectorScale), color: "#dc2626", label: "mg" },
              { body: @bobId, dx: (* @ux @tMag), dy: (* @uy @tMag), color: "#16a34a", label: "T" }
            ])
            (set @entity.angles [ { x: @pivotX, y: @pivotY, from: 90, to: @bearingDeg, radius: 24, color: "#0ea5e9", label: @thetaLabel } ])
            (set @entity.readouts [ { label: "θ", value: @thetaLabel } ])
            (set @entity.narration (str/concat "ready — bob at " (str/concat @thetaLabel " from vertical; press Step or Run to swing")))))
        (render-ui main {
          type: box
          padding: md
          children: [
            { type: stack, direction: vertical, gap: md, children: [
                @trait.PendulumTransport,
                { type: physics-canvas, width: @config.width, height: @config.height, backgroundColor: @config.backgroundColor, bodies: @entity.bodies, constraints: @entity.constraints, sceneObjects: @entity.sceneObjects, trails: @entity.trails, vectors: @entity.vectors, angles: @entity.angles, showVelocity: @config.showVelocity, showForces: false, velocityScale: @config.velocityScale, readouts: @entity.readouts },
                { type: typography, variant: body, content: @entity.narration }
              ] }
          ]
        })
        (emit PENDULUM_UPDATED { bodies: @entity.bodies, trails: @entity.trails, readouts: @entity.readouts, narration: @entity.narration })

      ;; a pendulum never terminates under rigid-length projection — done is never set true here
      LEARN_STEP -> idle when (and (== @entity.active true) (not (== @entity.done true)))
        (let (
            (pivotX (* @config.width @config.pivotXFrac))
            (pivotY (* @config.height @config.pivotYFrac))
            (newBodies (array/reduce (array/range @config.substeps) @entity.bodies (fn acc s
              (array/map @acc (fn b
                (if (== (object/get @b id) "pivot")
                  @b
                  (let (
                      (nvy (* (+ (object/get @b vy) @config.gravity) @config.damping))
                      (nvx (* (object/get @b vx) @config.damping))
                    )
                    (let (
                        (px (+ (object/get @b x) @nvx))
                        (py (+ (object/get @b y) @nvy))
                      )
                      (let (
                          (rdx (- @px @pivotX))
                          (rdy (- @py @pivotY))
                        )
                        (let (
                            (rdist (math/hypot @rdx @rdy))
                          )
                          (let (
                              (s (/ @config.length @rdist))
                            )
                            (let (
                                (cxp (+ @pivotX (* @rdx @s)))
                                (cyp (+ @pivotY (* @rdy @s)))
                              )
                              (object/merge @b {
                                x: @cxp,
                                y: @cyp,
                                vx: (- @cxp (object/get @b x)),
                                vy: (- @cyp (object/get @b y))
                              })))))))))))))
            (bob (array/nth @newBodies 1))
            (bobId (object/get @bob id))
            (bobX (object/get @bob x))
            (bobY (object/get @bob y))
            (dx (- @bobX @pivotX))
            (dy (- @bobY @pivotY))
            (dist (math/hypot @dx @dy))
            (bearingDeg (math/rad-deg (math/atan2 @dy @dx)))
            (thetaFromVertical (- @bearingDeg 90))
            (thetaLabel (str/concat (str/concat "" (math/round @thetaFromVertical 1)) "°"))
            (tMag (* @config.gravity (* @config.vectorScale (math/cos (math/deg-rad @thetaFromVertical)))))
            (ux (/ (* -1 @dx) @dist))
            (uy (/ (* -1 @dy) @dist))
            (prevPts (object/get (array/nth @entity.trails 0) points))
            (appended (array/append @prevPts { x: @bobX, y: @bobY }))
            (n (array/len @appended))
          )
          (do
            (set @entity.bodies @newBodies)
            (set @entity.trails [ { id: @bobId, points: (if (> @n @config.traceLength) (array/drop @appended (- @n @config.traceLength)) @appended), color: (object/get @bob color) } ])
            (set @entity.vectors [
              { body: @bobId, dx: 0, dy: (* @config.gravity @config.vectorScale), color: "#dc2626", label: "mg" },
              { body: @bobId, dx: (* @ux @tMag), dy: (* @uy @tMag), color: "#16a34a", label: "T" }
            ])
            (set @entity.angles [ { x: @pivotX, y: @pivotY, from: 90, to: @bearingDeg, radius: 24, color: "#0ea5e9", label: @thetaLabel } ])
            (set @entity.readouts [ { label: "θ", value: @thetaLabel } ])
            (set @entity.narration (str/concat "swinging — " (str/concat @thetaLabel " from vertical")))))
        (render-ui main {
          type: box
          padding: md
          children: [
            { type: stack, direction: vertical, gap: md, children: [
                @trait.PendulumTransport,
                { type: physics-canvas, width: @config.width, height: @config.height, backgroundColor: @config.backgroundColor, bodies: @entity.bodies, constraints: @entity.constraints, sceneObjects: @entity.sceneObjects, trails: @entity.trails, vectors: @entity.vectors, angles: @entity.angles, showVelocity: @config.showVelocity, showForces: false, velocityScale: @config.velocityScale, readouts: @entity.readouts },
                { type: typography, variant: body, content: @entity.narration }
              ] }
          ]
        })
        (emit PENDULUM_UPDATED { bodies: @entity.bodies, trails: @entity.trails, readouts: @entity.readouts, narration: @entity.narration })

      LEARN_RESET -> idle when (== @entity.active true)
        (set @entity.done false)
        (let (
            (pivotX (* @config.width @config.pivotXFrac))
            (pivotY (* @config.height @config.pivotYFrac))
            (configBob (array/nth @config.bodies 0))
            (bobId (object/get @configBob id))
            (bobX (object/get @configBob x))
            (bobY (object/get @configBob y))
            (dx (- @bobX @pivotX))
            (dy (- @bobY @pivotY))
            (dist (math/hypot @dx @dy))
            (bearingDeg (math/rad-deg (math/atan2 @dy @dx)))
            (thetaFromVertical (- @bearingDeg 90))
            (thetaLabel (str/concat (str/concat "" (math/round @thetaFromVertical 1)) "°"))
            (tMag (* @config.gravity (* @config.vectorScale (math/cos (math/deg-rad @thetaFromVertical)))))
            (ux (/ (* -1 @dx) @dist))
            (uy (/ (* -1 @dy) @dist))
          )
          (do
            (set @entity.sceneObjects [ { kind: "pivot", x: @pivotX, y: @pivotY, label: "pivot" } ])
            (set @entity.bodies (array/concat [ { id: "pivot", x: @pivotX, y: @pivotY, radius: 6, color: "#334155", label: "", vx: 0, vy: 0, fx: 0, fy: 0 } ] [ @configBob ]))
            (set @entity.constraints [ { from: "pivot", to: @bobId, kind: "rod", color: "#94a3b8" } ])
            (set @entity.trails [ { id: @bobId, points: [ { x: @bobX, y: @bobY } ], color: (object/get @configBob color) } ])
            (set @entity.vectors [
              { body: @bobId, dx: 0, dy: (* @config.gravity @config.vectorScale), color: "#dc2626", label: "mg" },
              { body: @bobId, dx: (* @ux @tMag), dy: (* @uy @tMag), color: "#16a34a", label: "T" }
            ])
            (set @entity.angles [ { x: @pivotX, y: @pivotY, from: 90, to: @bearingDeg, radius: 24, color: "#0ea5e9", label: @thetaLabel } ])
            (set @entity.readouts [ { label: "θ", value: @thetaLabel } ])
            (set @entity.narration (str/concat "ready — bob at " (str/concat @thetaLabel " from vertical; press Step or Run to swing")))))
        (render-ui main {
          type: box
          padding: md
          children: [
            { type: stack, direction: vertical, gap: md, children: [
                @trait.PendulumTransport,
                { type: physics-canvas, width: @config.width, height: @config.height, backgroundColor: @config.backgroundColor, bodies: @entity.bodies, constraints: @entity.constraints, sceneObjects: @entity.sceneObjects, trails: @entity.trails, vectors: @entity.vectors, angles: @entity.angles, showVelocity: @config.showVelocity, showForces: false, velocityScale: @config.velocityScale, readouts: @entity.readouts },
                { type: typography, variant: body, content: @entity.narration }
              ] }
          ]
        })
        (emit PENDULUM_UPDATED { bodies: @entity.bodies, trails: @entity.trails, readouts: @entity.readouts, narration: @entity.narration })

      LEARN_UPDATED -> idle when (== @entity.active true)
        (render-ui main {
          type: box
          padding: md
          children: [
            { type: stack, direction: vertical, gap: md, children: [
                @trait.PendulumTransport,
                { type: physics-canvas, width: @config.width, height: @config.height, backgroundColor: @config.backgroundColor, bodies: @entity.bodies, constraints: @entity.constraints, sceneObjects: @entity.sceneObjects, trails: @entity.trails, vectors: @entity.vectors, angles: @entity.angles, showVelocity: @config.showVelocity, showForces: false, velocityScale: @config.velocityScale, readouts: @entity.readouts },
                { type: typography, variant: body, content: @entity.narration }
              ] }
          ]
        })
    }

    listens {
      PendulumTransport.LEARN_RESET -> LEARN_RESET
      PendulumTransport.LEARN_STEP -> LEARN_STEP
      PendulumTransport.LEARN_UPDATED -> LEARN_UPDATED
      MODE_SELECTED {
        mode : string
      }
        @description "Lab router broadcast naming the active mode; this instrument renders when the mode equals matchMode, otherwise renders null."
        @tier "domain"
      LEARN_STEP {
        steps : int
      }
        @description "One step of the transport clock or Step button (from the composed std-learn-transport trait); applies one substepped rigid-length projection pass."
        @tier "domain"
      LEARN_RESET {
      }
        @description "Transport Reset broadcast (from the composed std-learn-transport trait); reseeds the bodies, trails, vectors, angles, sceneObjects, constraints, and readouts from config."
        @tier "domain"
      LEARN_UPDATED {
        running : boolean
        steps : int
      }
        @description "Transport state broadcast on load and Run/Pause toggle (from the composed std-learn-transport trait); repaints the full shell so the strip's Run/Pause label and step caption stay fresh."
        @tier "domain"
    }

    emits {
      PENDULUM_UPDATED -> external {
        bodies : [PendulumBody]
        trails : [PendulumTrail]
        readouts : [PendulumReadout]
        narration : string
      }
        @description "The scene and computed angle-from-vertical readout after each step/toggle/reset — a composed listener (graph, readout, mirror canvas) can subscribe; a harmless no-op when the atom runs standalone."
        @synonyms "pendulum, simple pendulum, swing, rigid rod, period"
        @tier "domain"
    }

    config {
      matchMode : string = ""
        @label "Match Mode"
        @description "When composed behind a lab router, the MODE_SELECTED mode value this instrument responds to. Empty string means standalone — render immediately on INIT."
        @tier "presentation"
      substeps : number = 8
        @label "Substeps"
        @description "Integration substeps applied per Step press or tick, for smoother motion at a coarse UI cadence."
        @synonyms "integration steps, sub-steps, physics substeps"
        @tier "domain"
      gravity : number = 0.5
        @label "Gravity"
        @description "Downward acceleration added to the bob's vy every substep before the length projection."
        @tier "domain"
      damping : number = 0.995
        @label "Damping"
        @description "Fraction of the bob's velocity retained each substep (air resistance)."
        @tier "domain"
      length : number = 170
        @label "Length"
        @description "Rigid rod length — the radius the bob is projected back onto each substep."
        @tier "domain"
      pivotXFrac : number = 0.5
        @label "Pivot X Fraction"
        @description "Pivot's x, as a fraction of width."
        @tier "domain"
      pivotYFrac : number = 0.175
        @label "Pivot Y Fraction"
        @description "Pivot's y, as a fraction of height."
        @tier "domain"
      traceLength : number = 60
        @label "Trace Length"
        @description "Maximum bob-trail points retained; older points drop off the trail's tail."
        @synonyms "trail length, trace cap, history length"
        @tier "domain"
      vectorScale : number = 5
        @label "Vector Scale"
        @description "Length multiplier turning the gravity/tension magnitudes into visible labeled arrows."
        @tier "presentation"
      bodies : [PendulumBody] = [
        { id: "bob", x: 450, y: 110, radius: 18, color: "#2563eb", label: "", vx: 0, vy: 0, fx: 0, fy: 0 }
      ]
        @label "Bodies"
        @description "The single bob; x/y is its initial swung-out position, always re-projected onto the rod length around the computed pivot on INIT/MODE_SELECTED/RESET."
        @tier "presentation"
      width : number = 600
        @label "Width"
        @description "Simulation width in pixels."
        @tier "presentation"
      height : number = 400
        @label "Height"
        @description "Simulation height in pixels."
        @tier "presentation"
      backgroundColor : string = "#f8fafc"
        @label "Background Color"
        @description "Canvas background color."
        @tier "presentation"
      showVelocity : boolean = true
        @label "Show Velocity"
        @description "Draw the bob's built-in velocity arrow in addition to the labeled tension/gravity vectors."
        @tier "presentation"
      velocityScale : number = 5
        @label "Velocity Scale"
        @description "Length multiplier for the velocity arrow."
        @tier "presentation"
    }
  }

  page "/physics-pendulum" as PendulumEnginePage -> PendulumTransport, PendulumSim
}

app std-physics-collision "2.0.0"
"Elastic-collision engine — equal or per-body-mass circles exchange velocity along the collision normal and bounce off box walls, substepped for smooth motion; renders a physics-canvas with the wall box, per-body momentum vectors, an impact flash on colliding bodies, and total-momentum/kinetic-energy readouts. The Step/Run-Pause/Reset transport and the step clock come from the std-learn-transport atom (CollisionTransport); the elastic-collision integration lives in the sibling CollisionSim trait, which transitions directly on the transport's LEARN_STEP (applies one substepped collision-and-bounce pass), LEARN_RESET (reseeds bodies, walls, vectors, and readouts from config), and LEARN_UPDATED (full-shell repaint) broadcasts — delivered by the same bare-event cascade the lab routers use — and owns the full-shell scene render (the transport strip is embedded via @trait.CollisionTransport — one render authority per shared entity). Standalone by default; behind a lab router set matchMode and it renders only when MODE_SELECTED matches."
orbital CollisionEngineOrbital {
  type CollisionBody = {
    id : string
    x : number!
    y : number!
    radius : number
    color : string
    baseColor : string
    label : string
    vx : number
    vy : number
    fx : number
    fy : number
    mass : number
    collided : boolean
  }
  type CollisionVector = {
    body : string
    dx : number!
    dy : number!
    color : string
    label : string
  }
  type CollisionSceneObject = {
    kind : "wall"!
    x1 : number
    y1 : number
    x2 : number
    y2 : number
    color : string
    label : string
  }
  type CollisionReadout = {
    label : string!
    value : string!
    color : string
  }

  entity CollisionState [runtime, shared] {
    id : string!
    active : boolean = false
    title : string
    running : boolean = false
    steps : int = 0
    elapsedMs : number = 0
    done : boolean = false
    bodies : [CollisionBody]
    vectors : [CollisionVector]
    sceneObjects : [CollisionSceneObject]
    readouts : [CollisionReadout]
    narration : string
  }

  uses LearnTransport from "std/behaviors/std-learn-transport"

  trait CollisionTransport = LearnTransport.traits.LearnTransportSim -> CollisionState {
    config {
      title: "Elastic Collisions"
      stepIntervalMs: 500
    }
  }

  trait CollisionSim -> @rebindable CollisionState [interaction, instance] {
    initial: idle

    state idle {
      INIT -> idle when (== @config.matchMode "")
        (set @entity.done false)
        (set @entity.bodies @config.bodies)
        (set @entity.sceneObjects [
          { kind: "wall", x1: (* @config.width 0.02), y1: (* @config.height 0.02), x2: (- @config.width (* @config.width 0.02)), y2: (* @config.height 0.02), label: "" },
          { kind: "wall", x1: (* @config.width 0.02), y1: (- @config.height (* @config.height 0.02)), x2: (- @config.width (* @config.width 0.02)), y2: (- @config.height (* @config.height 0.02)), label: "" },
          { kind: "wall", x1: (* @config.width 0.02), y1: (* @config.height 0.02), x2: (* @config.width 0.02), y2: (- @config.height (* @config.height 0.02)), label: "" },
          { kind: "wall", x1: (- @config.width (* @config.width 0.02)), y1: (* @config.height 0.02), x2: (- @config.width (* @config.width 0.02)), y2: (- @config.height (* @config.height 0.02)), label: "" }
        ])
        (set @entity.vectors (array/map @config.bodies (fn b { body: (object/get @b id), dx: (* (* (object/get @b mass) (object/get @b vx)) @config.vectorScale), dy: (* (* (object/get @b mass) (object/get @b vy)) @config.vectorScale), color: "#7c3aed", label: "p" })))
        (let (
            (sumPx (array/reduce @config.bodies 0 (fn (acc b) (+ @acc (* (object/get @b mass) (object/get @b vx))))))
            (sumPy (array/reduce @config.bodies 0 (fn (acc b) (+ @acc (* (object/get @b mass) (object/get @b vy))))))
            (totalKE (array/reduce @config.bodies 0 (fn (acc b) (+ @acc (* 0.5 (* (object/get @b mass) (+ (* (object/get @b vx) (object/get @b vx)) (* (object/get @b vy) (object/get @b vy)))))))))
            (totalP (math/hypot @sumPx @sumPy))
          )
          (set @entity.readouts [
            { label: "Σp", value: (str/concat "" (math/round @totalP 2)) },
            { label: "ΣKE", value: (str/concat "" (math/round @totalKE 2)) }
          ]))
        (set @entity.narration "ready — press Step to advance the collisions")
        (render-ui main {
          type: box
          padding: md
          children: [
            { type: stack, direction: vertical, gap: md, children: [
                @trait.CollisionTransport,
                { type: physics-canvas, width: @config.width, height: @config.height, backgroundColor: @config.backgroundColor, bodies: @entity.bodies, sceneObjects: @entity.sceneObjects, vectors: @entity.vectors, showVelocity: @config.showVelocity, showForces: false, velocityScale: @config.velocityScale, readouts: @entity.readouts },
                { type: typography, variant: body, content: @entity.narration }
              ] }
          ]
        })
        (emit COLLISION_UPDATED { bodies: @entity.bodies, readouts: @entity.readouts, narration: @entity.narration })

      MODE_SELECTED -> idle when (== ?mode @config.matchMode)
        (set @entity.done false)
        (set @entity.bodies @config.bodies)
        (set @entity.sceneObjects [
          { kind: "wall", x1: (* @config.width 0.02), y1: (* @config.height 0.02), x2: (- @config.width (* @config.width 0.02)), y2: (* @config.height 0.02), label: "" },
          { kind: "wall", x1: (* @config.width 0.02), y1: (- @config.height (* @config.height 0.02)), x2: (- @config.width (* @config.width 0.02)), y2: (- @config.height (* @config.height 0.02)), label: "" },
          { kind: "wall", x1: (* @config.width 0.02), y1: (* @config.height 0.02), x2: (* @config.width 0.02), y2: (- @config.height (* @config.height 0.02)), label: "" },
          { kind: "wall", x1: (- @config.width (* @config.width 0.02)), y1: (* @config.height 0.02), x2: (- @config.width (* @config.width 0.02)), y2: (- @config.height (* @config.height 0.02)), label: "" }
        ])
        (set @entity.vectors (array/map @config.bodies (fn b { body: (object/get @b id), dx: (* (* (object/get @b mass) (object/get @b vx)) @config.vectorScale), dy: (* (* (object/get @b mass) (object/get @b vy)) @config.vectorScale), color: "#7c3aed", label: "p" })))
        (let (
            (sumPx (array/reduce @config.bodies 0 (fn (acc b) (+ @acc (* (object/get @b mass) (object/get @b vx))))))
            (sumPy (array/reduce @config.bodies 0 (fn (acc b) (+ @acc (* (object/get @b mass) (object/get @b vy))))))
            (totalKE (array/reduce @config.bodies 0 (fn (acc b) (+ @acc (* 0.5 (* (object/get @b mass) (+ (* (object/get @b vx) (object/get @b vx)) (* (object/get @b vy) (object/get @b vy)))))))))
            (totalP (math/hypot @sumPx @sumPy))
          )
          (set @entity.readouts [
            { label: "Σp", value: (str/concat "" (math/round @totalP 2)) },
            { label: "ΣKE", value: (str/concat "" (math/round @totalKE 2)) }
          ]))
        (set @entity.narration "ready — press Step to advance the collisions")
        (render-ui main {
          type: box
          padding: md
          children: [
            { type: stack, direction: vertical, gap: md, children: [
                @trait.CollisionTransport,
                { type: physics-canvas, width: @config.width, height: @config.height, backgroundColor: @config.backgroundColor, bodies: @entity.bodies, sceneObjects: @entity.sceneObjects, vectors: @entity.vectors, showVelocity: @config.showVelocity, showForces: false, velocityScale: @config.velocityScale, readouts: @entity.readouts },
                { type: typography, variant: body, content: @entity.narration }
              ] }
          ]
        })
        (emit COLLISION_UPDATED { bodies: @entity.bodies, readouts: @entity.readouts, narration: @entity.narration })

      LEARN_STEP -> idle when (and (== @entity.active true) (not (== @entity.done true)))
        (let (
            (sumPx0 (array/reduce @entity.bodies 0 (fn (acc b) (+ @acc (* (object/get @b mass) (object/get @b vx))))))
            (sumPy0 (array/reduce @entity.bodies 0 (fn (acc b) (+ @acc (* (object/get @b mass) (object/get @b vy))))))
            (totalP0 (math/hypot @sumPx0 @sumPy0))
            (newBodies (array/reduce (array/range @config.substeps) @entity.bodies (fn acc s
              (array/map @acc (fn b
                (let (
                  (r (object/get @b radius))
                )
                (let (
                  (cv (array/reduce @acc
                    { vx: (object/get @b vx), vy: (object/get @b vy), hit: false }
                    (fn (acc o)
                      (if (= (object/get @o id) (object/get @b id))
                        @acc
                        (let (
                          (dx (- (object/get @o x) (object/get @b x)))
                          (dy (- (object/get @o y) (object/get @b y)))
                        )
                        (let (
                          (dist (math/sqrt (+ (* @dx @dx) (* @dy @dy))))
                          (sumr (+ (object/get @b radius) (object/get @o radius)))
                        )
                        (if (and (< @dist @sumr) (> @dist 0))
                          (let (
                            (nx (/ @dx @dist))
                            (ny (/ @dy @dist))
                          )
                          (let (
                            (vrel (+ (* (- (object/get @acc vx) (object/get @o vx)) @nx)
                                     (* (- (object/get @acc vy) (object/get @o vy)) @ny)))
                          )
                          (if (> @vrel 0)
                            (object/merge @acc {
                              vx: (- (object/get @acc vx) (* @vrel @nx)),
                              vy: (- (object/get @acc vy) (* @vrel @ny)),
                              hit: true
                            })
                            @acc)))
                          @acc)))))))
                )
                (let (
                  (bvx (object/get @cv vx))
                  (bvy (object/get @cv vy))
                  (collided (object/get @cv hit))
                )
                (let (
                  (newvx (if (or (< (+ (object/get @b x) @bvx) @r) (> (+ (object/get @b x) @bvx) (- @config.width @r)))
                    (* @bvx -1)
                    @bvx))
                  (newvy (if (or (< (+ (object/get @b y) @bvy) @r) (> (+ (object/get @b y) @bvy) (- @config.height @r)))
                    (* @bvy -1)
                    @bvy))
                )
                (let (
                  (nx (math/clamp (+ (object/get @b x) @newvx) @r (- @config.width @r)))
                  (ny (math/clamp (+ (object/get @b y) @newvy) @r (- @config.height @r)))
                )
                (object/merge @b {
                  x: @nx,
                  y: @ny,
                  vx: @newvx,
                  vy: @newvy,
                  collided: @collided,
                  color: (if @collided @config.flashColor (object/get @b baseColor))
                })))))))))))
            (anyCollided (array/reduce @newBodies false (fn (acc b) (or @acc (object/get @b collided)))))
            (sumPx (array/reduce @newBodies 0 (fn (acc b) (+ @acc (* (object/get @b mass) (object/get @b vx))))))
            (sumPy (array/reduce @newBodies 0 (fn (acc b) (+ @acc (* (object/get @b mass) (object/get @b vy))))))
            (totalKE (array/reduce @newBodies 0 (fn (acc b) (+ @acc (* 0.5 (* (object/get @b mass) (+ (* (object/get @b vx) (object/get @b vx)) (* (object/get @b vy) (object/get @b vy)))))))))
            (totalP (math/hypot @sumPx @sumPy))
          )
          (do
            (set @entity.bodies @newBodies)
            (set @entity.vectors (array/map @newBodies (fn b { body: (object/get @b id), dx: (* (* (object/get @b mass) (object/get @b vx)) @config.vectorScale), dy: (* (* (object/get @b mass) (object/get @b vy)) @config.vectorScale), color: "#7c3aed", label: "p" })))
            (set @entity.readouts [
              { label: "Σp", value: (str/concat "" (math/round @totalP 2)) },
              { label: "ΣKE", value: (str/concat "" (math/round @totalKE 2)) }
            ])
            (if @anyCollided
              (set @entity.narration (str/concat "impact — Σp before " (str/concat (str/concat "" (math/round @totalP0 2)) (str/concat ", after " (str/concat "" (math/round @totalP 2))))))
              (set @entity.narration (str/concat "Σp=" (str/concat (str/concat "" (math/round @totalP 2)) (str/concat ", ΣKE=" (str/concat "" (math/round @totalKE 2)))))))))
        (render-ui main {
          type: box
          padding: md
          children: [
            { type: stack, direction: vertical, gap: md, children: [
                @trait.CollisionTransport,
                { type: physics-canvas, width: @config.width, height: @config.height, backgroundColor: @config.backgroundColor, bodies: @entity.bodies, sceneObjects: @entity.sceneObjects, vectors: @entity.vectors, showVelocity: @config.showVelocity, showForces: false, velocityScale: @config.velocityScale, readouts: @entity.readouts },
                { type: typography, variant: body, content: @entity.narration }
              ] }
          ]
        })
        (emit COLLISION_UPDATED { bodies: @entity.bodies, readouts: @entity.readouts, narration: @entity.narration })

      LEARN_RESET -> idle when (== @entity.active true)
        (set @entity.done false)
        (set @entity.bodies @config.bodies)
        (set @entity.sceneObjects [
          { kind: "wall", x1: (* @config.width 0.02), y1: (* @config.height 0.02), x2: (- @config.width (* @config.width 0.02)), y2: (* @config.height 0.02), label: "" },
          { kind: "wall", x1: (* @config.width 0.02), y1: (- @config.height (* @config.height 0.02)), x2: (- @config.width (* @config.width 0.02)), y2: (- @config.height (* @config.height 0.02)), label: "" },
          { kind: "wall", x1: (* @config.width 0.02), y1: (* @config.height 0.02), x2: (* @config.width 0.02), y2: (- @config.height (* @config.height 0.02)), label: "" },
          { kind: "wall", x1: (- @config.width (* @config.width 0.02)), y1: (* @config.height 0.02), x2: (- @config.width (* @config.width 0.02)), y2: (- @config.height (* @config.height 0.02)), label: "" }
        ])
        (set @entity.vectors (array/map @config.bodies (fn b { body: (object/get @b id), dx: (* (* (object/get @b mass) (object/get @b vx)) @config.vectorScale), dy: (* (* (object/get @b mass) (object/get @b vy)) @config.vectorScale), color: "#7c3aed", label: "p" })))
        (let (
            (sumPx (array/reduce @config.bodies 0 (fn (acc b) (+ @acc (* (object/get @b mass) (object/get @b vx))))))
            (sumPy (array/reduce @config.bodies 0 (fn (acc b) (+ @acc (* (object/get @b mass) (object/get @b vy))))))
            (totalKE (array/reduce @config.bodies 0 (fn (acc b) (+ @acc (* 0.5 (* (object/get @b mass) (+ (* (object/get @b vx) (object/get @b vx)) (* (object/get @b vy) (object/get @b vy)))))))))
            (totalP (math/hypot @sumPx @sumPy))
          )
          (set @entity.readouts [
            { label: "Σp", value: (str/concat "" (math/round @totalP 2)) },
            { label: "ΣKE", value: (str/concat "" (math/round @totalKE 2)) }
          ]))
        (set @entity.narration "ready — press Step to advance the collisions")
        (render-ui main {
          type: box
          padding: md
          children: [
            { type: stack, direction: vertical, gap: md, children: [
                @trait.CollisionTransport,
                { type: physics-canvas, width: @config.width, height: @config.height, backgroundColor: @config.backgroundColor, bodies: @entity.bodies, sceneObjects: @entity.sceneObjects, vectors: @entity.vectors, showVelocity: @config.showVelocity, showForces: false, velocityScale: @config.velocityScale, readouts: @entity.readouts },
                { type: typography, variant: body, content: @entity.narration }
              ] }
          ]
        })
        (emit COLLISION_UPDATED { bodies: @entity.bodies, readouts: @entity.readouts, narration: @entity.narration })

      LEARN_UPDATED -> idle when (== @entity.active true)
        (render-ui main {
          type: box
          padding: md
          children: [
            { type: stack, direction: vertical, gap: md, children: [
                @trait.CollisionTransport,
                { type: physics-canvas, width: @config.width, height: @config.height, backgroundColor: @config.backgroundColor, bodies: @entity.bodies, sceneObjects: @entity.sceneObjects, vectors: @entity.vectors, showVelocity: @config.showVelocity, showForces: false, velocityScale: @config.velocityScale, readouts: @entity.readouts },
                { type: typography, variant: body, content: @entity.narration }
              ] }
          ]
        })
    }

    listens {
      CollisionTransport.LEARN_RESET -> LEARN_RESET
      CollisionTransport.LEARN_STEP -> LEARN_STEP
      CollisionTransport.LEARN_UPDATED -> LEARN_UPDATED
      MODE_SELECTED {
        mode : string
      }
        @description "Lab router broadcast naming the active mode; this instrument renders when the mode equals matchMode, otherwise renders null."
        @tier "domain"
      LEARN_STEP {
        steps : int
      }
        @description "One step of the transport clock or Step button (from the composed std-learn-transport trait); applies one substepped elastic-collision-and-bounce pass."
        @tier "domain"
      LEARN_RESET {
      }
        @description "Transport Reset broadcast (from the composed std-learn-transport trait); reseeds the bodies, walls, vectors, and readouts from config."
        @tier "domain"
      LEARN_UPDATED {
        running : boolean
        steps : int
      }
        @description "Transport state broadcast on load and Run/Pause toggle (from the composed std-learn-transport trait); repaints the full shell so the strip's Run/Pause label and step caption stay fresh."
        @tier "domain"
    }

    emits {
      COLLISION_UPDATED -> external {
        bodies : [CollisionBody]
        readouts : [CollisionReadout]
        narration : string
      }
        @description "The scene and computed total-momentum/kinetic-energy readouts after each step/toggle/reset — a composed listener (graph, readout, mirror canvas) can subscribe; a harmless no-op when the atom runs standalone."
        @synonyms "collision, elastic collision, momentum, kinetic energy, impact, bounce"
        @tier "domain"
    }

    config {
      matchMode : string = ""
        @label "Match Mode"
        @description "When composed behind a lab router, the MODE_SELECTED mode value this instrument responds to. Empty string means standalone — render immediately on INIT."
        @tier "presentation"
      substeps : number = 8
        @label "Substeps"
        @description "Integration substeps applied per Step press or tick, for smoother motion at a coarse UI cadence."
        @synonyms "integration steps, sub-steps, physics substeps"
        @tier "domain"
      flashColor : string = "#fde047"
        @label "Impact Flash Color"
        @description "Color a body swaps to for the substep it registers a collision, before returning to its base color."
        @tier "presentation"
      width : number = 600
        @label "Width"
        @description "Simulation width in pixels; bounds the wall box."
        @tier "presentation"
      height : number = 400
        @label "Height"
        @description "Simulation height in pixels; bounds the wall box."
        @tier "presentation"
      backgroundColor : string = "#f8fafc"
        @label "Background Color"
        @description "Canvas background color."
        @tier "presentation"
      showVelocity : boolean = true
        @label "Show Velocity"
        @description "Draw each body's velocity vector as an arrow."
        @tier "presentation"
      velocityScale : number = 10
        @label "Velocity Scale"
        @description "Length multiplier for the built-in velocity arrows."
        @tier "presentation"
      vectorScale : number = 3
        @label "Momentum Vector Scale"
        @description "Length multiplier for the labeled momentum (p = m·v) vectors."
        @tier "presentation"
      bodies : [CollisionBody] = [
        { id: "ball-a", x: 80, y: 200, radius: 16, color: "#2563eb", baseColor: "#2563eb", label: "A", vx: 5, vy: 0, fx: 0, fy: 0, mass: 1, collided: false },
        { id: "ball-b", x: 520, y: 200, radius: 16, color: "#16a34a", baseColor: "#16a34a", label: "B", vx: -5, vy: 0, fx: 0, fy: 0, mass: 1, collided: false },
        { id: "ball-c", x: 300, y: 90, radius: 16, color: "#dc2626", baseColor: "#dc2626", label: "C", vx: 0, vy: 4, fx: 0, fy: 0, mass: 1, collided: false },
        { id: "ball-d", x: 300, y: 320, radius: 16, color: "#f59e0b", baseColor: "#f59e0b", label: "D", vx: 0, vy: -4, fx: 0, fy: 0, mass: 1, collided: false }
      ]
        @label "Bodies"
        @description "Initial equal-radius bodies on collision courses: A/B head-on, C/D head-on, crossing paths; each carries its own mass so uneven masses can be modeled."
        @tier "presentation"
    }
  }

  page "/physics-collision" as CollisionEnginePage -> CollisionTransport, CollisionSim
}

app std-chem-reaction "2.0.0"
"Reversible reaction engine — pairCount A+B pairs run one kinetic interval per Step: each dissociated pair draws against kf to form, each bonded pair draws against kr to break, and positions glide toward the bonded center or back to their home over substeps; bonds mark forming/breaking/highlight and narration claims equilibrium only when the bonded count doesn't net change. The Step/Run-Pause/Reset transport and the step clock come from the std-learn-transport atom (ChemReactionTransport); the reaction kinetics live in the sibling ChemReactionSim trait, which transitions directly on the transport's LEARN_STEP (applies one kf/kr draw-and-glide interval), LEARN_RESET (reseeds atoms, pairs, bonds, and readouts from config), and LEARN_UPDATED (full-shell repaint) broadcasts — delivered by the same bare-event cascade the lab routers use — and owns the full-shell scene render (the transport strip is embedded via @trait.ChemReactionTransport — one render authority per shared entity). Reaction never explicitly terminates in this atom — done stays false, there is no rest/completion condition currently wired. Standalone by default; behind a lab router set matchMode and it renders only when MODE_SELECTED matches."
orbital ChemReactionEngineOrbital {
  type ChemAtom = {
    id : string
    x : number!
    y : number!
    element : string
    radius : number
    color : string
    home : number
    pairId : string
  }
  type ChemBond = {
    from : string!
    to : string!
    type : "single" | "double" | "triple"
    state : "default" | "forming" | "breaking" | "highlight"
  }
  type ChemPairState = {
    id : string
    bonded : boolean
  }
  type ChemReadout = {
    label : string
    value : string
  }

  entity ChemReactionState [runtime, shared] {
    id : string!
    active : boolean = false
    title : string
    running : boolean = false
    steps : int = 0
    elapsedMs : number = 0
    done : boolean = false
    atoms : [ChemAtom]
    pairs : [ChemPairState]
    bonds : [ChemBond]
    readouts : [ChemReadout]
    narration : string
  }

  uses LearnTransport from "std/behaviors/std-learn-transport"

  trait ChemReactionTransport = LearnTransport.traits.LearnTransportSim -> ChemReactionState {
    config {
      title: "Chemical Reaction"
      stepIntervalMs: 550
    }
  }

  trait ChemReactionSim -> @rebindable ChemReactionState [interaction, instance] {
    initial: idle

    state idle {
      INIT -> idle when (== @config.matchMode "")
        (set @entity.done false)
        (set @entity.pairs (array/map (array/range @config.pairCount) (fn j
          { id: (str/concat "p" (str/concat "" @j)), bonded: false })))
        (set @entity.atoms (array/flatten (array/map (array/range @config.pairCount) (fn j
          (let (
              (rowY (* @config.height (/ (+ @j 0.5) @config.pairCount)))
              (homeA (* @config.width 0.25))
              (homeB (* @config.width 0.75))
            )
            [ { id: (str/concat "a" (str/concat "" @j)), x: @homeA, y: @rowY, element: "A", radius: @config.atomRadius, color: @config.colorA, home: @homeA, pairId: (str/concat "p" (str/concat "" @j)) },
              { id: (str/concat "b" (str/concat "" @j)), x: @homeB, y: @rowY, element: "B", radius: @config.atomRadius, color: @config.colorB, home: @homeB, pairId: (str/concat "p" (str/concat "" @j)) } ])))))
        (set @entity.bonds (array/map @entity.pairs (fn pr
          { from: (str/concat "a" (str/concat "" (object/get @pr id))), to: (str/concat "b" (str/concat "" (object/get @pr id))), type: "single", state: "default" })))
        (set @entity.readouts [
          { label: "A", value: (str/concat "" @config.pairCount) },
          { label: "B", value: (str/concat "" @config.pairCount) },
          { label: "AB", value: "0" }
        ])
        (set @entity.narration (str/concat "" (str/concat @config.pairCount " A+B pairs at rest — press Step to run one reaction interval")))
        (render-ui main {
          type: box
          padding: md
          children: [
            { type: stack, direction: vertical, gap: md, children: [
                @trait.ChemReactionTransport,
                { type: chemistry-canvas, width: @config.width, height: @config.height, backgroundColor: @config.backgroundColor, equation: @config.equation, atoms: @entity.atoms, bonds: @entity.bonds, readouts: @entity.readouts },
                { type: typography, variant: body, content: @entity.narration }
              ] }
          ]
        })
        (emit REACTION_UPDATED { atoms: @entity.atoms, bonds: @entity.bonds, readouts: @entity.readouts, narration: @entity.narration })

      MODE_SELECTED -> idle when (== ?mode @config.matchMode)
        (set @entity.done false)
        (set @entity.pairs (array/map (array/range @config.pairCount) (fn j
          { id: (str/concat "p" (str/concat "" @j)), bonded: false })))
        (set @entity.atoms (array/flatten (array/map (array/range @config.pairCount) (fn j
          (let (
              (rowY (* @config.height (/ (+ @j 0.5) @config.pairCount)))
              (homeA (* @config.width 0.25))
              (homeB (* @config.width 0.75))
            )
            [ { id: (str/concat "a" (str/concat "" @j)), x: @homeA, y: @rowY, element: "A", radius: @config.atomRadius, color: @config.colorA, home: @homeA, pairId: (str/concat "p" (str/concat "" @j)) },
              { id: (str/concat "b" (str/concat "" @j)), x: @homeB, y: @rowY, element: "B", radius: @config.atomRadius, color: @config.colorB, home: @homeB, pairId: (str/concat "p" (str/concat "" @j)) } ])))))
        (set @entity.bonds (array/map @entity.pairs (fn pr
          { from: (str/concat "a" (str/concat "" (object/get @pr id))), to: (str/concat "b" (str/concat "" (object/get @pr id))), type: "single", state: "default" })))
        (set @entity.readouts [
          { label: "A", value: (str/concat "" @config.pairCount) },
          { label: "B", value: (str/concat "" @config.pairCount) },
          { label: "AB", value: "0" }
        ])
        (set @entity.narration (str/concat "" (str/concat @config.pairCount " A+B pairs at rest — press Step to run one reaction interval")))
        (render-ui main {
          type: box
          padding: md
          children: [
            { type: stack, direction: vertical, gap: md, children: [
                @trait.ChemReactionTransport,
                { type: chemistry-canvas, width: @config.width, height: @config.height, backgroundColor: @config.backgroundColor, equation: @config.equation, atoms: @entity.atoms, bonds: @entity.bonds, readouts: @entity.readouts },
                { type: typography, variant: body, content: @entity.narration }
              ] }
          ]
        })
        (emit REACTION_UPDATED { atoms: @entity.atoms, bonds: @entity.bonds, readouts: @entity.readouts, narration: @entity.narration })

      LEARN_STEP -> idle when (and (== @entity.active true) (not (== @entity.done true)))
        (let (
            (decided (array/map @entity.pairs (fn pr
              (let (
                  (prevBonded (object/get @pr bonded))
                  (roll (math/random))
                )
                (let (
                    (newBonded (if @prevBonded (>= @roll @config.kr) (< @roll @config.kf)))
                  )
                  { id: (object/get @pr id), bonded: @newBonded, prevBonded: @prevBonded })))))
          )
          (let (
              (formedCount (array/len (array/filter @decided (fn d (and (object/get @d bonded) (not (object/get @d prevBonded)))))))
              (brokenCount (array/len (array/filter @decided (fn d (and (not (object/get @d bonded)) (object/get @d prevBonded))))))
            )
            (let (
                (moved (array/reduce (array/range @config.substeps) @entity.atoms (fn acc i
                  (array/map @acc (fn a
                    (let (
                        (pr (array/find @decided (fn d (== (object/get @d id) (object/get @a pairId)))))
                      )
                      (let (
                          (bonded (object/get @pr bonded))
                        )
                        (let (
                            (targetX (if @bonded (* @config.width 0.5) (object/get @a home)))
                          )
                          (object/merge @a { x: (math/lerp (object/get @a x) @targetX (/ 1 @config.substeps)) })))))))))
              )
              (let (
                  (bonds (array/map @decided (fn d
                    { from: (str/concat "a" (str/concat "" (object/get @d id))), to: (str/concat "b" (str/concat "" (object/get @d id))), type: "single",
                      state: (if (and (object/get @d bonded) (not (object/get @d prevBonded))) "forming"
                               (if (and (not (object/get @d bonded)) (object/get @d prevBonded)) "breaking"
                                 (if (object/get @d bonded) "highlight" "default"))) })))
                  (newPairs (array/map @decided (fn d { id: (object/get @d id), bonded: (object/get @d bonded) })))
                  (bondedCount (array/len (array/filter @decided (fn d (object/get @d bonded)))))
                  (totalPairs (array/len @decided))
                  (netChange (- @formedCount @brokenCount))
                )
                (do
                  (set @entity.atoms @moved)
                  (set @entity.pairs @newPairs)
                  (set @entity.bonds @bonds)
                  (set @entity.readouts [
                    { label: "A", value: (str/concat "" (- @totalPairs @bondedCount)) },
                    { label: "B", value: (str/concat "" (- @totalPairs @bondedCount)) },
                    { label: "AB", value: (str/concat "" @bondedCount) }
                  ])
                  (set @entity.narration (if (== @netChange 0)
                    (str/concat "at equilibrium — " (str/concat (str/concat "" @formedCount) (str/concat " formed, " (str/concat (str/concat "" @brokenCount) (str/concat " broke this step, AB=" (str/concat "" @bondedCount))))))
                    (str/concat "reacting — " (str/concat (str/concat "" @formedCount) (str/concat " formed, " (str/concat (str/concat "" @brokenCount) (str/concat " broke this step, AB=" (str/concat "" @bondedCount))))))))))))
        )
        (render-ui main {
          type: box
          padding: md
          children: [
            { type: stack, direction: vertical, gap: md, children: [
                @trait.ChemReactionTransport,
                { type: chemistry-canvas, width: @config.width, height: @config.height, backgroundColor: @config.backgroundColor, equation: @config.equation, atoms: @entity.atoms, bonds: @entity.bonds, readouts: @entity.readouts },
                { type: typography, variant: body, content: @entity.narration }
              ] }
          ]
        })
        (emit REACTION_UPDATED { atoms: @entity.atoms, bonds: @entity.bonds, readouts: @entity.readouts, narration: @entity.narration })

      LEARN_RESET -> idle when (== @entity.active true)
        (set @entity.done false)
        (set @entity.pairs (array/map (array/range @config.pairCount) (fn j
          { id: (str/concat "p" (str/concat "" @j)), bonded: false })))
        (set @entity.atoms (array/flatten (array/map (array/range @config.pairCount) (fn j
          (let (
              (rowY (* @config.height (/ (+ @j 0.5) @config.pairCount)))
              (homeA (* @config.width 0.25))
              (homeB (* @config.width 0.75))
            )
            [ { id: (str/concat "a" (str/concat "" @j)), x: @homeA, y: @rowY, element: "A", radius: @config.atomRadius, color: @config.colorA, home: @homeA, pairId: (str/concat "p" (str/concat "" @j)) },
              { id: (str/concat "b" (str/concat "" @j)), x: @homeB, y: @rowY, element: "B", radius: @config.atomRadius, color: @config.colorB, home: @homeB, pairId: (str/concat "p" (str/concat "" @j)) } ])))))
        (set @entity.bonds (array/map @entity.pairs (fn pr
          { from: (str/concat "a" (str/concat "" (object/get @pr id))), to: (str/concat "b" (str/concat "" (object/get @pr id))), type: "single", state: "default" })))
        (set @entity.readouts [
          { label: "A", value: (str/concat "" @config.pairCount) },
          { label: "B", value: (str/concat "" @config.pairCount) },
          { label: "AB", value: "0" }
        ])
        (set @entity.narration (str/concat "" (str/concat @config.pairCount " A+B pairs at rest — press Step to run one reaction interval")))
        (render-ui main {
          type: box
          padding: md
          children: [
            { type: stack, direction: vertical, gap: md, children: [
                @trait.ChemReactionTransport,
                { type: chemistry-canvas, width: @config.width, height: @config.height, backgroundColor: @config.backgroundColor, equation: @config.equation, atoms: @entity.atoms, bonds: @entity.bonds, readouts: @entity.readouts },
                { type: typography, variant: body, content: @entity.narration }
              ] }
          ]
        })
        (emit REACTION_UPDATED { atoms: @entity.atoms, bonds: @entity.bonds, readouts: @entity.readouts, narration: @entity.narration })

      LEARN_UPDATED -> idle when (== @entity.active true)
        (render-ui main {
          type: box
          padding: md
          children: [
            { type: stack, direction: vertical, gap: md, children: [
                @trait.ChemReactionTransport,
                { type: chemistry-canvas, width: @config.width, height: @config.height, backgroundColor: @config.backgroundColor, equation: @config.equation, atoms: @entity.atoms, bonds: @entity.bonds, readouts: @entity.readouts },
                { type: typography, variant: body, content: @entity.narration }
              ] }
          ]
        })
    }

    listens {
      ChemReactionTransport.LEARN_RESET -> LEARN_RESET
      ChemReactionTransport.LEARN_STEP -> LEARN_STEP
      ChemReactionTransport.LEARN_UPDATED -> LEARN_UPDATED
      MODE_SELECTED {
        mode : string
      }
        @description "Lab router broadcast naming the active mode; this instrument renders when the mode equals matchMode, otherwise renders null."
        @tier "domain"
      LEARN_STEP {
        steps : int
      }
        @description "One step of the transport clock or Step button (from the composed std-learn-transport trait); applies one kf/kr bond draw-and-glide reaction interval."
        @tier "domain"
      LEARN_RESET {
      }
        @description "Transport Reset broadcast (from the composed std-learn-transport trait); reseeds the atoms, pairs, bonds, and readouts from config."
        @tier "domain"
      LEARN_UPDATED {
        running : boolean
        steps : int
      }
        @description "Transport state broadcast on load and Run/Pause toggle (from the composed std-learn-transport trait); repaints the full shell so the strip's Run/Pause label and step caption stay fresh."
        @tier "domain"
    }

    emits {
      REACTION_UPDATED -> external {
        atoms : [ChemAtom]
        bonds : [ChemBond]
        readouts : [ChemReadout]
        narration : string
      }
        @description "The atom/bond scene and A/B/AB readouts after each step/toggle/reset — a composed listener (graph, readout, mirror canvas) can subscribe; a harmless no-op when the atom runs standalone."
        @synonyms "reversible reaction, chemical equilibrium, forward rate, reverse rate, bond forming, bond breaking, kinetics"
        @tier "domain"
    }

    config {
      matchMode : string = ""
        @label "Match Mode"
        @description "When composed behind a lab router, the MODE_SELECTED mode value this instrument responds to. Empty string means standalone — render immediately on INIT."
        @tier "presentation"
      pairCount : number = 4
        @label "Pair Count"
        @description "Number of independent A+B pairs tracked; each draws its own kf/kr roll every interval."
        @tier "domain"
      kf : number = 0.35
        @label "Forward Rate (kf)"
        @description "Probability a currently-dissociated pair forms a bond this interval."
        @synonyms "forward rate constant, association probability, bond formation rate"
        @tier "domain"
      kr : number = 0.25
        @label "Reverse Rate (kr)"
        @description "Probability a currently-bonded pair breaks this interval."
        @synonyms "reverse rate constant, dissociation probability, bond breaking rate"
        @tier "domain"
      substeps : number = 8
        @label "Substeps"
        @description "Position-glide iterations applied per Step press or per tick, easing each atom toward the bonded center or back to its home."
        @tier "domain"
      atomRadius : number = 12
        @label "Atom Radius"
        @description "Drawn radius of each atom, in pixels."
        @tier "presentation"
      colorA : string = "#dc2626"
        @label "Species A Color"
        @description "Fill color for A atoms."
        @tier "presentation"
      colorB : string = "#2563eb"
        @label "Species B Color"
        @description "Fill color for B atoms."
        @tier "presentation"
      equation : string = "A + B ⇌ AB"
        @label "Equation"
        @description "Reaction equation shown centered above the canvas."
        @tier "presentation"
      width : number = 600
        @label "Width"
        @description "Canvas width in pixels; the bonded center is width * 0.5."
        @tier "presentation"
      height : number = 400
        @label "Height"
        @description "Canvas height in pixels."
        @tier "presentation"
      backgroundColor : string = "#f8fafc"
        @label "Background Color"
        @description "Canvas background color."
        @tier "presentation"
    }
  }

  page "/chem-reaction" as ChemReactionEnginePage -> ChemReactionTransport, ChemReactionSim
}

app std-chem-diffusion "2.0.0"
"Diffusion engine — two color-coded gases random-walk across a shared box; each Step applies substeps of the walk, and honest narration only claims mixing when the left/right species imbalance actually shrank that step. The Step/Run-Pause/Reset transport and the step clock come from the std-learn-transport atom (ChemDiffusionTransport); the random-walk diffusion lives in the sibling ChemDiffusionSim trait, which transitions directly on the transport's LEARN_STEP (applies one substepped random-walk pass), LEARN_RESET (reseeds particles, containers, readouts, and narration from config), and LEARN_UPDATED (full-shell repaint) broadcasts — delivered by the same bare-event cascade the lab routers use — and owns the full-shell scene render (the transport strip is embedded via @trait.ChemDiffusionTransport — one render authority per shared entity). Diffusion never terminates — done stays false always, there is no rest/completion condition to detect. Standalone by default; behind a lab router set matchMode and it renders only when MODE_SELECTED matches."
orbital ChemDiffusionOrbital {
  type ChemParticle = {
    id : string
    x : number!
    y : number!
    element : string
    radius : number
    color : string
  }
  type ChemContainer = {
    x : number
    y : number
    width : number
    height : number
    divider : "none" | "solid" | "dashed" | "dotted"
    leftLabel : string
    rightLabel : string
  }
  type ChemReadout = {
    label : string
    value : string
  }

  entity ChemDiffusionState [runtime, shared] {
    id : string!
    active : boolean = false
    title : string
    running : boolean = false
    steps : int = 0
    elapsedMs : number = 0
    done : boolean = false
    particles : [ChemParticle]
    containers : [ChemContainer]
    readouts : [ChemReadout]
    imbalance : number = 0
    narration : string
  }

  uses LearnTransport from "std/behaviors/std-learn-transport"

  trait ChemDiffusionTransport = LearnTransport.traits.LearnTransportSim -> ChemDiffusionState {
    config {
      title: "Diffusion"
      stepIntervalMs: 500
    }
  }

  trait ChemDiffusionSim -> @rebindable ChemDiffusionState [interaction, instance] {
    initial: idle

    state idle {
      INIT -> idle when (== @config.matchMode "")
        (set @entity.done false)
        (set @entity.particles (array/map (array/range @config.particleCount) (fn i
          (let (
              (half (/ @config.particleCount 2))
              (isA (< @i @half))
            )
            (let (
                (idxInSpecies (if @isA @i (- @i @half)))
              )
              (let (
                  (colParity (math/mod @idxInSpecies 2))
                  (rowNum (math/floor (/ @idxInSpecies 2)))
                )
                { id: (str/concat "p" (str/concat "" @i)),
                  x: (if @isA (* @config.width (+ 0.08 (* @colParity 0.06))) (* @config.width (- 0.92 (* @colParity 0.06)))),
                  y: (* @config.height (+ 0.1 (* @rowNum 0.11))),
                  element: (if @isA "A" "B"),
                  radius: @config.particleRadius,
                  color: (if @isA @config.colorA @config.colorB) }))))))
        (let (
            (dividerX (* @config.width 0.5))
          )
          (let (
              (aLeft (array/len (array/filter @entity.particles (fn p (and (== (object/get @p element) "A") (< (object/get @p x) @dividerX))))))
              (aRight (array/len (array/filter @entity.particles (fn p (and (== (object/get @p element) "A") (>= (object/get @p x) @dividerX))))))
              (bLeft (array/len (array/filter @entity.particles (fn p (and (== (object/get @p element) "B") (< (object/get @p x) @dividerX))))))
              (bRight (array/len (array/filter @entity.particles (fn p (and (== (object/get @p element) "B") (>= (object/get @p x) @dividerX))))))
            )
            (do
              (set @entity.imbalance (+ (math/abs (- @aLeft @aRight)) (math/abs (- @bLeft @bRight))))
              (set @entity.containers [{ x: 0, y: 0, width: @config.width, height: @config.height, divider: "solid", leftLabel: (str/concat "L " (str/concat "" (+ @aLeft @bLeft))), rightLabel: (str/concat "R " (str/concat "" (+ @aRight @bRight))) }])
              (set @entity.readouts [
                { label: "A left", value: (str/concat "" @aLeft) },
                { label: "A right", value: (str/concat "" @aRight) },
                { label: "B left", value: (str/concat "" @bLeft) },
                { label: "B right", value: (str/concat "" @bRight) }
              ])
              (set @entity.narration "gases separated — press Step to random-walk them together"))))
        (render-ui main {
          type: box
          padding: md
          children: [
            { type: stack, direction: vertical, gap: md, children: [
                @trait.ChemDiffusionTransport,
                { type: chemistry-canvas, width: @config.width, height: @config.height, backgroundColor: @config.backgroundColor, atoms: @entity.particles, containers: @entity.containers, readouts: @entity.readouts },
                { type: typography, variant: body, content: @entity.narration }
              ] }
          ]
        })
        (emit DIFFUSION_UPDATED { particles: @entity.particles, containers: @entity.containers, readouts: @entity.readouts, narration: @entity.narration })

      MODE_SELECTED -> idle when (== ?mode @config.matchMode)
        (set @entity.done false)
        (set @entity.particles (array/map (array/range @config.particleCount) (fn i
          (let (
              (half (/ @config.particleCount 2))
              (isA (< @i @half))
            )
            (let (
                (idxInSpecies (if @isA @i (- @i @half)))
              )
              (let (
                  (colParity (math/mod @idxInSpecies 2))
                  (rowNum (math/floor (/ @idxInSpecies 2)))
                )
                { id: (str/concat "p" (str/concat "" @i)),
                  x: (if @isA (* @config.width (+ 0.08 (* @colParity 0.06))) (* @config.width (- 0.92 (* @colParity 0.06)))),
                  y: (* @config.height (+ 0.1 (* @rowNum 0.11))),
                  element: (if @isA "A" "B"),
                  radius: @config.particleRadius,
                  color: (if @isA @config.colorA @config.colorB) }))))))
        (let (
            (dividerX (* @config.width 0.5))
          )
          (let (
              (aLeft (array/len (array/filter @entity.particles (fn p (and (== (object/get @p element) "A") (< (object/get @p x) @dividerX))))))
              (aRight (array/len (array/filter @entity.particles (fn p (and (== (object/get @p element) "A") (>= (object/get @p x) @dividerX))))))
              (bLeft (array/len (array/filter @entity.particles (fn p (and (== (object/get @p element) "B") (< (object/get @p x) @dividerX))))))
              (bRight (array/len (array/filter @entity.particles (fn p (and (== (object/get @p element) "B") (>= (object/get @p x) @dividerX))))))
            )
            (do
              (set @entity.imbalance (+ (math/abs (- @aLeft @aRight)) (math/abs (- @bLeft @bRight))))
              (set @entity.containers [{ x: 0, y: 0, width: @config.width, height: @config.height, divider: "solid", leftLabel: (str/concat "L " (str/concat "" (+ @aLeft @bLeft))), rightLabel: (str/concat "R " (str/concat "" (+ @aRight @bRight))) }])
              (set @entity.readouts [
                { label: "A left", value: (str/concat "" @aLeft) },
                { label: "A right", value: (str/concat "" @aRight) },
                { label: "B left", value: (str/concat "" @bLeft) },
                { label: "B right", value: (str/concat "" @bRight) }
              ])
              (set @entity.narration "gases separated — press Step to random-walk them together"))))
        (render-ui main {
          type: box
          padding: md
          children: [
            { type: stack, direction: vertical, gap: md, children: [
                @trait.ChemDiffusionTransport,
                { type: chemistry-canvas, width: @config.width, height: @config.height, backgroundColor: @config.backgroundColor, atoms: @entity.particles, containers: @entity.containers, readouts: @entity.readouts },
                { type: typography, variant: body, content: @entity.narration }
              ] }
          ]
        })
        (emit DIFFUSION_UPDATED { particles: @entity.particles, containers: @entity.containers, readouts: @entity.readouts, narration: @entity.narration })

      LEARN_STEP -> idle when (and (== @entity.active true) (not (== @entity.done true)))
        (let (
            (moved (array/reduce (array/range @config.substeps) @entity.particles (fn acc i
              (array/map @acc (fn p
                (let (
                    (r (object/get @p radius))
                  )
                  (let (
                      (nx (math/clamp (+ (object/get @p x) (- (* (math/random) (* 2 @config.jitter)) @config.jitter)) @r (- @config.width @r)))
                      (ny (math/clamp (+ (object/get @p y) (- (* (math/random) (* 2 @config.jitter)) @config.jitter)) @r (- @config.height @r)))
                    )
                    (object/merge @p { x: @nx, y: @ny }))))))))
            (dividerX (* @config.width 0.5))
          )
          (let (
              (aLeft (array/len (array/filter @moved (fn p (and (== (object/get @p element) "A") (< (object/get @p x) @dividerX))))))
              (aRight (array/len (array/filter @moved (fn p (and (== (object/get @p element) "A") (>= (object/get @p x) @dividerX))))))
              (bLeft (array/len (array/filter @moved (fn p (and (== (object/get @p element) "B") (< (object/get @p x) @dividerX))))))
              (bRight (array/len (array/filter @moved (fn p (and (== (object/get @p element) "B") (>= (object/get @p x) @dividerX))))))
            )
            (let (
                (newImbalance (+ (math/abs (- @aLeft @aRight)) (math/abs (- @bLeft @bRight))))
                (mixing (< (+ (math/abs (- @aLeft @aRight)) (math/abs (- @bLeft @bRight))) @entity.imbalance))
              )
              (do
                (set @entity.particles @moved)
                (set @entity.containers [{ x: 0, y: 0, width: @config.width, height: @config.height, divider: "solid", leftLabel: (str/concat "L " (str/concat "" (+ @aLeft @bLeft))), rightLabel: (str/concat "R " (str/concat "" (+ @aRight @bRight))) }])
                (set @entity.readouts [
                  { label: "A left", value: (str/concat "" @aLeft) },
                  { label: "A right", value: (str/concat "" @aRight) },
                  { label: "B left", value: (str/concat "" @bLeft) },
                  { label: "B right", value: (str/concat "" @bRight) }
                ])
                (set @entity.narration (if @mixing
                  (str/concat "mixing — imbalance now " (str/concat "" @newImbalance))
                  (str/concat "random walk continues — imbalance " (str/concat "" @newImbalance))))
                (set @entity.imbalance @newImbalance)))))
        (render-ui main {
          type: box
          padding: md
          children: [
            { type: stack, direction: vertical, gap: md, children: [
                @trait.ChemDiffusionTransport,
                { type: chemistry-canvas, width: @config.width, height: @config.height, backgroundColor: @config.backgroundColor, atoms: @entity.particles, containers: @entity.containers, readouts: @entity.readouts },
                { type: typography, variant: body, content: @entity.narration }
              ] }
          ]
        })
        (emit DIFFUSION_UPDATED { particles: @entity.particles, containers: @entity.containers, readouts: @entity.readouts, narration: @entity.narration })

      LEARN_RESET -> idle when (== @entity.active true)
        (set @entity.done false)
        (set @entity.particles (array/map (array/range @config.particleCount) (fn i
          (let (
              (half (/ @config.particleCount 2))
              (isA (< @i @half))
            )
            (let (
                (idxInSpecies (if @isA @i (- @i @half)))
              )
              (let (
                  (colParity (math/mod @idxInSpecies 2))
                  (rowNum (math/floor (/ @idxInSpecies 2)))
                )
                { id: (str/concat "p" (str/concat "" @i)),
                  x: (if @isA (* @config.width (+ 0.08 (* @colParity 0.06))) (* @config.width (- 0.92 (* @colParity 0.06)))),
                  y: (* @config.height (+ 0.1 (* @rowNum 0.11))),
                  element: (if @isA "A" "B"),
                  radius: @config.particleRadius,
                  color: (if @isA @config.colorA @config.colorB) }))))))
        (let (
            (dividerX (* @config.width 0.5))
          )
          (let (
              (aLeft (array/len (array/filter @entity.particles (fn p (and (== (object/get @p element) "A") (< (object/get @p x) @dividerX))))))
              (aRight (array/len (array/filter @entity.particles (fn p (and (== (object/get @p element) "A") (>= (object/get @p x) @dividerX))))))
              (bLeft (array/len (array/filter @entity.particles (fn p (and (== (object/get @p element) "B") (< (object/get @p x) @dividerX))))))
              (bRight (array/len (array/filter @entity.particles (fn p (and (== (object/get @p element) "B") (>= (object/get @p x) @dividerX))))))
            )
            (do
              (set @entity.imbalance (+ (math/abs (- @aLeft @aRight)) (math/abs (- @bLeft @bRight))))
              (set @entity.containers [{ x: 0, y: 0, width: @config.width, height: @config.height, divider: "solid", leftLabel: (str/concat "L " (str/concat "" (+ @aLeft @bLeft))), rightLabel: (str/concat "R " (str/concat "" (+ @aRight @bRight))) }])
              (set @entity.readouts [
                { label: "A left", value: (str/concat "" @aLeft) },
                { label: "A right", value: (str/concat "" @aRight) },
                { label: "B left", value: (str/concat "" @bLeft) },
                { label: "B right", value: (str/concat "" @bRight) }
              ])
              (set @entity.narration "gases separated — press Step to random-walk them together"))))
        (render-ui main {
          type: box
          padding: md
          children: [
            { type: stack, direction: vertical, gap: md, children: [
                @trait.ChemDiffusionTransport,
                { type: chemistry-canvas, width: @config.width, height: @config.height, backgroundColor: @config.backgroundColor, atoms: @entity.particles, containers: @entity.containers, readouts: @entity.readouts },
                { type: typography, variant: body, content: @entity.narration }
              ] }
          ]
        })
        (emit DIFFUSION_UPDATED { particles: @entity.particles, containers: @entity.containers, readouts: @entity.readouts, narration: @entity.narration })

      LEARN_UPDATED -> idle when (== @entity.active true)
        (render-ui main {
          type: box
          padding: md
          children: [
            { type: stack, direction: vertical, gap: md, children: [
                @trait.ChemDiffusionTransport,
                { type: chemistry-canvas, width: @config.width, height: @config.height, backgroundColor: @config.backgroundColor, atoms: @entity.particles, containers: @entity.containers, readouts: @entity.readouts },
                { type: typography, variant: body, content: @entity.narration }
              ] }
          ]
        })
    }

    listens {
      ChemDiffusionTransport.LEARN_RESET -> LEARN_RESET
      ChemDiffusionTransport.LEARN_STEP -> LEARN_STEP
      ChemDiffusionTransport.LEARN_UPDATED -> LEARN_UPDATED
      MODE_SELECTED {
        mode : string
      }
        @description "Lab router broadcast naming the active mode; this instrument renders when the mode equals matchMode, otherwise renders null."
        @tier "domain"
      LEARN_STEP {
        steps : int
      }
        @description "One step of the transport clock or Step button (from the composed std-learn-transport trait); applies one substepped random-walk diffusion pass."
        @tier "domain"
      LEARN_RESET {
      }
        @description "Transport Reset broadcast (from the composed std-learn-transport trait); reseeds the particles, containers, readouts, and narration from config."
        @tier "domain"
      LEARN_UPDATED {
        running : boolean
        steps : int
      }
        @description "Transport state broadcast on load and Run/Pause toggle (from the composed std-learn-transport trait); repaints the full shell so the strip's Run/Pause label and step caption stay fresh."
        @tier "domain"
    }

    emits {
      DIFFUSION_UPDATED -> external {
        particles : [ChemParticle]
        containers : [ChemContainer]
        readouts : [ChemReadout]
        narration : string
      }
        @description "The particle scene and left/right readouts after each step/toggle/reset — a composed listener (graph, readout, mirror canvas) can subscribe; a harmless no-op when the atom runs standalone."
        @synonyms "diffusion, random walk, entropy, gas mixing, concentration gradient, brownian motion"
        @tier "domain"
    }

    config {
      matchMode : string = ""
        @label "Match Mode"
        @description "When composed behind a lab router, the MODE_SELECTED mode value this instrument responds to. Empty string means standalone — render immediately on INIT."
        @tier "presentation"
      particleCount : number = 16
        @label "Particle Count"
        @description "Total particles — split evenly, the first half seeded as species A on the left, the rest as species B on the right."
        @synonyms "gas A, gas B, particles, molecules"
        @tier "domain"
      jitter : number = 3
        @label "Jitter"
        @description "Maximum random-walk step per substep, in pixels each axis."
        @tier "domain"
      substeps : number = 8
        @label "Substeps"
        @description "Random-walk iterations applied per Step press or per tick; higher values move particles further each press."
        @tier "domain"
      particleRadius : number = 10
        @label "Particle Radius"
        @description "Drawn radius of each particle, in pixels."
        @tier "presentation"
      colorA : string = "#dc2626"
        @label "Species A Color"
        @description "Fill color for species A particles."
        @tier "presentation"
      colorB : string = "#2563eb"
        @label "Species B Color"
        @description "Fill color for species B particles."
        @tier "presentation"
      width : number = 600
        @label "Width"
        @description "Simulation width in pixels; the left/right split is at width * 0.5."
        @tier "presentation"
      height : number = 400
        @label "Height"
        @description "Simulation height in pixels; bounds the random walk."
        @tier "presentation"
      backgroundColor : string = "#f8fafc"
        @label "Background Color"
        @description "Canvas background color."
        @tier "presentation"
    }
  }

  page "/chem-diffusion" as ChemDiffusionEnginePage -> ChemDiffusionTransport, ChemDiffusionSim
}

app std-bio-mitosis "1.0.0"
"Cell-division engine — a config-declared five-phase roster (interphase→prophase→metaphase→anaphase→telophase) the learner steps through on biology-canvas: a timeline strip tracks phase progress, the cell boundary renders as a compartment, chromosome nodes reposition per the phase's declarative scene roster, and a cleavage furrow compartment appears at telophase. The Step/Run-Pause/Reset transport and the step clock come from the std-learn-transport atom (BioMitosisTransport); the phase advance lives in the sibling BioMitosisSim trait, which transitions directly on the transport's LEARN_STEP (advances one phase), LEARN_RESET (reseeds from the first phase), and LEARN_UPDATED (full-shell repaint) broadcasts — delivered by the same bare-event cascade the lab routers use — and owns the full-shell scene render (the transport strip is embedded via @trait.BioMitosisTransport — one render authority per shared entity). Standalone by default; behind a lab router set matchMode and it renders only when MODE_SELECTED matches."
orbital BioMitosisEngineOrbital {
  type BioNode = {
    id : string
    x : number!
    y : number!
    radius : number
    color : string
    label : string
    kind : "cell" | "organelle" | "molecule" | "organism"
  }

  type BioCompartment = {
    x : number!
    y : number!
    width : number!
    height : number!
    label : string
    color : string
    dash : "dashed" | "dotted"
  }

  type MitosisPhase = {
    label : string
    caption : string
  }

  type MitosisPhaseScene = {
    nodes : [BioNode]
    compartments : [BioCompartment]
  }

  type BioStage = {
    label : string
    state : "pending" | "active" | "done"
  }

  entity BioMitosisState [runtime, shared] {
    id : string!
    active : boolean = false
    title : string
    running : boolean = false
    steps : int = 0
    elapsedMs : number = 0
    done : boolean = false
    phaseIndex : number = 0
    stages : [BioStage]
    nodes : [BioNode]
    compartments : [BioCompartment]
    narration : string
  }

  uses LearnTransport from "std/behaviors/std-learn-transport"

  trait BioMitosisTransport = LearnTransport.traits.LearnTransportSim -> BioMitosisState {
    config {
      title: "Mitosis"
      stepIntervalMs: 550
    }
  }

  trait BioMitosisSim -> @rebindable BioMitosisState [interaction, instance] {
    initial: idle

    state idle {
      INIT -> idle when (== @config.matchMode "")
        (let (
            (scene (array/nth @config.phaseScenes 0))
            (phaseDef (array/nth @config.phases 0))
          )
          (do
            (set @entity.phaseIndex 0)
            (set @entity.done false)
            (set @entity.nodes (object/get @scene nodes))
            (set @entity.compartments (object/get @scene compartments))
            (set @entity.stages (array/map @config.phases (fn p { label: (object/get @p label), state: (if (== @index 0) "active" "pending") })))
            (set @entity.narration (str/concat (object/get @phaseDef label) " — " (object/get @phaseDef caption)))
          ))
        (render-ui main {
          type: box
          padding: md
          children: [
            { type: stack, direction: vertical, gap: md, children: [
                @trait.BioMitosisTransport,
                { type: biology-canvas, width: @config.width, height: @config.height, backgroundColor: @config.backgroundColor,
                  nodes: @entity.nodes, compartments: @entity.compartments, stages: @entity.stages },
                { type: typography, variant: body, content: @entity.narration }
              ] }
          ]
        })
        (emit MITOSIS_UPDATED { phaseIndex: @entity.phaseIndex, stages: @entity.stages, nodes: @entity.nodes, compartments: @entity.compartments, narration: @entity.narration, done: @entity.done })

      MODE_SELECTED -> idle when (== ?mode @config.matchMode)
        (let (
            (scene (array/nth @config.phaseScenes 0))
            (phaseDef (array/nth @config.phases 0))
          )
          (do
            (set @entity.phaseIndex 0)
            (set @entity.done false)
            (set @entity.nodes (object/get @scene nodes))
            (set @entity.compartments (object/get @scene compartments))
            (set @entity.stages (array/map @config.phases (fn p { label: (object/get @p label), state: (if (== @index 0) "active" "pending") })))
            (set @entity.narration (str/concat (object/get @phaseDef label) " — " (object/get @phaseDef caption)))
          ))
        (render-ui main {
          type: box
          padding: md
          children: [
            { type: stack, direction: vertical, gap: md, children: [
                @trait.BioMitosisTransport,
                { type: biology-canvas, width: @config.width, height: @config.height, backgroundColor: @config.backgroundColor,
                  nodes: @entity.nodes, compartments: @entity.compartments, stages: @entity.stages },
                { type: typography, variant: body, content: @entity.narration }
              ] }
          ]
        })
        (emit MITOSIS_UPDATED { phaseIndex: @entity.phaseIndex, stages: @entity.stages, nodes: @entity.nodes, compartments: @entity.compartments, narration: @entity.narration, done: @entity.done })

      LEARN_STEP -> idle when (and @entity.active (not @entity.done))
        (let (
            (lastIndex (- (array/len @config.phases) 1))
            (newIndex (math/min (- (array/len @config.phases) 1) (+ @entity.phaseIndex 1)))
          )
          (let (
            (scene (array/nth @config.phaseScenes @newIndex))
            (phaseDef (array/nth @config.phases @newIndex))
          )
          (do
            (set @entity.phaseIndex @newIndex)
            (set @entity.done (== @newIndex @lastIndex))
            (set @entity.nodes (object/get @scene nodes))
            (set @entity.compartments (object/get @scene compartments))
            (set @entity.stages (array/map @config.phases (fn p { label: (object/get @p label), state: (if (< @index @newIndex) "done" (if (== @index @newIndex) "active" "pending")) })))
            (set @entity.narration (str/concat (object/get @phaseDef label) " — " (object/get @phaseDef caption)))
          )))
        (render-ui main {
          type: box
          padding: md
          children: [
            { type: stack, direction: vertical, gap: md, children: [
                @trait.BioMitosisTransport,
                { type: biology-canvas, width: @config.width, height: @config.height, backgroundColor: @config.backgroundColor,
                  nodes: @entity.nodes, compartments: @entity.compartments, stages: @entity.stages },
                { type: typography, variant: body, content: @entity.narration }
              ] }
          ]
        })
        (emit MITOSIS_UPDATED { phaseIndex: @entity.phaseIndex, stages: @entity.stages, nodes: @entity.nodes, compartments: @entity.compartments, narration: @entity.narration, done: @entity.done })

      LEARN_RESET -> idle when (== @entity.active true)
        (let (
            (scene (array/nth @config.phaseScenes 0))
            (phaseDef (array/nth @config.phases 0))
          )
          (do
            (set @entity.phaseIndex 0)
            (set @entity.done false)
            (set @entity.nodes (object/get @scene nodes))
            (set @entity.compartments (object/get @scene compartments))
            (set @entity.stages (array/map @config.phases (fn p { label: (object/get @p label), state: (if (== @index 0) "active" "pending") })))
            (set @entity.narration (str/concat (object/get @phaseDef label) " — " (object/get @phaseDef caption)))
          ))
        (render-ui main {
          type: box
          padding: md
          children: [
            { type: stack, direction: vertical, gap: md, children: [
                @trait.BioMitosisTransport,
                { type: biology-canvas, width: @config.width, height: @config.height, backgroundColor: @config.backgroundColor,
                  nodes: @entity.nodes, compartments: @entity.compartments, stages: @entity.stages },
                { type: typography, variant: body, content: @entity.narration }
              ] }
          ]
        })
        (emit MITOSIS_UPDATED { phaseIndex: @entity.phaseIndex, stages: @entity.stages, nodes: @entity.nodes, compartments: @entity.compartments, narration: @entity.narration, done: @entity.done })

      LEARN_UPDATED -> idle when (== @entity.active true)
        (render-ui main {
          type: box
          padding: md
          children: [
            { type: stack, direction: vertical, gap: md, children: [
                @trait.BioMitosisTransport,
                { type: biology-canvas, width: @config.width, height: @config.height, backgroundColor: @config.backgroundColor,
                  nodes: @entity.nodes, compartments: @entity.compartments, stages: @entity.stages },
                { type: typography, variant: body, content: @entity.narration }
              ] }
          ]
        })
    }

    listens {
      BioMitosisTransport.LEARN_RESET -> LEARN_RESET
      BioMitosisTransport.LEARN_STEP -> LEARN_STEP
      BioMitosisTransport.LEARN_UPDATED -> LEARN_UPDATED
      MODE_SELECTED {
        mode : string
      }
        @description "Lab router broadcast naming the active mode; this instrument renders when the mode equals matchMode, otherwise renders null."
        @tier "domain"
      LEARN_STEP {
        steps : int
      }
        @description "One step of the transport clock or Step button (from the composed std-learn-transport trait); advances the phase roster by one and recomputes the timeline, chromosome scene, and narration."
        @tier "domain"
      LEARN_RESET {
      }
        @description "Transport Reset broadcast (from the composed std-learn-transport trait); reseeds the phase index, timeline, chromosome scene, and narration from the first phase in config."
        @tier "domain"
      LEARN_UPDATED {
        running : boolean
        steps : int
      }
        @description "Transport state broadcast on load and Run/Pause toggle (from the composed std-learn-transport trait); repaints the full shell so the strip's Run/Pause label and step caption stay fresh."
        @tier "domain"
    }

    emits {
      MITOSIS_UPDATED -> external {
        phaseIndex : number
        stages : [BioStage]
        nodes : [BioNode]
        compartments : [BioCompartment]
        narration : string
        done : boolean
      }
        @description "The current phase and scene after each step/reset — a composed listener (readout, quiz) can subscribe; a harmless no-op when the atom runs standalone."
        @synonyms "mitosis, cell division, cytokinesis, cleavage furrow, phases"
        @tier "domain"
    }

    config {
      matchMode : string = ""
        @label "Match Mode"
        @description "When composed behind a lab router, the MODE_SELECTED mode value this instrument responds to. Empty string means standalone — render immediately on INIT."
        @tier "presentation"
      phases : [MitosisPhase] = [
        { label: "Interphase", caption: "Chromatin is diffuse inside the nucleus while the cell grows and duplicates its DNA." },
        { label: "Prophase", caption: "Chromatin condenses into visible chromosomes as the nuclear envelope begins to break down." },
        { label: "Metaphase", caption: "Chromosomes align along the cell's equator, attached to spindle fibers at the metaphase plate." },
        { label: "Anaphase", caption: "Sister chromatids separate and are pulled toward opposite poles of the cell." },
        { label: "Telophase", caption: "Two nuclear envelopes reform around the separated chromosomes as a cleavage furrow pinches the cell in two." }
      ]
        @label "Phases"
        @description "The five-phase roster the tour steps through; each phase's label and caption drive the timeline chip and narration."
        @synonyms "mitosis phases, cell cycle stages, interphase prophase metaphase anaphase telophase"
        @tier "domain"
      phaseScenes : [MitosisPhaseScene] = [
        { nodes: [
            { id: "c1", x: 270, y: 180, radius: 6, color: "#7c3aed", label: "", kind: organelle },
            { id: "c2", x: 330, y: 180, radius: 6, color: "#7c3aed", label: "", kind: organelle },
            { id: "c3", x: 270, y: 220, radius: 6, color: "#7c3aed", label: "", kind: organelle },
            { id: "c4", x: 330, y: 220, radius: 6, color: "#7c3aed", label: "", kind: organelle }
          ], compartments: [
            { x: 300, y: 200, width: 340, height: 280, label: "cell", color: "#475569" },
            { x: 300, y: 200, width: 140, height: 120, label: "nucleus", color: "#2563eb", dash: dashed }
