app std-bio-population "2.0.0"
"Predator-prey population engine — real coupled Lotka-Volterra dynamics: each Step integrates one dt of prey growth-vs-predation and predator growth-vs-death, redrawing two organism nodes (radius proportional to population) linked by a directed \"eats\" edge on biology-canvas, with a two-series traces panel tracking prey/predator history. The Step/Run-Pause/Reset transport and the step clock come from the std-learn-transport atom (BioPopulationTransport); the Lotka-Volterra integration lives in the sibling BioPopulationSim trait, which transitions directly on the transport's LEARN_STEP (integrates one dt of the coupled predator-prey dynamics), LEARN_RESET (reseeds populations, history, scene nodes, and narration from config), and LEARN_UPDATED (full-shell repaint) broadcasts — delivered by the same bare-event cascade the lab routers use — and owns the full-shell scene render (the transport strip is embedded via @trait.BioPopulationTransport — one render authority per shared entity). The predator-prey dynamics never terminate — done stays false always, there is no rest/completion condition to detect. Standalone by default; behind a lab router set matchMode and it renders only when MODE_SELECTED matches."
orbital BioPopulationEngineOrbital {
  type BioNode = {
    id : string
    x : number!
    y : number!
    radius : number
    color : string
    label : string
    kind : "cell" | "organelle" | "molecule" | "organism"
  }

  type BioEdge = {
    from : string!
    to : string!
    directed : boolean
    color : string
    label : string
  }

  type BioReadout = {
    label : string
    value : string
    color : string
  }

  type BioPoint = {
    x : number!
    y : number!
  }

  type BioTraceSeries = {
    samples : [BioPoint]
    color : string
    label : string
  }

  type BioTracePanel = {
    series : [BioTraceSeries]
    xLabel : string
    yLabel : string
  }

  entity BioPopulationState [runtime, shared] {
    id : string!
    active : boolean = false
    title : string
    running : boolean = false
    steps : int = 0
    elapsedMs : number = 0
    done : boolean = false
    prey : number = 40
    pred : number = 9
    stepIndex : number = 0
    preyHistory : [BioPoint]
    predHistory : [BioPoint]
    nodes : [BioNode]
    edges : [BioEdge]
    readouts : [BioReadout]
    narration : string
  }

  uses LearnTransport from "std/behaviors/std-learn-transport"

  trait BioPopulationTransport = LearnTransport.traits.LearnTransportSim -> BioPopulationState {
    config {
      title: "Predator-Prey Population"
      stepIntervalMs: 550
    }
  }

  trait BioPopulationSim -> @rebindable BioPopulationState [interaction, instance] {
    initial: idle

    state idle {
      INIT -> idle when (== @config.matchMode "")
        (set @entity.done false)
        (let (
            (preyX (* @config.width 0.3))
            (predX (* @config.width 0.7))
            (cy (* @config.height 0.5))
            (preyR (+ 10 (math/min 28 (* 0.3 @config.initialPrey))))
            (predR (+ 10 (math/min 28 (* 0.3 @config.initialPred))))
          )
          (do
            (set @entity.prey @config.initialPrey)
            (set @entity.pred @config.initialPred)
            (set @entity.stepIndex 0)
            (set @entity.preyHistory [ { x: 0, y: @config.initialPrey } ])
            (set @entity.predHistory [ { x: 0, y: @config.initialPred } ])
            (set @entity.nodes [
              { id: "prey", x: @preyX, y: @cy, radius: @preyR, color: "#16a34a", label: "Prey", kind: organism },
              { id: "predator", x: @predX, y: @cy, radius: @predR, color: "#dc2626", label: "Predator", kind: organism }
            ])
            (set @entity.edges [ { from: "predator", to: "prey", directed: true, color: "#94a3b8", label: "eats" } ])
            (set @entity.readouts [
              { label: "prey", value: (str/concat "" (math/round @config.initialPrey 1)) },
              { label: "pred", value: (str/concat "" (math/round @config.initialPred 1)) }
            ])
            (set @entity.narration (str/concat "prey " (str/concat "" (math/round @config.initialPrey 1)) " — pred " (str/concat "" (math/round @config.initialPred 1)) " — press Step to advance"))
          ))
        (render-ui main {
          type: box
          padding: md
          children: [
            { type: stack, direction: vertical, gap: md, children: [
                @trait.BioPopulationTransport,
                { type: biology-canvas, width: @config.width, height: @config.height, backgroundColor: @config.backgroundColor,
                  nodes: @entity.nodes, edges: @entity.edges, readouts: @entity.readouts,
                  traces: [ { series: [ { samples: @entity.preyHistory, color: "#2563eb", label: "prey" }, { samples: @entity.predHistory, color: "#dc2626", label: "pred" } ], xLabel: "step", yLabel: "population" } ] },
                { type: typography, variant: body, content: @entity.narration }
              ] }
          ]
        })
        (emit POPULATION_UPDATED { prey: @entity.prey, pred: @entity.pred, nodes: @entity.nodes, edges: @entity.edges, narration: @entity.narration })

      MODE_SELECTED -> idle when (== ?mode @config.matchMode)
        (set @entity.done false)
        (let (
            (preyX (* @config.width 0.3))
            (predX (* @config.width 0.7))
            (cy (* @config.height 0.5))
            (preyR (+ 10 (math/min 28 (* 0.3 @config.initialPrey))))
            (predR (+ 10 (math/min 28 (* 0.3 @config.initialPred))))
          )
          (do
            (set @entity.prey @config.initialPrey)
            (set @entity.pred @config.initialPred)
            (set @entity.stepIndex 0)
            (set @entity.preyHistory [ { x: 0, y: @config.initialPrey } ])
            (set @entity.predHistory [ { x: 0, y: @config.initialPred } ])
            (set @entity.nodes [
              { id: "prey", x: @preyX, y: @cy, radius: @preyR, color: "#16a34a", label: "Prey", kind: organism },
              { id: "predator", x: @predX, y: @cy, radius: @predR, color: "#dc2626", label: "Predator", kind: organism }
            ])
            (set @entity.edges [ { from: "predator", to: "prey", directed: true, color: "#94a3b8", label: "eats" } ])
            (set @entity.readouts [
              { label: "prey", value: (str/concat "" (math/round @config.initialPrey 1)) },
              { label: "pred", value: (str/concat "" (math/round @config.initialPred 1)) }
            ])
            (set @entity.narration (str/concat "prey " (str/concat "" (math/round @config.initialPrey 1)) " — pred " (str/concat "" (math/round @config.initialPred 1)) " — press Step to advance"))
          ))
        (render-ui main {
          type: box
          padding: md
          children: [
            { type: stack, direction: vertical, gap: md, children: [
                @trait.BioPopulationTransport,
                { type: biology-canvas, width: @config.width, height: @config.height, backgroundColor: @config.backgroundColor,
                  nodes: @entity.nodes, edges: @entity.edges, readouts: @entity.readouts,
                  traces: [ { series: [ { samples: @entity.preyHistory, color: "#2563eb", label: "prey" }, { samples: @entity.predHistory, color: "#dc2626", label: "pred" } ], xLabel: "step", yLabel: "population" } ] },
                { type: typography, variant: body, content: @entity.narration }
              ] }
          ]
        })
        (emit POPULATION_UPDATED { prey: @entity.prey, pred: @entity.pred, nodes: @entity.nodes, edges: @entity.edges, narration: @entity.narration })

      LEARN_STEP -> idle when (and (== @entity.active true) (not (== @entity.done true)))
        (let (
            (newPrey (math/max 0.5 (+ @entity.prey (* (- (* @config.alpha @entity.prey) (* (* @config.beta @entity.prey) @entity.pred)) @config.dt))))
            (newPred (math/max 0.5 (+ @entity.pred (* (- (* (* @config.gamma @entity.prey) @entity.pred) (* @config.delta @entity.pred)) @config.dt))))
            (newStepIndex (+ @entity.stepIndex 1))
            (preyX (* @config.width 0.3))
            (predX (* @config.width 0.7))
            (cy (* @config.height 0.5))
          )
          (let (
            (preyR (+ 10 (math/min 28 (* 0.3 @newPrey))))
            (predR (+ 10 (math/min 28 (* 0.3 @newPred))))
            (appendedPreyHistory (array/append @entity.preyHistory { x: @newStepIndex, y: @newPrey }))
            (appendedPredHistory (array/append @entity.predHistory { x: @newStepIndex, y: @newPred }))
          )
          (let (
            (preyHistCount (array/len @appendedPreyHistory))
            (predHistCount (array/len @appendedPredHistory))
          )
          (do
            (set @entity.prey @newPrey)
            (set @entity.pred @newPred)
            (set @entity.stepIndex @newStepIndex)
            (set @entity.preyHistory (if (> @preyHistCount @config.historyLength) (array/drop @appendedPreyHistory (- @preyHistCount @config.historyLength)) @appendedPreyHistory))
            (set @entity.predHistory (if (> @predHistCount @config.historyLength) (array/drop @appendedPredHistory (- @predHistCount @config.historyLength)) @appendedPredHistory))
            (set @entity.nodes [
              { id: "prey", x: @preyX, y: @cy, radius: @preyR, color: "#16a34a", label: "Prey", kind: organism },
              { id: "predator", x: @predX, y: @cy, radius: @predR, color: "#dc2626", label: "Predator", kind: organism }
            ])
            (set @entity.readouts [
              { label: "prey", value: (str/concat "" (math/round @newPrey 1)) },
              { label: "pred", value: (str/concat "" (math/round @newPred 1)) }
            ])
            (set @entity.narration (str/concat "prey " (str/concat "" (math/round @newPrey 1)) (if (> @newPrey @entity.prey) " rising" " falling") " — pred " (str/concat "" (math/round @newPred 1)) (if (> @newPred @entity.pred) " rising" " falling")))
          ))))
        (render-ui main {
          type: box
          padding: md
          children: [
            { type: stack, direction: vertical, gap: md, children: [
                @trait.BioPopulationTransport,
                { type: biology-canvas, width: @config.width, height: @config.height, backgroundColor: @config.backgroundColor,
                  nodes: @entity.nodes, edges: @entity.edges, readouts: @entity.readouts,
                  traces: [ { series: [ { samples: @entity.preyHistory, color: "#2563eb", label: "prey" }, { samples: @entity.predHistory, color: "#dc2626", label: "pred" } ], xLabel: "step", yLabel: "population" } ] },
                { type: typography, variant: body, content: @entity.narration }
              ] }
          ]
        })
        (emit POPULATION_UPDATED { prey: @entity.prey, pred: @entity.pred, nodes: @entity.nodes, edges: @entity.edges, narration: @entity.narration })

      LEARN_RESET -> idle when (== @entity.active true)
        (set @entity.done false)
        (let (
            (preyX (* @config.width 0.3))
            (predX (* @config.width 0.7))
            (cy (* @config.height 0.5))
            (preyR (+ 10 (math/min 28 (* 0.3 @config.initialPrey))))
            (predR (+ 10 (math/min 28 (* 0.3 @config.initialPred))))
          )
          (do
            (set @entity.prey @config.initialPrey)
            (set @entity.pred @config.initialPred)
            (set @entity.stepIndex 0)
            (set @entity.preyHistory [ { x: 0, y: @config.initialPrey } ])
            (set @entity.predHistory [ { x: 0, y: @config.initialPred } ])
            (set @entity.nodes [
              { id: "prey", x: @preyX, y: @cy, radius: @preyR, color: "#16a34a", label: "Prey", kind: organism },
              { id: "predator", x: @predX, y: @cy, radius: @predR, color: "#dc2626", label: "Predator", kind: organism }
            ])
            (set @entity.edges [ { from: "predator", to: "prey", directed: true, color: "#94a3b8", label: "eats" } ])
            (set @entity.readouts [
              { label: "prey", value: (str/concat "" (math/round @config.initialPrey 1)) },
              { label: "pred", value: (str/concat "" (math/round @config.initialPred 1)) }
            ])
            (set @entity.narration (str/concat "prey " (str/concat "" (math/round @config.initialPrey 1)) " — pred " (str/concat "" (math/round @config.initialPred 1)) " — press Step to advance"))
          ))
        (render-ui main {
          type: box
          padding: md
          children: [
            { type: stack, direction: vertical, gap: md, children: [
                @trait.BioPopulationTransport,
                { type: biology-canvas, width: @config.width, height: @config.height, backgroundColor: @config.backgroundColor,
                  nodes: @entity.nodes, edges: @entity.edges, readouts: @entity.readouts,
                  traces: [ { series: [ { samples: @entity.preyHistory, color: "#2563eb", label: "prey" }, { samples: @entity.predHistory, color: "#dc2626", label: "pred" } ], xLabel: "step", yLabel: "population" } ] },
                { type: typography, variant: body, content: @entity.narration }
              ] }
          ]
        })
        (emit POPULATION_UPDATED { prey: @entity.prey, pred: @entity.pred, nodes: @entity.nodes, edges: @entity.edges, narration: @entity.narration })

      LEARN_UPDATED -> idle when (== @entity.active true)
        (render-ui main {
          type: box
          padding: md
          children: [
            { type: stack, direction: vertical, gap: md, children: [
                @trait.BioPopulationTransport,
                { type: biology-canvas, width: @config.width, height: @config.height, backgroundColor: @config.backgroundColor,
                  nodes: @entity.nodes, edges: @entity.edges, readouts: @entity.readouts,
                  traces: [ { series: [ { samples: @entity.preyHistory, color: "#2563eb", label: "prey" }, { samples: @entity.predHistory, color: "#dc2626", label: "pred" } ], xLabel: "step", yLabel: "population" } ] },
                { type: typography, variant: body, content: @entity.narration }
              ] }
          ]
        })
    }

    listens {
      BioPopulationTransport.LEARN_RESET -> LEARN_RESET
      BioPopulationTransport.LEARN_STEP -> LEARN_STEP
      BioPopulationTransport.LEARN_UPDATED -> LEARN_UPDATED
      MODE_SELECTED {
        mode : string
      }
        @description "Lab router broadcast naming the active mode; this instrument renders when the mode equals matchMode, otherwise renders null."
        @tier "domain"
      LEARN_STEP {
        steps : int
      }
        @description "One step of the transport clock or Step button (from the composed std-learn-transport trait); integrates one dt of the coupled predator-prey dynamics."
        @tier "domain"
      LEARN_RESET {
      }
        @description "Transport Reset broadcast (from the composed std-learn-transport trait); reseeds the prey/predator populations, history, scene nodes, and narration from config."
        @tier "domain"
      LEARN_UPDATED {
        running : boolean
        steps : int
      }
        @description "Transport state broadcast on load and Run/Pause toggle (from the composed std-learn-transport trait); repaints the full shell so the strip's Run/Pause label and step caption stay fresh."
        @tier "domain"
    }

    emits {
      POPULATION_UPDATED -> external {
        prey : number
        pred : number
        nodes : [BioNode]
        edges : [BioEdge]
        narration : string
      }
        @description "The prey/predator populations and scene after each step/toggle/reset — a composed listener (readout, grader) can subscribe; a harmless no-op when the atom runs standalone."
        @synonyms "predator prey, lotka volterra, population cycle, ecology"
        @tier "domain"
    }

    config {
      matchMode : string = ""
        @label "Match Mode"
        @description "When composed behind a lab router, the MODE_SELECTED mode value this instrument responds to. Empty string means standalone — render immediately on INIT."
        @tier "presentation"
      alpha : number = 0.6
        @label "Prey Growth Rate"
        @description "Exponential growth rate of the prey population absent predation."
        @synonyms "alpha, prey birth rate, growth rate"
        @tier "domain"
      beta : number = 0.025
        @label "Predation Rate"
        @description "Rate at which predators reduce the prey population per encounter."
        @synonyms "beta, predation rate, encounter rate"
        @tier "domain"
      gamma : number = 0.012
        @label "Predator Efficiency"
        @description "Rate at which consumed prey convert into predator population growth."
        @synonyms "gamma, predator efficiency, conversion rate"
        @tier "domain"
      delta : number = 0.5
        @label "Predator Death Rate"
        @description "Exponential death rate of the predator population absent prey."
        @synonyms "delta, predator death rate, mortality"
        @tier "domain"
      dt : number = 0.1
        @label "Time Step"
        @description "Size of one Step's time increment in the coupled differential equations."
        @synonyms "dt, time step, integration step"
        @tier "domain"
      historyLength : number = 80
        @label "History Length"
        @description "Maximum number of points retained per series in the traces panel before the oldest is dropped."
        @synonyms "history length, trace length, window size"
        @tier "domain"
      initialPrey : number = 40
        @label "Initial Prey"
        @description "Starting prey population seeded on INIT/MODE_SELECTED/Reset."
        @synonyms "initial prey, starting prey population"
        @tier "domain"
      initialPred : number = 9
        @label "Initial Predators"
        @description "Starting predator population seeded on INIT/MODE_SELECTED/Reset."
        @synonyms "initial predators, starting predator population"
        @tier "domain"
      width : number = 600
        @label "Width"
        @description "Canvas width in pixels."
        @tier "presentation"
      height : number = 400
        @label "Height"
        @description "Canvas height in pixels."
        @tier "presentation"
      backgroundColor : string = "#f0fdf4"
        @label "Background Color"
        @description "Canvas background color."
        @tier "presentation"
    }
  }

  page "/bio-population" as BioPopulationEnginePage -> BioPopulationTransport, BioPopulationSim
}

app std-astro-stellar "2.0.0"
"Stellar life-cycle simulator — the learner picks a starting mass via slider or preset buttons and steps through the star's evolutionary stages from nebula to its predicted end state (white dwarf, neutron star, or black hole), on a math-canvas with a poor-man's stage-progress timeline. The Step/Run-Pause/Reset transport and the step clock come from the std-learn-transport atom (AstroStellarTransport); the stage-advance lives in the sibling AstroStellarSim trait, which transitions directly on the transport's LEARN_STEP (advances the star to its next life-cycle stage — the same computation the tick used to run, and the same as the old Next Stage button), LEARN_RESET (returns the star to its first life-cycle stage), and LEARN_UPDATED (full-shell repaint) broadcasts — delivered by the same bare-event cascade the lab routers use — and owns the full-shell scene render (the transport strip is embedded via @trait.AstroStellarTransport — one render authority per shared entity). The life-cycle path terminates: done flips true once the star reaches its path's final stage (white dwarf / neutron star / black hole), halting the transport's clock and blocking further LEARN_STEP transitions until Reset. Standalone by default; behind a lab router set matchMode and it renders only when MODE_SELECTED matches."
orbital AstroStellarOrbital {
  type AstroStellarStage = {
    label : string!
    description : string
    color : string
    radius : number
  }
  type AstroStellarPath = {
    maxMass : number!
    endLabel : string
    stages : [AstroStellarStage]!
  }
  type AstroStellarBar = {
    x : number!
    width : number
    y0 : number
    y1 : number
    color : string
  }

  entity AstroStellarScene [runtime, shared] {
    id : string!
    active : boolean = false
    title : string
    running : boolean = false
    steps : int = 0
    elapsedMs : number = 0
    done : boolean = false
    initialMass : number
    pathEndLabel : string
    stages : [AstroStellarStage]
    currentStageIndex : number
    stageLabel : string
    stageDescription : string
    starRadius : number
    starColor : string
    stageBars : [AstroStellarBar]
    narration : string
  }

  uses LearnTransport from "std/behaviors/std-learn-transport"

  trait AstroStellarTransport = LearnTransport.traits.LearnTransportSim -> AstroStellarScene {
    config {
      title: "Star Life-Cycle Simulator"
      stepIntervalMs: 800
    }
  }

  trait AstroStellarSim -> @rebindable AstroStellarScene [interaction, instance] {
    initial: idle

    state idle {
      INIT -> idle when (== @config.matchMode "")
        (set @entity.done false)
        (let (
          (mass @config.initialMass)
          (matched (array/first (array/filter @config.stellarPaths (fn p (<= @mass (object/get @p maxMass))))))
          (selectedPath (if (== @matched null) (array/last @config.stellarPaths) @matched))
          (stages (object/get @selectedPath stages))
          (stage0 (array/nth @stages 0))
          (bars (array/map (array/range (array/len @stages)) (fn idx { x: @idx, width: 0.8, y0: -1, y1: 0, color: (if (== @idx 0) @config.stageActiveColor @config.stagePendingColor) })))
        )
        (do
          (set @entity.initialMass @mass)
          (set @entity.pathEndLabel (object/get @selectedPath endLabel))
          (set @entity.stages @stages)
          (set @entity.currentStageIndex 0)
          (set @entity.stageLabel (object/get @stage0 label))
          (set @entity.stageDescription (object/get @stage0 description))
          (set @entity.starRadius (object/get @stage0 radius))
          (set @entity.starColor (object/get @stage0 color))
          (set @entity.stageBars @bars)
          (set @entity.narration (str/concat @entity.stageLabel " — " @entity.stageDescription))
        ))
        (render-ui main {
          type: box
          padding: md
          children: [
            { type: stack, direction: vertical, gap: md, children: [
                @trait.AstroStellarTransport,
                { type: stack, direction: horizontal, gap: xs, children: (array/map @config.massPresets (fn m { type: button, action: SET_MASS, actionPayload: { value: @m }, label: (str/concat @m " M☉"), variant: (if (== @entity.initialMass @m) "primary" "ghost"), size: sm })) },
                { type: range-slider, min: 0.1, max: 25, step: 0.1, value: @entity.initialMass, showTooltip: true, onChange: SET_MASS },
                { type: math-canvas, width: @config.width, height: @config.height, xMin: -1, xMax: 6, yMin: -1, yMax: 3,
                  showAxes: false, showGrid: false, showTickLabels: false,
                  points: [ { x: 2.5, y: 2, label: @entity.stageLabel, color: @entity.starColor, radius: @entity.starRadius } ],
                  bars: @entity.stageBars,
                  readouts: [ { label: "Stage", value: @entity.stageLabel }, { label: "Mass", value: (str/concat @entity.initialMass " M☉") }, { label: "End state", value: @entity.pathEndLabel } ],
                  interactive: @config.interactive, animate: false },
                { type: typography, variant: body, content: @entity.narration }
              ] }
          ]
        })
        (emit STELLAR_UPDATED { initialMass: @entity.initialMass, currentStageIndex: @entity.currentStageIndex, stageLabel: @entity.stageLabel, pathEndLabel: @entity.pathEndLabel, narration: @entity.narration })

      MODE_SELECTED -> idle when (== ?mode @config.matchMode)
        (set @entity.done false)
        (let (
          (mass @config.initialMass)
          (matched (array/first (array/filter @config.stellarPaths (fn p (<= @mass (object/get @p maxMass))))))
          (selectedPath (if (== @matched null) (array/last @config.stellarPaths) @matched))
          (stages (object/get @selectedPath stages))
          (stage0 (array/nth @stages 0))
          (bars (array/map (array/range (array/len @stages)) (fn idx { x: @idx, width: 0.8, y0: -1, y1: 0, color: (if (== @idx 0) @config.stageActiveColor @config.stagePendingColor) })))
        )
        (do
          (set @entity.initialMass @mass)
          (set @entity.pathEndLabel (object/get @selectedPath endLabel))
