          (set @entity.done @isDone)
          (set @entity.narration (str/concat @entity.stageLabel " — " @entity.stageDescription))
        ))
        (render-ui main {
          type: box
          padding: md
          children: [
            { type: stack, direction: vertical, gap: md, children: [
                @trait.AstroStellarTransport,
                { type: stack, direction: horizontal, gap: xs, children: (array/map @config.massPresets (fn m { type: button, action: SET_MASS, actionPayload: { value: @m }, label: (str/concat @m " M☉"), variant: (if (== @entity.initialMass @m) "primary" "ghost"), size: sm })) },
                { type: range-slider, min: 0.1, max: 25, step: 0.1, value: @entity.initialMass, showTooltip: true, onChange: SET_MASS },
                { type: math-canvas, width: @config.width, height: @config.height, xMin: -1, xMax: 6, yMin: -1, yMax: 3,
                  showAxes: false, showGrid: false, showTickLabels: false,
                  points: [ { x: 2.5, y: 2, label: @entity.stageLabel, color: @entity.starColor, radius: @entity.starRadius } ],
                  bars: @entity.stageBars,
                  readouts: [ { label: "Stage", value: @entity.stageLabel }, { label: "Mass", value: (str/concat @entity.initialMass " M☉") }, { label: "End state", value: @entity.pathEndLabel } ],
                  interactive: @config.interactive, animate: false },
                { type: typography, variant: body, content: @entity.narration }
              ] }
          ]
        })
        (emit STELLAR_UPDATED { initialMass: @entity.initialMass, currentStageIndex: @entity.currentStageIndex, stageLabel: @entity.stageLabel, pathEndLabel: @entity.pathEndLabel, narration: @entity.narration })

      LEARN_RESET -> idle when (== @entity.active true)
        (set @entity.done false)
        (let (
          (stage0 (array/nth @entity.stages 0))
          (bars (array/map (array/range (array/len @entity.stages)) (fn idx { x: @idx, width: 0.8, y0: -1, y1: 0, color: (if (== @idx 0) @config.stageActiveColor @config.stagePendingColor) })))
        )
        (do
          (set @entity.currentStageIndex 0)
          (set @entity.stageLabel (object/get @stage0 label))
          (set @entity.stageDescription (object/get @stage0 description))
          (set @entity.starRadius (object/get @stage0 radius))
          (set @entity.starColor (object/get @stage0 color))
          (set @entity.stageBars @bars)
          (set @entity.narration (str/concat @entity.stageLabel " — " @entity.stageDescription))
        ))
        (render-ui main {
          type: box
          padding: md
          children: [
            { type: stack, direction: vertical, gap: md, children: [
                @trait.AstroStellarTransport,
                { type: stack, direction: horizontal, gap: xs, children: (array/map @config.massPresets (fn m { type: button, action: SET_MASS, actionPayload: { value: @m }, label: (str/concat @m " M☉"), variant: (if (== @entity.initialMass @m) "primary" "ghost"), size: sm })) },
                { type: range-slider, min: 0.1, max: 25, step: 0.1, value: @entity.initialMass, showTooltip: true, onChange: SET_MASS },
                { type: math-canvas, width: @config.width, height: @config.height, xMin: -1, xMax: 6, yMin: -1, yMax: 3,
                  showAxes: false, showGrid: false, showTickLabels: false,
                  points: [ { x: 2.5, y: 2, label: @entity.stageLabel, color: @entity.starColor, radius: @entity.starRadius } ],
                  bars: @entity.stageBars,
                  readouts: [ { label: "Stage", value: @entity.stageLabel }, { label: "Mass", value: (str/concat @entity.initialMass " M☉") }, { label: "End state", value: @entity.pathEndLabel } ],
                  interactive: @config.interactive, animate: false },
                { type: typography, variant: body, content: @entity.narration }
              ] }
          ]
        })
        (emit STELLAR_UPDATED { initialMass: @entity.initialMass, currentStageIndex: @entity.currentStageIndex, stageLabel: @entity.stageLabel, pathEndLabel: @entity.pathEndLabel, narration: @entity.narration })

      LEARN_UPDATED -> idle when (== @entity.active true)
        (render-ui main {
          type: box
          padding: md
          children: [
            { type: stack, direction: vertical, gap: md, children: [
                @trait.AstroStellarTransport,
                { type: stack, direction: horizontal, gap: xs, children: (array/map @config.massPresets (fn m { type: button, action: SET_MASS, actionPayload: { value: @m }, label: (str/concat @m " M☉"), variant: (if (== @entity.initialMass @m) "primary" "ghost"), size: sm })) },
                { type: range-slider, min: 0.1, max: 25, step: 0.1, value: @entity.initialMass, showTooltip: true, onChange: SET_MASS },
                { type: math-canvas, width: @config.width, height: @config.height, xMin: -1, xMax: 6, yMin: -1, yMax: 3,
                  showAxes: false, showGrid: false, showTickLabels: false,
                  points: [ { x: 2.5, y: 2, label: @entity.stageLabel, color: @entity.starColor, radius: @entity.starRadius } ],
                  bars: @entity.stageBars,
                  readouts: [ { label: "Stage", value: @entity.stageLabel }, { label: "Mass", value: (str/concat @entity.initialMass " M☉") }, { label: "End state", value: @entity.pathEndLabel } ],
                  interactive: @config.interactive, animate: false },
                { type: typography, variant: body, content: @entity.narration }
              ] }
          ]
        })
    }

    listens {
      AstroStellarTransport.LEARN_RESET -> LEARN_RESET
      AstroStellarTransport.LEARN_STEP -> LEARN_STEP
      AstroStellarTransport.LEARN_UPDATED -> LEARN_UPDATED
      MODE_SELECTED {
        mode : string
      }
        @description "Lab router broadcast naming the active mode; this instrument renders when the mode equals matchMode, otherwise renders null."
        @tier "domain"
      SET_MASS {
        value : number
      }
        @description "Learner set the initial stellar mass, via slider or a preset button."
        @tier "domain"
      LEARN_STEP {
        steps : int
      }
        @description "One step of the transport clock or Step button (from the composed std-learn-transport trait); advances the star to its next life-cycle stage, same as the old Next Stage button."
        @tier "domain"
      LEARN_RESET {
      }
        @description "Transport Reset broadcast (from the composed std-learn-transport trait); returns the star to its first life-cycle stage."
        @tier "domain"
      LEARN_UPDATED {
        running : boolean
        steps : int
      }
        @description "Transport state broadcast on load and Run/Pause toggle (from the composed std-learn-transport trait); repaints the full shell so the strip's Run/Pause label and step caption stay fresh."
        @tier "domain"
    }

    emits {
      STELLAR_UPDATED -> external {
        initialMass : number
        currentStageIndex : number
        stageLabel : string
        pathEndLabel : string
        narration : string
      }
        @description "The star's life-cycle state after each learner action — a composed listener (readout, grader) can subscribe; a harmless no-op when the atom runs standalone."
        @synonyms "stellar update, life-cycle stage, star mass change, stage advance"
        @tier "domain"
    }

    config {
      matchMode : string = ""
        @label "Match Mode"
        @description "When composed behind a lab router, the MODE_SELECTED mode value this instrument responds to. Empty string means standalone — render immediately on INIT."
        @tier "presentation"
      initialMass : number = 1
        @label "Initial Stellar Mass"
        @description "Starting stellar mass in solar masses; determines which life-cycle path the star follows."
        @synonyms "solar mass, star mass, initial mass"
        @tier "domain"
      massPresets : [number] = [0.5, 1, 8, 20]
        @label "Mass Presets"
        @description "Quick-pick starting masses, in solar masses, shown as preset buttons."
        @tier "domain"
      stellarPaths : [AstroStellarPath] = [
        { maxMass: 7.9, endLabel: "White Dwarf", stages: [
