app std-math-sinewave "2.0.0"
"Sine wave lab instrument — y = A·sin(kx − φ) sampled fresh from amplitude/frequency/phase config on every step, plotted against a dashed un-shifted reference curve, phase advancing by π/8 each step. The Step/Run-Pause/Reset transport and the step clock come from the std-learn-transport atom (MathSineWaveTransport); the phase-advance sampling lives in the sibling MathSineWaveSim trait, which transitions directly on the transport's LEARN_STEP (advances phase by π/8 and resamples both curves), LEARN_RESET (reseeds phase to 0 and resamples from config), and LEARN_UPDATED (full-shell repaint) broadcasts — delivered by the same bare-event cascade the lab routers use — and owns the full-shell scene render (the transport strip is embedded via @trait.MathSineWaveTransport — one render authority per shared entity). The wave never terminates — done stays false always, there is no rest/completion condition to detect. Standalone by default; behind a lab router set matchMode and it renders only when MODE_SELECTED matches."
orbital MathSineWaveEngineOrbital {
  type MathSample = {
    x : number!
    y : number!
  }
  type MathCurve = {
    label : string
    color : string
    dash : string
    samples : [MathSample]
  }

  entity MathSineWaveState [runtime, shared] {
    id : string!
    active : boolean = false
    title : string
    running : boolean = false
    steps : int = 0
    elapsedMs : number = 0
    done : boolean = false
    phase : number = 0
    curves : [MathCurve]
    narration : string
  }

  uses LearnTransport from "std/behaviors/std-learn-transport"

  trait MathSineWaveTransport = LearnTransport.traits.LearnTransportSim -> MathSineWaveState {
    config {
      title: "Sine Wave"
      stepIntervalMs: 550
    }
  }

  trait MathSineWaveSim -> @rebindable MathSineWaveState [interaction, instance] {
    initial: idle

    state idle {
      INIT -> idle when (== @config.matchMode "")
        (set @entity.done false)
        (let (
            (xs (array/map (array/range 0 @config.sampleCount) (fn idx (+ @config.xMin (* @idx (/ (- @config.xMax @config.xMin) (- @config.sampleCount 1)))))))
            (mainSamples (array/map @xs (fn x { x: @x, y: (* @config.amplitude (math/sin (* @config.frequency @x))) })))
          )
          (do
            (set @entity.phase 0)
            (set @entity.curves [
              { label: "wave", color: "#2563eb", samples: @mainSamples },
              { label: "reference", color: "#9ca3af", dash: "dashed", samples: @mainSamples }
            ])
            (set @entity.narration "phase φ = 0 rad — press Step to advance")
          ))
        (render-ui main {
          type: box
          padding: md
          children: [
            { type: stack, direction: vertical, gap: md, children: [
                @trait.MathSineWaveTransport,
                { type: math-canvas, width: @config.width, height: @config.height, xMin: @config.xMin, xMax: @config.xMax, yMin: @config.yMin, yMax: @config.yMax, showTickLabels: true, curves: @entity.curves },
                { type: typography, variant: body, content: @entity.narration }
              ] }
          ]
        })
        (emit SINEWAVE_UPDATED { curves: @entity.curves, phase: @entity.phase, narration: @entity.narration })

      MODE_SELECTED -> idle when (== ?mode @config.matchMode)
        (set @entity.done false)
        (let (
            (xs (array/map (array/range 0 @config.sampleCount) (fn idx (+ @config.xMin (* @idx (/ (- @config.xMax @config.xMin) (- @config.sampleCount 1)))))))
            (mainSamples (array/map @xs (fn x { x: @x, y: (* @config.amplitude (math/sin (* @config.frequency @x))) })))
          )
          (do
            (set @entity.phase 0)
            (set @entity.curves [
              { label: "wave", color: "#2563eb", samples: @mainSamples },
              { label: "reference", color: "#9ca3af", dash: "dashed", samples: @mainSamples }
            ])
            (set @entity.narration "phase φ = 0 rad — press Step to advance")
          ))
        (render-ui main {
          type: box
          padding: md
          children: [
            { type: stack, direction: vertical, gap: md, children: [
                @trait.MathSineWaveTransport,
                { type: math-canvas, width: @config.width, height: @config.height, xMin: @config.xMin, xMax: @config.xMax, yMin: @config.yMin, yMax: @config.yMax, showTickLabels: true, curves: @entity.curves },
                { type: typography, variant: body, content: @entity.narration }
              ] }
          ]
        })
        (emit SINEWAVE_UPDATED { curves: @entity.curves, phase: @entity.phase, narration: @entity.narration })

      LEARN_STEP -> idle when (and (== @entity.active true) (not (== @entity.done true)))
        (let (
            (step 0.39269908169872414)
            (twoPi 6.283185307179586)
            (rawPhase (+ @entity.phase @step))
            (crossed (>= @rawPhase @twoPi))
            (newPhase (math/mod @rawPhase @twoPi))
            (displayPhase (/ (math/round (* @newPhase 100)) 100))
            (xs (array/map (array/range 0 @config.sampleCount) (fn idx (+ @config.xMin (* @idx (/ (- @config.xMax @config.xMin) (- @config.sampleCount 1)))))))
            (mainSamples (array/map @xs (fn x { x: @x, y: (* @config.amplitude (math/sin (- (* @config.frequency @x) @newPhase))) })))
            (refSamples (array/map @xs (fn x { x: @x, y: (* @config.amplitude (math/sin (* @config.frequency @x))) })))
          )
          (do
            (set @entity.phase @newPhase)
            (set @entity.curves [
              { label: "wave", color: "#2563eb", samples: @mainSamples },
              { label: "reference", color: "#9ca3af", dash: "dashed", samples: @refSamples }
            ])
            (set @entity.narration (if @crossed "one full period traversed — phase wrapped past 2π" (str/concat "phase φ = " (str/concat "" @displayPhase) " rad")))
          ))
        (render-ui main {
          type: box
          padding: md
          children: [
            { type: stack, direction: vertical, gap: md, children: [
                @trait.MathSineWaveTransport,
                { type: math-canvas, width: @config.width, height: @config.height, xMin: @config.xMin, xMax: @config.xMax, yMin: @config.yMin, yMax: @config.yMax, showTickLabels: true, curves: @entity.curves },
                { type: typography, variant: body, content: @entity.narration }
              ] }
          ]
        })
        (emit SINEWAVE_UPDATED { curves: @entity.curves, phase: @entity.phase, narration: @entity.narration })

      LEARN_RESET -> idle when (== @entity.active true)
        (set @entity.done false)
        (let (
            (xs (array/map (array/range 0 @config.sampleCount) (fn idx (+ @config.xMin (* @idx (/ (- @config.xMax @config.xMin) (- @config.sampleCount 1)))))))
            (mainSamples (array/map @xs (fn x { x: @x, y: (* @config.amplitude (math/sin (* @config.frequency @x))) })))
          )
          (do
            (set @entity.phase 0)
            (set @entity.curves [
              { label: "wave", color: "#2563eb", samples: @mainSamples },
              { label: "reference", color: "#9ca3af", dash: "dashed", samples: @mainSamples }
            ])
            (set @entity.narration "phase φ = 0 rad — press Step to advance")
          ))
        (render-ui main {
          type: box
          padding: md
          children: [
            { type: stack, direction: vertical, gap: md, children: [
                @trait.MathSineWaveTransport,
                { type: math-canvas, width: @config.width, height: @config.height, xMin: @config.xMin, xMax: @config.xMax, yMin: @config.yMin, yMax: @config.yMax, showTickLabels: true, curves: @entity.curves },
                { type: typography, variant: body, content: @entity.narration }
              ] }
          ]
        })
        (emit SINEWAVE_UPDATED { curves: @entity.curves, phase: @entity.phase, narration: @entity.narration })

      LEARN_UPDATED -> idle when (== @entity.active true)
        (render-ui main {
          type: box
          padding: md
          children: [
            { type: stack, direction: vertical, gap: md, children: [
                @trait.MathSineWaveTransport,
                { type: math-canvas, width: @config.width, height: @config.height, xMin: @config.xMin, xMax: @config.xMax, yMin: @config.yMin, yMax: @config.yMax, showTickLabels: true, curves: @entity.curves },
                { type: typography, variant: body, content: @entity.narration }
              ] }
          ]
        })
    }

    listens {
      MathSineWaveTransport.LEARN_RESET -> LEARN_RESET
      MathSineWaveTransport.LEARN_STEP -> LEARN_STEP
      MathSineWaveTransport.LEARN_UPDATED -> LEARN_UPDATED
      MODE_SELECTED {
        mode : string
      }
        @description "Lab router broadcast naming the active mode; this instrument renders when the mode equals matchMode, otherwise renders null."
        @tier "domain"
      LEARN_STEP {
        steps : int
      }
        @description "One step of the transport clock or Step button (from the composed std-learn-transport trait); advances the phase by π/8 and resamples both curves."
        @tier "domain"
      LEARN_RESET {
      }
        @description "Transport Reset broadcast (from the composed std-learn-transport trait); reseeds the phase to 0 and resamples both curves from config."
        @tier "domain"
      LEARN_UPDATED {
        running : boolean
        steps : int
      }
        @description "Transport state broadcast on load and Run/Pause toggle (from the composed std-learn-transport trait); repaints the full shell so the strip's Run/Pause label and step caption stay fresh."
        @tier "domain"
    }

    emits {
      SINEWAVE_UPDATED -> external {
        curves : [MathCurve]
        phase : number
        narration : string
      }
        @description "The waveform and phase after each step/toggle/reset — a composed listener (readout, grader) can subscribe; a harmless no-op when the atom runs standalone."
        @synonyms "sine wave, trig function, oscillation, periodic function"
        @tier "domain"
    }

    config {
      matchMode : string = ""
        @label "Match Mode"
        @description "When composed behind a lab router, the MODE_SELECTED mode value this instrument responds to. Empty string means standalone — render immediately on INIT."
        @tier "presentation"
      amplitude : number = 5
        @label "Amplitude"
        @description "Peak displacement A of y = A·sin(kx − φ); scales the wave's height."
        @synonyms "amplitude, height, peak value, A"
        @tier "domain"
      frequency : number = 1
        @label "Frequency"
        @description "Angular frequency k of y = A·sin(kx − φ); higher values compress the wave horizontally."
        @synonyms "frequency, angular frequency, k, wavenumber"
        @tier "domain"
      sampleCount : number = 41
        @label "Sample Count"
        @description "Number of x samples used to draw each curve between xMin and xMax."
        @tier "presentation"
      xMin : number = -9
        @label "X Min"
        @description "Left edge of the sampled/plotted domain."
        @tier "presentation"
      xMax : number = 9
        @label "X Max"
        @description "Right edge of the sampled/plotted domain."
        @tier "presentation"
      yMin : number = -6
        @label "Y Min"
        @description "Bottom edge of the plotted range."
        @tier "presentation"
      yMax : number = 6
        @label "Y Max"
        @description "Top edge of the plotted range."
        @tier "presentation"
      width : number = 600
        @label "Width"
        @description "Canvas width in pixels."
        @tier "presentation"
      height : number = 400
        @label "Height"
        @description "Canvas height in pixels."
        @tier "presentation"
    }
  }

  page "/math-sinewave" as MathSineWaveEnginePage -> MathSineWaveTransport, MathSineWaveSim
}

app std-snake "1.0.0"

"Snake — the classic grid game, composed by atomic design.
Mechanics live in atoms: std-snake-loop (domain atom, body/dir/food/score/result
authority) + std-fx-particles (std substrate, pickup floaters). Rendering is
composed from std UI molecules: ui-canvas (drawables + keyMap) inside
ui-game-shell (HUD chip + game-over overlay). This orbital only binds the
pieces to one shared entity and routes raw key events into domain intents
(TURN / RESTART)."
;; @capabilities "snake game, grid movement, tick loop, food pickup, score, collision detection, keyboard steering, restart"

orbital SnakeOrbital {
  uses Loop from "almadar-behaviors/std-snake-loop"
  uses Fx from "std/behaviors/std-fx-particles"
  uses Shell from "std/behaviors/ui-game-shell"
  uses Hud from "std/behaviors/ui-game-hud"
  uses Canvas from "std/behaviors/ui-canvas"

  type Cell = {
    x : number!
    y : number!
  }
  type Fx = {
    id : string!
    type : string!
    x : number!
    z : number
    y : number
    message : string
    ttl : number!
    maxTtl : number
    bornAt : number
    space : string
    effect : string
    color : string
    size : number
    vx : number
    vy : number
    vz : number
    particleCount : number
  }

  entity SnakeGame [runtime, shared] {
    id : string!
    body : [Cell] = []
    dir : string = "right"
    food : Cell = { x: 10, y: 6 }
    score : number = 0
    result : string = "none"
    fx : [Fx] = []
  }

  trait SnakeMechanic = Loop.traits.SnakeLoop -> SnakeGame {
    config {
      running: true
      gridWidth: 16
      gridHeight: 12
    }

    listens {
      TURN { dir : string }
      RESTART { id : string }
      SnakePlay.RESTART -> RESTART
      SnakePlay.TURN -> TURN
    }
  }

  trait SnakeFx = Fx.traits.FxParticles -> SnakeGame {
    config { running: true }

    listens {
      BURST { particles : [Fx] }
      RESTART { }
      SnakeMechanic.BURST -> BURST
      SnakePlay.RESTART -> RESTART
    }
  }

  trait SnakeHud = Hud.traits.GameHudRender -> SnakeGame {
    config {
      stats: [ { label: "Score", value: @entity.score } ]
    }
  }

  trait SnakeCanvas = Canvas.traits.CanvasRender -> SnakeGame {
    config {
      mode: "2d"
      projection: "flat"
      camera: { zoom: 0.42, pos: { x: (- (/ 16 2) 0.5), y: (- (/ (+ 12 1) 2) 0.5) } }
      worldWidth: 16
      worldHeight: (+ 12 1)
      backgroundColor: "#0f172a"
      showMinimap: false
      keyMap: { ArrowUp: "UP", KeyW: "UP", ArrowDown: "DOWN", KeyS: "DOWN", ArrowLeft: "LEFT", KeyA: "LEFT", ArrowRight: "RIGHT", KeyD: "RIGHT", Space: "PLAY_AGAIN", Enter: "PLAY_AGAIN" }
      drawables: (array/concat
        [ { type: draw-shape, shape: rect, position: { x: 0, y: 0 }, width: 16, height: 12, stroke: "#475569", strokeWidth: 2 }
          { type: draw-shape, shape: "cell", position: { x: (object/get @entity.food x), y: (object/get @entity.food y) }, fill: "#ef4444" }
          { type: draw-shape, shape: "cell", position: { x: (object/get (array/first @entity.body) x), y: (object/get (array/first @entity.body) y) }, fill: "#4ade80" } ]
        (array/concat
          (array/map (array/drop @entity.body 1) (fn c { type: draw-shape, shape: "cell", position: { x: (object/get @c x), y: (object/get @c y) }, fill: "#16a34a" }))
          [ { type: draw-fx-layer, items: @entity.fx, tickMs: 500, presets: [ { type: "pickup", color: "#facc15", color2: "#4ade80", shape: "spark", size: 0.4, count: 5, glow: 0.1 } ] } ]))
    }
  }

  trait SnakeShell = Shell.traits.GameShellRender -> SnakeGame {
    config {
      appName: "Snake"
      theme: "game-sci-fi-dark"
      hud: @trait.SnakeHud
      overlay: (if (== @entity.result "lost")
        { type: game-menu, title: "GAME OVER", subtitle: (str/concat "Score: " @entity.score), options: [ { id: "again", label: "Play Again", event: "PLAY_AGAIN", variant: "primary" } ] }
        null)
      children: [@trait.SnakeCanvas]
    }
  }

  trait SnakePlay -> SnakeGame [interaction, instance] {
    initial: playing

    state playing {
      INIT -> playing
        (render-ui main { type: stack, children: [@trait.SnakeShell] })

      UP -> playing
        (emit TURN { dir: "up" })

      DOWN -> playing
        (emit TURN { dir: "down" })

      LEFT -> playing
        (emit TURN { dir: "left" })

      RIGHT -> playing
        (emit TURN { dir: "right" })

      PLAY_AGAIN -> playing
        (emit RESTART { id: "snake" })
    }

    emits {
      UP -> external { id : string }
      DOWN -> external { id : string }
      LEFT -> external { id : string }
      RIGHT -> external { id : string }
      RESTART -> external { id : string }
      PLAY_AGAIN -> external { id : string }
      TURN -> external { dir : string! }
    }
  }

  page "/snake" as SnakePage -> SnakeMechanic, SnakeFx, SnakeHud, SnakeCanvas, SnakeShell, SnakePlay
}

app std-algo-quicksort "2.0.0"
"Algorithm-animation engine (algorithm-canvas): Iterative quicksort visualizer — Step performs one Lomuto partition micro-step driven by an explicit range stack, with pointers on the partition's low bound, the pivot and the scan cursor, a fill range over the current partition and bracket ranges over the top pending stack ranges. The Step/Run-Pause/Reset transport and the step clock come from the std-learn-transport atom (QuickSortTransport); the partition logic lives in the sibling QuickSortSim trait, which transitions directly on the transport's LEARN_STEP (applies one Lomuto partition micro-step), LEARN_RESET (reseeds bars and stack from config), and LEARN_UPDATED (full-shell repaint) broadcasts — delivered by the same bare-event cascade the lab routers use — and owns the full-shell scene render (the transport strip is embedded via @trait.QuickSortTransport — one render authority per shared entity). Standalone by default; behind a lab router set matchMode and it renders only when MODE_SELECTED matches."
orbital QuickSortEngineOrbital {
  type AlgoBar = {
    value : number!
    color : string
    label : string
  }
  type AlgoPointer = {
    index : number!
    label : string
    color : string
  }
  type AlgoRange = {
    from : number!
    to : number!
    kind : "fill" | "bracket"
    label : string
    color : string
  }

  type Range = {
    lo : number!
    hi : number!
  }

  entity QuickScene [runtime, shared] {
    id : string!
    active : boolean = false
    title : string
    running : boolean = false
    steps : int = 0
    elapsedMs : number = 0
    done : boolean = false
    bars : [AlgoBar]
    stack : [Range]
    lo : number = 0
    hi : number = 0
    pivot : number = 0
    si : number = 0
    j : number = 0
    partitioning : boolean = false
    sEmpty : boolean = false
    topLo : number = 0
    topHi : number = 0
    cmpLess : boolean = false
    doSwap : boolean = false
    swapA : number = 0
    swapB : number = 0
    settled : [number]
    pointers : [AlgoPointer]
    ranges : [AlgoRange]
    narration : string
  }

  uses LearnTransport from "std/behaviors/std-learn-transport"

  trait QuickSortTransport = LearnTransport.traits.LearnTransportSim -> QuickScene {
    config {
      title: "Quicksort"
      stepIntervalMs: 350
    }
  }

  trait QuickSortSim -> @rebindable QuickScene [interaction, instance] {
    initial: idle

    state idle {
      INIT -> idle when (== @config.matchMode "")
        (set @entity.bars (array/map @config.values { value: @item, label: (str/concat "" @item), color: "#3b82f6" }))
        (set @entity.stack [ { lo: 0, hi: (- (array/len @config.values) 1) } ])
        (set @entity.lo 0)
        (set @entity.hi 0)
        (set @entity.pivot 0)
        (set @entity.si 0)
        (set @entity.j 0)
        (set @entity.partitioning false)
        (set @entity.done (<= (array/len @config.values) 1))
        (set @entity.settled [])
        (set @entity.pointers [])
        (set @entity.ranges [ { from: 0, to: (- (array/len @config.values) 1), kind: "fill", label: "partition" } ])
        (set @entity.narration "press Step to pop the first range and choose a pivot")
        (render-ui main {
          type: box
          padding: md
          children: [
            { type: stack, direction: vertical, gap: md, children: [
                @trait.QuickSortTransport,
                { type: algorithm-canvas, width: @config.width, height: @config.height, backgroundColor: @config.backgroundColor, bars: @entity.bars, pointers: @entity.pointers, ranges: @entity.ranges },
                { type: typography, variant: body, content: @entity.narration }
              ] }
          ]
        })
        (emit QUICKSORT_UPDATED { bars: @entity.bars, pointers: @entity.pointers, ranges: @entity.ranges, narration: @entity.narration })

      MODE_SELECTED -> idle when (== ?mode @config.matchMode)
        (set @entity.bars (array/map @config.values { value: @item, label: (str/concat "" @item), color: "#3b82f6" }))
        (set @entity.stack [ { lo: 0, hi: (- (array/len @config.values) 1) } ])
        (set @entity.lo 0)
        (set @entity.hi 0)
        (set @entity.pivot 0)
        (set @entity.si 0)
        (set @entity.j 0)
        (set @entity.partitioning false)
        (set @entity.done (<= (array/len @config.values) 1))
        (set @entity.settled [])
        (set @entity.pointers [])
        (set @entity.ranges [ { from: 0, to: (- (array/len @config.values) 1), kind: "fill", label: "partition" } ])
        (set @entity.narration "press Step to pop the first range and choose a pivot")
        (render-ui main {
          type: box
          padding: md
          children: [
            { type: stack, direction: vertical, gap: md, children: [
                @trait.QuickSortTransport,
                { type: algorithm-canvas, width: @config.width, height: @config.height, backgroundColor: @config.backgroundColor, bars: @entity.bars, pointers: @entity.pointers, ranges: @entity.ranges },
                { type: typography, variant: body, content: @entity.narration }
              ] }
          ]
        })
        (emit QUICKSORT_UPDATED { bars: @entity.bars, pointers: @entity.pointers, ranges: @entity.ranges, narration: @entity.narration })

      LEARN_STEP -> idle when (and (== @entity.active true) (not (== @entity.done true)))
        (let (
            (wasActive @entity.partitioning)
            (oldLo @entity.lo)
            (oldHi @entity.hi)
            (oldJ @entity.j)
            (oldSi @entity.si)
            (oldPivot @entity.pivot)
            (jVal (object/get (array/nth @entity.bars @oldJ) value))
            (finishingSwap (and @wasActive (== @oldJ @oldHi)))
            (cmpLessSnap (< @jVal @oldPivot))
          )
          (do
            (set @entity.sEmpty (== (array/len @entity.stack) 0))
            (set @entity.topLo (if @entity.sEmpty 0 (object/get (array/last @entity.stack) lo)))
            (set @entity.topHi (if @entity.sEmpty 0 (object/get (array/last @entity.stack) hi)))
            (set @entity.cmpLess (< (object/get (array/nth @entity.bars @entity.j) value) @entity.pivot))
            (set @entity.doSwap (and @entity.partitioning (or (== @entity.j @entity.hi) @entity.cmpLess)))
            (set @entity.swapA @entity.si)
            (set @entity.swapB (if (== @entity.j @entity.hi) @entity.hi @entity.j))
            (set @entity.bars
              (array/map @entity.bars
                { value: (if (and @entity.doSwap (== @index @entity.swapA)) (object/get (array/nth @entity.bars @entity.swapB) value)
                           (if (and @entity.doSwap (== @index @entity.swapB)) (object/get (array/nth @entity.bars @entity.swapA) value)
                             (object/get @item value)))
                  label: (if (and @entity.doSwap (== @index @entity.swapA)) (str/concat "" (object/get (array/nth @entity.bars @entity.swapB) value))
                           (if (and @entity.doSwap (== @index @entity.swapB)) (str/concat "" (object/get (array/nth @entity.bars @entity.swapA) value))
                             (object/get @item label)))
                  color: (if (array/includes @entity.settled @index) "#22c55e"
                           (if (and (not @entity.partitioning) @entity.sEmpty) "#22c55e"
                             (if (and @entity.partitioning (>= @index @entity.lo) (<= @index @entity.hi))
                               (if (== @index @entity.hi) "#a855f7"
                                 (if (== @index @entity.j) "#f59e0b"
                                   (if (== @index @entity.si) "#fbbf24" "#3b82f6")))
                               "#3b82f6")))
                }))
            (set @entity.stack
              (if (and @entity.partitioning (== @entity.j @entity.hi))
                (array/append (array/append @entity.stack { lo: @entity.lo, hi: (- @entity.si 1) }) { lo: (+ @entity.si 1), hi: @entity.hi })
                (if (and (not @entity.partitioning) (not @entity.sEmpty))
                  (array/dropLast @entity.stack 1)
                  @entity.stack)))
            (set @entity.lo (if @entity.partitioning @entity.lo (if @entity.sEmpty @entity.lo @entity.topLo)))
            (set @entity.hi (if @entity.partitioning @entity.hi (if @entity.sEmpty @entity.hi @entity.topHi)))
            (set @entity.pivot (if @entity.partitioning @entity.pivot
                                 (if (and (not @entity.sEmpty) (< @entity.topLo @entity.topHi))
                                   (object/get (array/nth @entity.bars @entity.topHi) value)
                                   @entity.pivot)))
            (set @entity.si (if @entity.partitioning
                              (if (== @entity.j @entity.hi) @entity.si (if @entity.cmpLess (+ @entity.si 1) @entity.si))
                              (if (and (not @entity.sEmpty) (< @entity.topLo @entity.topHi)) @entity.topLo @entity.si)))
            (set @entity.j (if @entity.partitioning
                             (if (== @entity.j @entity.hi) @entity.j (+ @entity.j 1))
                             (if (and (not @entity.sEmpty) (< @entity.topLo @entity.topHi)) @entity.topLo @entity.j)))
            (set @entity.done (and (not @entity.partitioning) @entity.sEmpty))
            ;; must read the PRE-step j (via let snapshots) — @entity.j was already advanced above,
            ;; so re-reading it here ends the partition one step early and skips the pivot settle
            (set @entity.partitioning (if @wasActive
                                  (if @finishingSwap false true)
                                  (if @entity.sEmpty false (< @entity.topLo @entity.topHi))))
            (set @entity.settled (if @finishingSwap (array/append @entity.settled @oldSi) @entity.settled))
            (set @entity.narration
              (if @entity.done "sorted!"
                (if @finishingSwap (str/concat "settle pivot " @oldPivot " at position " @oldSi)
                  (if @wasActive
                    (if @cmpLessSnap (str/concat @jVal " < " @oldPivot " — advance") (str/concat @jVal " >= " @oldPivot " — advance"))
                    (str/concat "partition [" @entity.lo "," @entity.hi "] around pivot " @entity.pivot)))))
            (set @entity.pointers (if @entity.done [] [ { index: @entity.lo, label: "lo" }, { index: @entity.hi, label: "pivot" }, { index: @entity.j, label: "j" } ]))
            (set @entity.ranges (if @entity.done [] (array/concat
              [ { from: @entity.lo, to: @entity.hi, kind: "fill", label: "partition" } ]
              (array/map (array/takeLast @entity.stack 3) { from: (object/get @item lo), to: (object/get @item hi), kind: "bracket", label: (str/concat "[" (object/get @item lo) "," (object/get @item hi) "]") }))))
          ))
        (render-ui main {
          type: box
          padding: md
          children: [
            { type: stack, direction: vertical, gap: md, children: [
                @trait.QuickSortTransport,
                { type: algorithm-canvas, width: @config.width, height: @config.height, backgroundColor: @config.backgroundColor, bars: @entity.bars, pointers: @entity.pointers, ranges: @entity.ranges },
                { type: typography, variant: body, content: @entity.narration }
              ] }
          ]
        })
        (emit QUICKSORT_UPDATED { bars: @entity.bars, pointers: @entity.pointers, ranges: @entity.ranges, narration: @entity.narration })

      LEARN_RESET -> idle when (== @entity.active true)
        (set @entity.bars (array/map @config.values { value: @item, label: (str/concat "" @item), color: "#3b82f6" }))
        (set @entity.stack [ { lo: 0, hi: (- (array/len @config.values) 1) } ])
        (set @entity.lo 0)
        (set @entity.hi 0)
        (set @entity.pivot 0)
        (set @entity.si 0)
        (set @entity.j 0)
        (set @entity.partitioning false)
        (set @entity.done (<= (array/len @config.values) 1))
        (set @entity.settled [])
        (set @entity.pointers [])
        (set @entity.ranges [ { from: 0, to: (- (array/len @config.values) 1), kind: "fill", label: "partition" } ])
        (set @entity.narration "press Step to pop the first range and choose a pivot")
        (render-ui main {
          type: box
          padding: md
          children: [
            { type: stack, direction: vertical, gap: md, children: [
                @trait.QuickSortTransport,
                { type: algorithm-canvas, width: @config.width, height: @config.height, backgroundColor: @config.backgroundColor, bars: @entity.bars, pointers: @entity.pointers, ranges: @entity.ranges },
                { type: typography, variant: body, content: @entity.narration }
              ] }
          ]
        })
        (emit QUICKSORT_UPDATED { bars: @entity.bars, pointers: @entity.pointers, ranges: @entity.ranges, narration: @entity.narration })

      LEARN_UPDATED -> idle when (== @entity.active true)
        (render-ui main {
          type: box
          padding: md
          children: [
            { type: stack, direction: vertical, gap: md, children: [
                @trait.QuickSortTransport,
                { type: algorithm-canvas, width: @config.width, height: @config.height, backgroundColor: @config.backgroundColor, bars: @entity.bars, pointers: @entity.pointers, ranges: @entity.ranges },
                { type: typography, variant: body, content: @entity.narration }
              ] }
          ]
        })
    }

    listens {
      QuickSortTransport.LEARN_RESET -> LEARN_RESET
      QuickSortTransport.LEARN_STEP -> LEARN_STEP
      QuickSortTransport.LEARN_UPDATED -> LEARN_UPDATED
      MODE_SELECTED {
        mode : string
      }
        @description "Lab router broadcast naming the active mode; this instrument renders when the mode equals matchMode, otherwise renders null."
        @tier "domain"
      LEARN_STEP {
        steps : int
      }
        @description "One step of the transport clock or Step button (from the composed std-learn-transport trait); applies one Lomuto partition micro-step — compares the scan cursor against the pivot, swaps into place, or pops the next range from the stack and chooses a new pivot."
        @tier "domain"
      LEARN_RESET {
      }
        @description "Transport Reset broadcast (from the composed std-learn-transport trait); reseeds the bar array, range stack, and narration from config."
        @tier "domain"
      LEARN_UPDATED {
        running : boolean
        steps : int
      }
        @description "Transport state broadcast on load and Run/Pause toggle (from the composed std-learn-transport trait); repaints the full shell so the canvas and narration stay fresh."
        @tier "domain"
    }

    emits {
      QUICKSORT_UPDATED -> external {
        bars : [AlgoBar]
        pointers : [AlgoPointer]
        ranges : [AlgoRange]
        narration : string
      }
        @description "The bar array, pointers, ranges and narration after each step/toggle/reset — a composed listener (a mirror canvas, a readout) can subscribe; a harmless no-op standalone."
        @synonyms "tick, frame, step, redraw, compare, swap, partition, pivot, quicksort"
        @tier "domain"
    }

    config {
      matchMode : string = ""
        @label "Match Mode"
        @description "When composed behind a lab router, the MODE_SELECTED mode value this instrument responds to. Empty string means standalone — render immediately on INIT."
        @tier "presentation"
      width : number = 600
        @label "Width"
        @description "Canvas width in pixels."
        @tier "presentation"
      height : number = 400
        @label "Height"
        @description "Canvas height in pixels."
        @tier "presentation"
      backgroundColor : string = "#f8fafc"
        @label "Background Color"
        @description "Canvas background color."
        @tier "presentation"
      values : [number] = [5, 2, 8, 1, 9, 3, 7, 4]
        @label "Values"
        @description "Initial unsorted dataset; each bar's height is proportional to its value."
        @tier "presentation"
    }
  }

  page "/algo-quicksort" as QuickSortEnginePage -> QuickSortTransport, QuickSortSim
}

app std-pong "1.0.0"

"Pong — the classic paddle arcade game, composed by atomic design.
Mechanics live in atoms: std-pong-rally (domain atom, ball/paddles/score/result
authority, with a built-in AI opponent) + std-fx-particles (std substrate,
paddle-hit floaters). Rendering is composed from std UI molecules: ui-canvas
(drawables + keyMap) inside ui-game-shell (HUD chip + game-over overlay). This
orbital only binds the pieces to one shared entity and routes raw key events
into domain intents (PADDLE_MOVE / RESTART). Single-player by default: KeyW/KeyS
steer your left paddle and the rally atom's AI drives the right paddle toward
the ball; set the PongMechanic aiEnabled config false for two-player, where
ArrowUp/ArrowDown steer the right paddle by hand. First to 5 wins."
;; @capabilities "pong game, paddle, ball physics, wall bounce, ai opponent, single player, two-player, score, win condition, keyboard steering, restart"

orbital PongOrbital {
  uses Rally from "almadar-behaviors/std-pong-rally"
  uses Fx from "std/behaviors/std-fx-particles"
  uses Shell from "std/behaviors/ui-game-shell"
  uses Hud from "std/behaviors/ui-game-hud"
  uses Canvas from "std/behaviors/ui-canvas"

  type Ball = {
    x : number!
    y : number!
    vx : number!
    vy : number!
  }
  type Fx = {
    id : string!
    type : string!
    x : number!
    z : number
    y : number
    message : string
    ttl : number!
    maxTtl : number
    bornAt : number
    space : string
    effect : string
    color : string
    size : number
    vx : number
    vy : number
    vz : number
    particleCount : number
  }

  entity PongGame [runtime, shared] {
    id : string!
    ball : Ball = { x: 12, y: 7, vx: 1, vy: 1 }
    leftY : number = 5
    rightY : number = 5
    leftScore : number = 0
    rightScore : number = 0
    result : string = "none"
    fx : [Fx] = []
  }

  trait PongMechanic = Rally.traits.PongRally -> PongGame {
    config {
      running: true
      gridWidth: 24
      gridHeight: 14
    }

    listens {
      PADDLE_MOVE { side : string, dy : number }
      RESTART { id : string }
      PongPlay.PADDLE_MOVE -> PADDLE_MOVE
      PongPlay.RESTART -> RESTART
    }
  }

  trait PongFx = Fx.traits.FxParticles -> PongGame {
    config { running: true }

    listens {
      BURST { particles : [Fx] }
      RESTART { }
      PongMechanic.BURST -> BURST
      PongPlay.RESTART -> RESTART
    }
  }

  trait PongHud = Hud.traits.GameHudRender -> PongGame {
    config {
      stats: [ { label: "Left", value: @entity.leftScore } { label: "Right", value: @entity.rightScore } ]
    }
  }

  trait PongCanvas = Canvas.traits.CanvasRender -> PongGame {
    config {
      mode: "2d"
      projection: "flat"
      camera: { zoom: 0.36, pos: { x: (- (/ 24 2) 0.5), y: (- (/ (+ 14 1) 2) 0.5) } }
      worldWidth: 24
      worldHeight: (+ 14 1)
      backgroundColor: "#0f172a"
      showMinimap: false
      keyMap: { KeyW: "LEFT_UP", KeyS: "LEFT_DOWN", ArrowUp: "RIGHT_UP", ArrowDown: "RIGHT_DOWN", Space: "PLAY_AGAIN", Enter: "PLAY_AGAIN" }
      drawables: (array/concat
        [ { type: draw-shape, shape: rect, position: { x: 0, y: 0 }, width: 24, height: 14, stroke: "#475569", strokeWidth: 2 }
          { type: draw-shape, shape: "cell", position: { x: (object/get @entity.ball x), y: (object/get @entity.ball y) }, fill: "#facc15" } ]
        (array/concat
          (array/concat
            (array/map (array/range 3) (fn i { type: draw-shape, shape: "cell", position: { x: 0, y: (+ @entity.leftY @i) }, fill: "#38bdf8" }))
            (array/map (array/range 3) (fn i { type: draw-shape, shape: "cell", position: { x: 23, y: (+ @entity.rightY @i) }, fill: "#f472b6" })))
          [ { type: draw-fx-layer, items: @entity.fx, tickMs: 500, presets: [ { type: "pickup", color: "#f8fafc", color2: "#38bdf8", shape: "spark", size: 0.45, count: 6, glow: 0.14 } ] } ]))
    }
  }

  trait PongShell = Shell.traits.GameShellRender -> PongGame {
    config {
      appName: "Pong"
      theme: "game-sci-fi-dark"
      hud: @trait.PongHud
      overlay: (if (not (== @entity.result "none"))
        { type: game-menu, title: "GAME OVER", subtitle: (str/concat (if (== @entity.result "left") "Left" "Right") " wins"), options: [ { id: "again", label: "Play Again", event: "PLAY_AGAIN", variant: "primary" } ] }
        null)
      children: [@trait.PongCanvas]
    }
  }

  trait PongPlay -> PongGame [interaction, instance] {
    initial: playing

    state playing {
      INIT -> playing
        (render-ui main { type: stack, children: [@trait.PongShell] })

      LEFT_UP -> playing
        (emit PADDLE_MOVE { side: "left", dy: -1 })

      LEFT_DOWN -> playing
        (emit PADDLE_MOVE { side: "left", dy: 1 })

      RIGHT_UP -> playing
        (emit PADDLE_MOVE { side: "right", dy: -1 })

      RIGHT_DOWN -> playing
        (emit PADDLE_MOVE { side: "right", dy: 1 })

      PLAY_AGAIN -> playing
        (emit RESTART { id: "pong" })
    }

    emits {
      LEFT_UP -> external { id : string }
      LEFT_DOWN -> external { id : string }
      RIGHT_UP -> external { id : string }
      RIGHT_DOWN -> external { id : string }
      RESTART -> external { id : string }
      PLAY_AGAIN -> external { id : string }
      PADDLE_MOVE -> external { side : string!, dy : number! }
    }
  }

  page "/pong" as PongPage -> PongMechanic, PongFx, PongHud, PongCanvas, PongShell, PongPlay
}

app std-algo-gameoflife "2.0.0"
"Conway's Game of Life visualizer — an algorithm-canvas grid recomputes every cell's next state from its eight neighbours (underpopulation, survival, overpopulation, reproduction) each step, reporting the generation number and live-cell count. The Step/Run-Pause/Reset transport and the step clock come from the std-learn-transport atom (GameOfLifeTransport); the generation update lives in the sibling GameOfLifeSim trait, which transitions directly on the transport's LEARN_STEP (applies one full-grid generation step), LEARN_RESET (reseeds the starting pattern), and LEARN_UPDATED (full-shell repaint) broadcasts — delivered by the same bare-event cascade the lab routers use — and owns the full-shell scene render (the transport strip is embedded via @trait.GameOfLifeTransport — one render authority per shared entity). This implementation runs forever — done stays false always, there is no extinction/stasis detection. Standalone by default; behind a lab router set matchMode and it renders only when MODE_SELECTED matches."
orbital GameOfLifeEngineOrbital {
  type AlgoCell = {
    row : number!
    col : number!
    value : number
    color : string
    label : string
  }

  entity LifeScene [runtime, shared] {
    id : string!
    active : boolean = false
    title : string
    running : boolean = false
    steps : int = 0
    elapsedMs : number = 0
    done : boolean = false
    cells : [AlgoCell]
    generation : number = 0
    aliveCount : number = 0
    narration : string
  }

  uses LearnTransport from "std/behaviors/std-learn-transport"

  trait GameOfLifeTransport = LearnTransport.traits.LearnTransportSim -> LifeScene {
    config {
      title: "Conway's Game of Life"
      stepIntervalMs: 500
    }
  }

  trait GameOfLifeSim -> @rebindable LifeScene [interaction, instance] {
    initial: idle

    state idle {
      INIT -> idle when (== @config.matchMode "")
        (set @entity.cells @config.cells)
        (set @entity.generation 0)
        (set @entity.done false)
        (set @entity.aliveCount (array/len (array/filter @entity.cells (== (object/get @item value) 1))))
        (set @entity.narration (str/concat "generation 0 — " (str/concat "" @entity.aliveCount) " alive — press Step to advance"))
        (render-ui main {
          type: box
          padding: md
          children: [
            { type: stack, direction: vertical, gap: md, children: [
                @trait.GameOfLifeTransport,
                { type: algorithm-canvas, width: @config.width, height: @config.height, backgroundColor: @config.backgroundColor, cells: @entity.cells },
                { type: typography, variant: body, content: @entity.narration }
              ] }
          ]
        })
        (emit GAMEOFLIFE_UPDATED { cells: @entity.cells, generation: @entity.generation, aliveCount: @entity.aliveCount, narration: @entity.narration })

      MODE_SELECTED -> idle when (== ?mode @config.matchMode)
        (set @entity.cells @config.cells)
        (set @entity.generation 0)
        (set @entity.done false)
        (set @entity.aliveCount (array/len (array/filter @entity.cells (== (object/get @item value) 1))))
        (set @entity.narration (str/concat "generation 0 — " (str/concat "" @entity.aliveCount) " alive — press Step to advance"))
        (render-ui main {
          type: box
          padding: md
          children: [
            { type: stack, direction: vertical, gap: md, children: [
                @trait.GameOfLifeTransport,
                { type: algorithm-canvas, width: @config.width, height: @config.height, backgroundColor: @config.backgroundColor, cells: @entity.cells },
                { type: typography, variant: body, content: @entity.narration }
              ] }
          ]
        })
        (emit GAMEOFLIFE_UPDATED { cells: @entity.cells, generation: @entity.generation, aliveCount: @entity.aliveCount, narration: @entity.narration })

      LEARN_STEP -> idle when (and (== @entity.active true) (not (== @entity.done true)))
        (set @entity.cells
          (array/map @entity.cells
            (let ( (r (object/get @item row)) (c (object/get @item col)) (self (object/get @item value)) )
            (let ( (live (array/len (array/filter @entity.cells
                     (and (<= (math/abs (- (object/get @item row) @r)) 1)
                       (and (<= (math/abs (- (object/get @item col) @c)) 1)
                         (and (== (object/get @item value) 1)
                           (not (and (== (object/get @item row) @r) (== (object/get @item col) @c))))))))) )
            (let ( (next (if (== @self 1)
                           (if (or (== @live 2) (== @live 3)) 1 0)
                           (if (== @live 3) 1 0))) )
            (object/merge @item {
              value: @next
              color: (if (== @next 1) "#22c55e" "#1e293b")
            }))))))
        (set @entity.generation (+ @entity.generation 1))
        (set @entity.aliveCount (array/len (array/filter @entity.cells (== (object/get @item value) 1))))
        (set @entity.narration (str/concat "generation " (str/concat "" @entity.generation) " — " (str/concat "" @entity.aliveCount) " alive"))
        (render-ui main {
          type: box
          padding: md
          children: [
            { type: stack, direction: vertical, gap: md, children: [
                @trait.GameOfLifeTransport,
                { type: algorithm-canvas, width: @config.width, height: @config.height, backgroundColor: @config.backgroundColor, cells: @entity.cells },
                { type: typography, variant: body, content: @entity.narration }
              ] }
          ]
        })
        (emit GAMEOFLIFE_UPDATED { cells: @entity.cells, generation: @entity.generation, aliveCount: @entity.aliveCount, narration: @entity.narration })

      LEARN_RESET -> idle when (== @entity.active true)
        (set @entity.cells @config.cells)
        (set @entity.generation 0)
        (set @entity.done false)
        (set @entity.aliveCount (array/len (array/filter @entity.cells (== (object/get @item value) 1))))
        (set @entity.narration (str/concat "generation 0 — " (str/concat "" @entity.aliveCount) " alive — press Step to advance"))
        (render-ui main {
          type: box
          padding: md
          children: [
            { type: stack, direction: vertical, gap: md, children: [
                @trait.GameOfLifeTransport,
                { type: algorithm-canvas, width: @config.width, height: @config.height, backgroundColor: @config.backgroundColor, cells: @entity.cells },
                { type: typography, variant: body, content: @entity.narration }
              ] }
          ]
        })
        (emit GAMEOFLIFE_UPDATED { cells: @entity.cells, generation: @entity.generation, aliveCount: @entity.aliveCount, narration: @entity.narration })

      LEARN_UPDATED -> idle when (== @entity.active true)
        (render-ui main {
          type: box
          padding: md
          children: [
            { type: stack, direction: vertical, gap: md, children: [
                @trait.GameOfLifeTransport,
                { type: algorithm-canvas, width: @config.width, height: @config.height, backgroundColor: @config.backgroundColor, cells: @entity.cells },
                { type: typography, variant: body, content: @entity.narration }
              ] }
          ]
        })
    }

    listens {
      GameOfLifeTransport.LEARN_RESET -> LEARN_RESET
      GameOfLifeTransport.LEARN_STEP -> LEARN_STEP
      GameOfLifeTransport.LEARN_UPDATED -> LEARN_UPDATED
      MODE_SELECTED {
        mode : string
      }
        @description "Lab router broadcast naming the active mode; this instrument renders when the mode equals matchMode, otherwise renders null."
        @tier "domain"
      LEARN_STEP {
        steps : int
      }
        @description "One step of the transport clock or Step button (from the composed std-learn-transport trait); applies one Game of Life generation update (Conway's rules) to every cell."
        @tier "domain"
      LEARN_RESET {
      }
        @description "Transport Reset broadcast (from the composed std-learn-transport trait); reseeds the grid, generation, and narration from config."
        @tier "domain"
      LEARN_UPDATED {
        running : boolean
        steps : int
      }
        @description "Transport state broadcast on load and Run/Pause toggle (from the composed std-learn-transport trait); repaints the full shell so the strip's Run/Pause label and step caption stay fresh."
        @tier "domain"
    }

    emits {
      GAMEOFLIFE_UPDATED -> external {
        cells : [AlgoCell]
        generation : number
        aliveCount : number
        narration : string
      }
        @description "The grid after each generation — a composed listener (readout, grader) can subscribe; a harmless no-op when the atom runs standalone."
        @synonyms "conway, game of life, cellular automaton, generation, alive, dead"
        @tier "domain"
    }

    config {
      matchMode : string = ""
        @label "Match Mode"
        @description "When composed behind a lab router, the MODE_SELECTED mode value this instrument responds to. Empty string means standalone — render immediately on INIT."
        @tier "presentation"
      width : number = 600
        @label "Width"
        @description "Canvas width in pixels."
        @tier "presentation"
      height : number = 400
        @label "Height"
        @description "Canvas height in pixels."
        @tier "presentation"
      backgroundColor : string = "#0f172a"
        @label "Background Color"
        @description "Canvas background color."
        @tier "presentation"
      cells : [AlgoCell] = [
        { row: 0, col: 0, value: 0, color: "#1e293b", label: "" },
        { row: 0, col: 1, value: 0, color: "#1e293b", label: "" },
        { row: 0, col: 2, value: 0, color: "#1e293b", label: "" },
        { row: 0, col: 3, value: 0, color: "#1e293b", label: "" },
        { row: 0, col: 4, value: 0, color: "#1e293b", label: "" },
        { row: 0, col: 5, value: 0, color: "#1e293b", label: "" },
        { row: 1, col: 0, value: 0, color: "#1e293b", label: "" },
        { row: 1, col: 1, value: 1, color: "#22c55e", label: "" },
        { row: 1, col: 2, value: 1, color: "#22c55e", label: "" },
        { row: 1, col: 3, value: 1, color: "#22c55e", label: "" },
        { row: 1, col: 4, value: 0, color: "#1e293b", label: "" },
        { row: 1, col: 5, value: 0, color: "#1e293b", label: "" },
        { row: 2, col: 0, value: 0, color: "#1e293b", label: "" },
        { row: 2, col: 1, value: 0, color: "#1e293b", label: "" },
        { row: 2, col: 2, value: 0, color: "#1e293b", label: "" },
        { row: 2, col: 3, value: 0, color: "#1e293b", label: "" },
