app std-algo-dijkstra "2.0.0"
"Dijkstra's shortest-path engine on algo-graph-canvas — Step extracts the unvisited node with smallest tentative distance and relaxes its incident edges (badges show running distances, infinity symbol until reached); the settled shortest-path tree accumulates edge state tree while the edges just relaxed flash relaxed; a horizontal slot strip renders the priority queue ordered by distance, head highlighted. The Step/Run-Pause/Reset transport and the step clock come from the std-learn-transport atom (DijkstraTransport); the Dijkstra relaxation lives in the sibling DijkstraSim trait, which transitions directly on the transport's LEARN_STEP (extracts the min and relaxes its incident edges), LEARN_RESET (reseeds distances and the graph from config), and LEARN_UPDATED (full-shell repaint) broadcasts — delivered by the same bare-event cascade the lab routers use — and owns the full-shell scene render (the transport strip is embedded via @trait.DijkstraTransport — one render authority per shared entity). Standalone by default; behind a lab router set matchMode and it renders only when MODE_SELECTED matches."
orbital DijkstraEngineOrbital {
  type NodeSeed = {
    id : string!
    label : string
    x : number
    y : number
  }
  type WeightedEdge = {
    from : string!
    to : string!
    weight : number!
  }
  type Dist = {
    id : string!
    d : number!
    from : string
  }
  type Badge = {
    text : string!
  }
  type GraphNodeOut = {
    id : string!
    label : string
    state : "unvisited" | "frontier" | "current" | "visited" | "goal" | "path"
    x : number
    y : number
    badge : Badge
  }
  type GraphEdgeOut = {
    from : string!
    to : string!
    directed : boolean
    weight : number
    state : "default" | "tree" | "relaxed" | "candidate" | "path"
  }
  type PQSlot = {
    value : string
    state : "empty" | "filled" | "highlight"
  }

  entity DijkstraScene [runtime, shared] {
    id : string!
    active : boolean = false
    title : string
    running : boolean = false
    steps : int = 0
    elapsedMs : number = 0
    done : boolean = false
    dist : [Dist]
    visited : [string]
    cur : string = ""
    distU : number = 0
    relaxIds : [string]
    nodes : [GraphNodeOut]
    edges : [GraphEdgeOut]
    slots : [PQSlot]
    narration : string
  }

  uses LearnTransport from "std/behaviors/std-learn-transport"

  trait DijkstraTransport = LearnTransport.traits.LearnTransportSim -> DijkstraScene {
    config {
      title: "Dijkstra's Shortest Path"
      stepIntervalMs: 500
    }
  }

  trait DijkstraSim -> @rebindable DijkstraScene [interaction, instance] {
    initial: idle

    state idle {
      INIT -> idle when (== @config.matchMode "")
        (set @entity.done false)
        (set @entity.dist (array/map @config.nodeSeeds (fn ns
          { id: (object/get @ns id), d: (if (== (object/get @ns id) @config.start) 0 9999), from: "" })))
        (set @entity.visited [])
        (set @entity.cur "")
        (set @entity.distU 0)
        (set @entity.relaxIds [])
        (set @entity.nodes (array/map @config.nodeSeeds (fn ns
          { id: (object/get @ns id), label: (object/get @ns label), x: (object/get @ns x), y: (object/get @ns y),
            state: (if (== (object/get @ns id) @config.start) "frontier" "unvisited"),
            badge: { text: (if (== (object/get @ns id) @config.start) "0" "∞") } })))
        (set @entity.edges (array/map @config.edges (fn e
          { from: (object/get @e from), to: (object/get @e to), directed: false, weight: (object/get @e weight), state: "default" })))
        (set @entity.slots [ { value: (str/concat @config.start ":0"), state: "highlight" } ])
        (set @entity.narration (str/concat "Press Step to extract-min and relax " @config.start "'s neighbors, or Run to auto-play."))
        (render-ui main {
          type: box
          padding: md
          children: [
            { type: stack, direction: vertical, gap: md, children: [
                @trait.DijkstraTransport,
                { type: algo-graph-canvas, width: @config.width, height: @config.height, backgroundColor: @config.backgroundColor, layout: manual, nodes: @entity.nodes, edges: @entity.edges },
                { type: algorithm-canvas, width: @config.width, height: 120, backgroundColor: @config.backgroundColor, slots: @entity.slots, slotOrientation: horizontal },
                { type: typography, variant: body, content: @entity.narration }
              ] }
          ]
        })
        (emit DIJKSTRA_UPDATED { nodes: @entity.nodes, edges: @entity.edges, dist: @entity.dist, narration: @entity.narration })

      MODE_SELECTED -> idle when (== ?mode @config.matchMode)
        (set @entity.done false)
        (set @entity.dist (array/map @config.nodeSeeds (fn ns
          { id: (object/get @ns id), d: (if (== (object/get @ns id) @config.start) 0 9999), from: "" })))
        (set @entity.visited [])
        (set @entity.cur "")
        (set @entity.distU 0)
        (set @entity.relaxIds [])
        (set @entity.nodes (array/map @config.nodeSeeds (fn ns
          { id: (object/get @ns id), label: (object/get @ns label), x: (object/get @ns x), y: (object/get @ns y),
            state: (if (== (object/get @ns id) @config.start) "frontier" "unvisited"),
            badge: { text: (if (== (object/get @ns id) @config.start) "0" "∞") } })))
        (set @entity.edges (array/map @config.edges (fn e
          { from: (object/get @e from), to: (object/get @e to), directed: false, weight: (object/get @e weight), state: "default" })))
        (set @entity.slots [ { value: (str/concat @config.start ":0"), state: "highlight" } ])
        (set @entity.narration (str/concat "Press Step to extract-min and relax " @config.start "'s neighbors, or Run to auto-play."))
        (render-ui main {
          type: box
          padding: md
          children: [
            { type: stack, direction: vertical, gap: md, children: [
                @trait.DijkstraTransport,
                { type: algo-graph-canvas, width: @config.width, height: @config.height, backgroundColor: @config.backgroundColor, layout: manual, nodes: @entity.nodes, edges: @entity.edges },
                { type: algorithm-canvas, width: @config.width, height: 120, backgroundColor: @config.backgroundColor, slots: @entity.slots, slotOrientation: horizontal },
                { type: typography, variant: body, content: @entity.narration }
              ] }
          ]
        })
        (emit DIJKSTRA_UPDATED { nodes: @entity.nodes, edges: @entity.edges, dist: @entity.dist, narration: @entity.narration })

      LEARN_STEP -> idle when (and (== @entity.active true) (not (== @entity.done true)))
        (set @entity.distU
          (array/min (array/map (array/filter @entity.dist (fn dd (not (array/includes @entity.visited (object/get @dd id))))) (fn dd (object/get @dd d)))))
        (set @entity.cur
          (object/get (array/first (array/filter @entity.dist (fn dd (and (not (array/includes @entity.visited (object/get @dd id))) (== (object/get @dd d) @entity.distU))))) id))
        (set @entity.visited (array/append @entity.visited @entity.cur))
        (set @entity.relaxIds
          (array/map
            (array/filter @entity.edges (fn e
              (and (or (== (object/get @e from) @entity.cur) (== (object/get @e to) @entity.cur))
                   (not (array/includes @entity.visited (if (== (object/get @e from) @entity.cur) (object/get @e to) (object/get @e from)))))))
            (fn e (if (== (object/get @e from) @entity.cur) (object/get @e to) (object/get @e from)))))
        (set @entity.narration
          (let (
              (hasRelax (> (array/len @entity.relaxIds) 0))
              (nb0 (if @hasRelax (array/first @entity.relaxIds) ""))
              (edge0 (if @hasRelax (array/first (array/filter @entity.edges (fn e (or (and (== (object/get @e from) @entity.cur) (== (object/get @e to) @nb0)) (and (== (object/get @e from) @nb0) (== (object/get @e to) @entity.cur)))))) null))
              (w0 (if @hasRelax (object/get @edge0 weight) 0))
              (old0 (if @hasRelax (object/get (array/first (array/filter @entity.dist (fn dd (== (object/get @dd id) @nb0)))) d) 0))
            )
            (str/concat "settle " @entity.cur " at " (str/concat "" @entity.distU)
              (if @hasRelax
                (if (< (+ @entity.distU @w0) @old0)
                  (str/concat " — relax " @entity.cur "→" @nb0 ": " (str/concat "" @entity.distU) "+" (str/concat "" @w0) " < " (if (< @old0 9999) (str/concat "" @old0) "∞") " — update")
                  (str/concat " — relax " @entity.cur "→" @nb0 ": " (str/concat "" @entity.distU) "+" (str/concat "" @w0) " ≥ " (str/concat "" @old0) " — keep"))
                " — settled, no unvisited neighbors"))))
        (set @entity.dist
          (array/map @entity.dist (fn row
            (let ( (nid (object/get @row id)) (dcur (object/get @row d)) )
              (let ( (matches (array/filter @entity.edges (fn e (or (and (== (object/get @e from) @entity.cur) (== (object/get @e to) @nid)) (and (== (object/get @e from) @nid) (== (object/get @e to) @entity.cur)))))) )
                (if (== (array/len @matches) 0)
                  @row
                  (let ( (ww (object/get (array/first @matches) weight)) )
                    (if (< (+ @entity.distU @ww) @dcur)
                      (object/merge @row { d: (+ @entity.distU @ww), from: @entity.cur })
                      @row))))))))
        (set @entity.nodes
          (array/map @entity.nodes (fn nd
            (let ( (drec (array/first (array/filter @entity.dist (fn dd (== (object/get @dd id) (object/get @nd id)))))) )
              (object/merge @nd {
                state: (if (== (object/get @nd id) @entity.cur) "current"
                         (if (array/includes @entity.visited (object/get @nd id)) "visited"
                           (if (< (object/get @drec d) 9999) "frontier" "unvisited"))),
                badge: { text: (if (< (object/get @drec d) 9999) (str/concat "" (object/get @drec d)) "∞") }
              })))))
        (set @entity.edges
          (array/map @entity.edges (fn ed
            (let ( (ef (object/get @ed from)) (et (object/get @ed to)) )
              (object/merge @ed {
                state: (if (or
                             (and (array/includes @entity.visited @et) (== (object/get (array/first (array/filter @entity.dist (fn dd (== (object/get @dd id) @et)))) from) @ef))
                             (and (array/includes @entity.visited @ef) (== (object/get (array/first (array/filter @entity.dist (fn dd (== (object/get @dd id) @ef)))) from) @et)))
                           "tree"
                           (if (or (and (== @ef @entity.cur) (array/includes @entity.relaxIds @et))
                                   (and (== @et @entity.cur) (array/includes @entity.relaxIds @ef)))
                             "relaxed"
                             "default"))
              })))))
        (set @entity.slots
          (array/map
            (array/sort (array/filter @entity.dist (fn dd (and (not (array/includes @entity.visited (object/get @dd id))) (< (object/get @dd d) 9999)))) "d" "asc")
            (fn dd { value: (str/concat (object/get @dd id) ":" (str/concat "" (object/get @dd d))), state: (if (== @index 0) "highlight" "filled") })))
        (set @entity.done
          (== (array/len (array/filter @entity.dist (fn dd (and (not (array/includes @entity.visited (object/get @dd id))) (< (object/get @dd d) 9999))))) 0))
        (render-ui main {
          type: box
          padding: md
          children: [
            { type: stack, direction: vertical, gap: md, children: [
                @trait.DijkstraTransport,
                { type: algo-graph-canvas, width: @config.width, height: @config.height, backgroundColor: @config.backgroundColor, layout: manual, nodes: @entity.nodes, edges: @entity.edges },
                { type: algorithm-canvas, width: @config.width, height: 120, backgroundColor: @config.backgroundColor, slots: @entity.slots, slotOrientation: horizontal },
                { type: typography, variant: body, content: @entity.narration }
              ] }
          ]
        })
        (emit DIJKSTRA_UPDATED { nodes: @entity.nodes, edges: @entity.edges, dist: @entity.dist, narration: @entity.narration })

      LEARN_RESET -> idle when (== @entity.active true)
        (set @entity.done false)
        (set @entity.dist (array/map @config.nodeSeeds (fn ns
          { id: (object/get @ns id), d: (if (== (object/get @ns id) @config.start) 0 9999), from: "" })))
        (set @entity.visited [])
        (set @entity.cur "")
        (set @entity.distU 0)
        (set @entity.relaxIds [])
        (set @entity.nodes (array/map @config.nodeSeeds (fn ns
          { id: (object/get @ns id), label: (object/get @ns label), x: (object/get @ns x), y: (object/get @ns y),
            state: (if (== (object/get @ns id) @config.start) "frontier" "unvisited"),
            badge: { text: (if (== (object/get @ns id) @config.start) "0" "∞") } })))
        (set @entity.edges (array/map @config.edges (fn e
          { from: (object/get @e from), to: (object/get @e to), directed: false, weight: (object/get @e weight), state: "default" })))
        (set @entity.slots [ { value: (str/concat @config.start ":0"), state: "highlight" } ])
        (set @entity.narration (str/concat "Press Step to extract-min and relax " @config.start "'s neighbors, or Run to auto-play."))
        (render-ui main {
          type: box
          padding: md
          children: [
            { type: stack, direction: vertical, gap: md, children: [
                @trait.DijkstraTransport,
                { type: algo-graph-canvas, width: @config.width, height: @config.height, backgroundColor: @config.backgroundColor, layout: manual, nodes: @entity.nodes, edges: @entity.edges },
                { type: algorithm-canvas, width: @config.width, height: 120, backgroundColor: @config.backgroundColor, slots: @entity.slots, slotOrientation: horizontal },
                { type: typography, variant: body, content: @entity.narration }
              ] }
          ]
        })
        (emit DIJKSTRA_UPDATED { nodes: @entity.nodes, edges: @entity.edges, dist: @entity.dist, narration: @entity.narration })

      LEARN_UPDATED -> idle when (== @entity.active true)
        (render-ui main {
          type: box
          padding: md
          children: [
            { type: stack, direction: vertical, gap: md, children: [
                @trait.DijkstraTransport,
                { type: algo-graph-canvas, width: @config.width, height: @config.height, backgroundColor: @config.backgroundColor, layout: manual, nodes: @entity.nodes, edges: @entity.edges },
                { type: algorithm-canvas, width: @config.width, height: 120, backgroundColor: @config.backgroundColor, slots: @entity.slots, slotOrientation: horizontal },
                { type: typography, variant: body, content: @entity.narration }
              ] }
          ]
        })
    }

    listens {
      DijkstraTransport.LEARN_RESET -> LEARN_RESET
      DijkstraTransport.LEARN_STEP -> LEARN_STEP
      DijkstraTransport.LEARN_UPDATED -> LEARN_UPDATED
      MODE_SELECTED {
        mode : string
      }
        @description "Lab router broadcast naming the active mode; this instrument renders when the mode equals matchMode, otherwise renders null."
        @tier "domain"
      LEARN_STEP {
        steps : int
      }
        @description "One step of the transport clock or Step button (from the composed std-learn-transport trait); applies one Dijkstra extract-min-and-relax."
        @tier "domain"
      LEARN_RESET {
      }
        @description "Transport Reset broadcast (from the composed std-learn-transport trait); reseeds the graph, distance table, and narration from config."
        @tier "domain"
      LEARN_UPDATED {
        running : boolean
        steps : int
      }
        @description "Transport state broadcast on load and Run/Pause toggle (from the composed std-learn-transport trait); repaints the full shell so the strip's Run/Pause label and step caption stay fresh."
        @tier "domain"
    }

    emits {
      DIJKSTRA_UPDATED -> external {
        nodes : [GraphNodeOut]
        edges : [GraphEdgeOut]
        dist : [Dist]
        narration : string
      }
        @description "The graph and distance table after each step/reset — a composed listener (readout, grader) can subscribe; a harmless no-op when the atom runs standalone."
        @synonyms "dijkstra, shortest path, relax, settle, priority queue, greedy, weighted graph"
        @tier "domain"
    }

    config {
      matchMode : string = ""
        @label "Match Mode"
        @description "When composed behind a lab router, the MODE_SELECTED mode value this instrument responds to. Empty string means standalone — render immediately on INIT."
        @tier "presentation"
      start : string = "A"
        @label "Start Node"
        @description "Id of the source node Dijkstra measures distances from; seeded to distance 0."
        @tier "domain"
      width : number = 600
        @label "Width"
        @description "Canvas width in pixels."
        @tier "presentation"
      height : number = 400
        @label "Height"
        @description "Canvas height in pixels."
        @tier "presentation"
      backgroundColor : string = "#f8fafc"
        @label "Background Color"
        @description "Canvas background color."
        @tier "presentation"
      nodeSeeds : [NodeSeed] = [
        { id: "A", label: "A", x: 300, y: 60 },
        { id: "B", label: "B", x: 150, y: 160 },
        { id: "C", label: "C", x: 450, y: 160 },
        { id: "D", label: "D", x: 90, y: 300 },
        { id: "E", label: "E", x: 240, y: 300 },
        { id: "F", label: "F", x: 400, y: 300 },
        { id: "G", label: "G", x: 520, y: 300 }
      ]
        @label "Node Seeds"
        @description "Graph vertices — id/label/manual x,y position; the algorithm recolors them via state, not these seeds."
        @synonyms "vertices, nodes, graph"
        @tier "domain"
      edges : [WeightedEdge] = [
        { from: "A", to: "B", weight: 4 },
        { from: "A", to: "C", weight: 3 },
        { from: "B", to: "C", weight: 1 },
        { from: "B", to: "D", weight: 5 },
        { from: "C", to: "D", weight: 6 },
        { from: "C", to: "E", weight: 8 },
        { from: "D", to: "E", weight: 2 },
        { from: "D", to: "F", weight: 7 },
        { from: "E", to: "F", weight: 3 },
        { from: "E", to: "G", weight: 9 },
        { from: "F", to: "G", weight: 4 }
      ]
        @label "Weighted Edges"
        @description "Undirected weighted adjacency the relaxation reads; also the single source of the drawn edges — the weight label renders automatically."
        @synonyms "adjacency, weights, graph edges"
        @tier "domain"
    }
  }

  page "/algo-dijkstra" as DijkstraEnginePage -> DijkstraTransport, DijkstraSim
}
